window.__D("text/likkutei-sichot/c133",{"p":[[1300201262,"ער פסק׳נט (ווי די דיעה²⁵) אז „קטן מאימתי בא לעולם הבא כו׳ משעה שנימול״.\nע״פ הנ״ל יש לומר, אז דאס איז פאר־בונדן מיט א גאר פריערדיקן מקור — תרגום יונתן הנ״ל אויף „יולדו על ברכי יוסף״ — „כד אתילידו גזירינון יוסף״ — קומט אויס, אז דער ברית („גזירינון״) איז דער זמן פון „אתילידו״. ולכאורה, דער זמן הברית איז טאקע בסמיכות צו לידה, אבער ניט „כד אתילידו״?\nוע״פ דברי אדה״ז הנ״ל איז פאר־שטאנדיק — דעמאלט איז די כניסת נפש הקדושה בגוף, וואס איז דוגמת לידה.\nז. נאך אן ענין אין הלכה וואס מ׳קען אַרויסנעמען פון תרגום יונתן הנ״ל:\nס׳איז א מנהג ישראל²⁶ אז מ׳זאל ניט מכבד זיין דעמזעלבן מענטשן מיט סנדקאות ביי צווי ברידער. און דער טעם דערפון: מילה ווערט פארגליכן צו עבודת הקטורת, און ביי קטורת שטייט²⁷ „מעולם לא שנה אדם בה״²⁶.\nפרעגט מען²⁸ אויף דעם פון דעם תרגום יונתן: עס שטייט דאך דא אז „בני מכיר״, „גזירינון יוסף״, אז יוסף איז געווען דער סנדק ביי בני מכיר — לשון רבים?\nויש לומר, אז פון דעם איז א סמך צו דברי החתם סופר²⁹, אז א מרא דאתרא קען זיין סנדק ביי מערערע קינדער פון די זעלבע עלטערן — ובדוגמת הקטרת, וואס דער דין פון „חדשים לקטורת״³⁰ איז נאר בנוגע אנדערע כהנים, אבער ניט בשייכות צו א כהן גדול, וואס האט געקענט מקטיר זיין קטורת ווען נאר ער האט געוואלט³¹.\nועד״ז יוסף, וויבאלד ער איז געווען „השליט על הארץ״³² — (בדוגמת) א מרא דאתרא.\nח. פון תרגום אונקלוס ופרש״י קען מען אפלערנען פון דעם פסוק א דין אין הלכות תלמוד תורה:\nפון דעם פסוק³³ „והודעתם לבניך ולבני בניך״ לערנט מען אפ³⁴ א חיוב צו לערנען תורה ניט נאר מיט בנו נאר אויך מיט בן בנו. וועגן בן בן בנו (אן אור־אייניקל) אבער איז דער דין³⁵, אז ער איז מחוייב מיט זיי לערנען נאר אין פאל ווען ער איז (א „חכם״ וואס איז) מחוייב צו לערנען מיט תלמידים בכלל (וואס דאן דארף ער מקדים זיין „יוצאי ירכו לתלמידים אחרים״). משא״כ אויב אין שטאט זיינען פאראן „גדולים בחכמה ממנו״ וואס דאמאלס איז ער ניט מחוייב צו לערנען מיט תלמידים (בכלל), איז אויפן עלטער זיידן ניטא קיין חיוב אז ער זאל לערנען מיט זיין אור־אייניקל.",[["25","25","סנהדרין קי, ב. וכן משמע בשו״ע יו״ד סרס״ג ס״ה. וראה לקו״ש שם ע׳ 801 הערה 10."],["26","26","רמ״א יו״ד סרס״ה סי״א."],["27","27","יומא כו, א. רמב״ם הל׳ תמידין ומוספין פ״ד ה״ז."],["28","28","הגהות יד שאול לשו״ע יו״ד שם. ועיי״ש תירוצו עפמ״ש בנודע ביהודה מהד״ק יו״ד ספ״ז."],["29","29","שו״ת חאו״ח סי׳ קנח־ט."],["30","30","לשון המשנה יומא שם. הובא ברמב״ם הנ״ל."],["31","31","יומא יד, א. רמב״ם הל׳ כלי המקדש פ״ה הי״ב."],["32","32","מקץ מב, ו."],["33","33","ואתחנן ד, ט."],["34","34","קידושין ל, א. רמב״ם הל׳ ת״ת פ״א ה״ב. טושו״ע יו״ד סרמ״ה ס״ג. הל׳ ת״ת לאדה״ז פ״א ס״ח."],["35","35","עיין בכל זה — הל׳ ת״ת לאדה״ז שם סעיף ח־ט. וש״נ."]]],[1300201263,"לויט תרגום אונקלוס ופרש״י אבער, אז יוסף האט מגדל געווען די בני מכיר בן מנשה — וואס בפשטות מיינט דאס אויך (ובעיקר³⁶) אז ער האט מיט זיי געלערנט תורה³⁷ — איז משמע ניט אזוי:\nבפשטות איז משמע, אז יוסף איז ניט געווען מחוייב צו לערנען מיט תלמידים בכלל, ווייל (א) יהודה האט דארט אנגעפירט א ישיבה — „ואת יהודה שלח גו׳ להורות לפניו גושנה״³⁸, און ס׳איז מסתבר אז יהודה (וואס האט די אלע יארן אנגעפירט א ישיבה) איז געווען „גדול בחכמה ממנו״³⁹. (ב) וויבאלד אז יוסף איז געווען משנה למלך און פארנומען מיט עניני המדינה פון ארץ מצרים כולל אויך יעקב וביתו — ובלשון ההלכה עוסק בצרכי צבור באמונה — איז ער פטור⁴⁰ פון צו לערנען מיט תלמידים⁴¹:\nפארוואס־זשע האט יוסף אליין געלערנט מיט בני מכיר⁴², בני בן בנו⁴³?\nזעט מען דערפון, אז רש״י — בפירושו על התורה — האלט, אז אויך אן עלטער־זיידן איז דא א חיוב צו לערנען תורה מיט זיינע אור־אייניקלעך (ווי א זיידע מיט אייניקלעך)⁴⁴. און דעריבער האט יוסף אליין געלערנט מיט זיי תורה.\nט. פון דעם האט מען אויך א הוראה למעשה⁴⁵, אז בשעת א איד איז זוכה צו דערלעבן אור־אייניקלעך דארף ער מיט זיי אליין לערנען תורה. און אויב ער אליין קען מיט זיי ניט לערנען — ווייל ער האט ניט קיין כח, אדער ער איז דערצו ניט מסוגל וכיו״ב — דארף ער געבן א גרויסן סכום⁴⁶ אויף אויסצוהאלטן די ישיבה אין וועלכע עס לערנען זיינע אור־אייניקלעך.\nובפרט ע״פ מחז״ל⁴⁷ (בנוגע צו",[["36","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091039\" data-slug=\"likkutei-sichot\" data-id=\"1300091039\">לקו״ש ח״ט ע׳ 39</a> הערה 31."],["37","37","מה שלא נעשה כל זה ע״י אביהם וכו׳ — מובן בפשטות שאינה דומה יכולת יוסף השליט על הארץ ליכולתם; וכן בנוגע לתורה (ובפרט ע״פ פרש״י (וישב לז, ג) כל מה שלמד כו׳)."],["38","38","ויגש מו, כח ובפרש״י שם (מתנחומא וב״ר עה״פ)."],["39","39","אבל ראה הערה 37."],["40","40","להעיר דעוסק בצ״צ דוחה לימוד התורה כו׳ — שהרי תורתו אומנתו מפסיק לק״ש (או״ח סק״ו) ועוסק בצ״צ לא מפסיק (או״ח ס״ע). וראה שמו״ר פ״ו, ב (וש״נ): חכם המתעסק בצ״צ כו׳ וכולן נשתכחו ממני כו׳. סנה׳ (יז, א): הטל עליהן צ״צ והן כלין מאליהן. ובכל אופן צ״ע בירושלמי ברכות (רפ״ה. רמב״ם הל׳ תפלה פ״ה ה״ח) „העוסק בצ״צ כעוסק בדת״י״ (ולא יותר מזה). וכן צ״ע בשו״ע אדה״ז או״ח סו״ס צג (ועיין בפמ״ג שם) שלא פירש שאפילו תורתו אומנתו — עוסק בצ״צ עדיף."],["41","41","ראה הל׳ ת״ת לאדה״ז שם בקו״א סק״א (ע׳ 4 [1652]), דגם בבן בנו צ״ע במי שאין לו פנאי אם נפטר מחמת עסק פרנסתו (ולא דמי לאביו כו׳), ע״ש."],["42","42","ובפרט שאין לו ליקח המצוה ממכיר אביהם שמחוייב בזה לכל הדיעות (ראה לקו״ש ח״ט שם), אבל ראה הערה 37."],["43","43","להעיר מרש״י פרשתנו (מח, א) דאפרים הי׳ רגיל לפני יעקב בתלמוד."],["44","44","ראה ש״ך יו״ד ר״ס רמה בשם הכס״מ (ריש הל׳ ת״ת) „ואפשר דגם לבן בנו חייב להשכיר לו מלמד והוא הדין לבן בן בנו״. וכבר העירו (המקנה קידושין שם. „קובץ״ וטורי אבן לרמב״ם שם) שבכס״מ שם איתא רק „ובן בן בנו נ״ל פשוט דקודם לבן חבירו״, ולא קאי בחיוב לשכור לו מלמד (ההבדל השני שברמב״ם שם — ע״ש בכס״מ). וראה הל׳ ת״ת לאדה״ז שם ס״ח־ט. קו״א הנ״ל בארוכה. ואכ״מ."],["45","45","אף שפסק הלכה (בהל׳ ת״ת שם) אינו כן — מ״מ מקום להחמיר כו׳, ובפרט שכ״ה דעת הש״ך (ועוד)."],["46","46","כמו לדיעה הא׳ (הל׳ ת״ת שם ס״ח) גבי בן בנו, שבזה „כל אדם צריך להחמיר לעצמו״ (שם סוס״ט)."],["47","47","תענית ה, ב."]]],[1300201264,"יעקב׳ן): „מה זרעו בחיים אף הוא בחיים״ (וואס „זרעו״ מיינט דאך ניט נאר בנים ובני בנים, נאר כל יוצאי חלציו, אויך בני בן בנו) — דארף ער טאן כל התלוי בו בכדי אז יוצאי חלציו זאלן זיין בחיים האמיתיים, לערנען תורה — אויך ווייל אין דעם באשטייט זיין אייגענער חיות — „אף הוא בחיים״.\n(משיחת ש״פ ויחי תשכ״ה)\n---"],[1300201265,"הוספות\n8\nא ) מאמרים ושיחות\nמוצאי שמת \"ת - עשרה בטבת , ה'ת של \"ח\nב ) שיחות\nג ) מכתבים"],[1300201266,"הוספות 8 מאמרים ושיחות\nמוצאי שמת \" ת -עשרה בטבת\nהית של \"ח"],[1300201267,"מפתח מוצאי שמח \"כ מאמר\n.,................ .. ... .. ..... .. ... ....\n255\nשיחה\n.......................................\n260\nמוצא יש \"פ בראשית\nמאמר . . . , . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n262\n.........,,.. ..... . .. ...... . .,.. .......\n266 שיחה מוצאי ש\"פ נח\n.,..................... ...............\n................ .. . .... . . ... .. .. ... . . .\n281\nמאמר\n... ............... ............. . .......\n295\nשיחה\n... ... ..........., .. . .., .....,. .. .....\n,\n301\nמוצא יש \"פ חיי שרה\nמאמר . . . . . , . . . . . . , . . . . . . . . . . . . . . . . . . . . , . . . . .\n315 , 323 מאמר שיחה מוצאי , , 276 ש\" פלך שיחה\n......... .. .. ... . .. .., . .. ...... ...... .\nאיר לעשרת בטבת\nמאמר . . . . . . . . . . . . . . . . . , . . . . . . . . . . . . . . . . . . . . .\n347\n.................. ,..,............. ....\n352\nיים עשרה בטבת . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .\n360\nשיחה"],[1300201268,"להבין ענין שמחת תורה, וידוע הדיוק בזה¹ מה שאופן השמחה (דשמחת תורה) הוא שלוקחים ספר תורה כפי שהיא כרוכה ומכוסה במפה² ומרקדין עמה. דעם היות שבתורה כתיב³ כי היא חכמתכם ובינתכם גו׳ מ״מ אופן שמחה זו הוא לא ע״י לימוד ועיון כ״א ע״י ריקוד דוקא. שלכן השמחה דשמחת תורה היא אצל כל ישראל, גם אצל פשוטים ביותר שאין שייכים להשגה והבנה [ויתרה מזו, שבעת השמחה וריקודים דהקפות נמשכים (ווערן צוגעצויגן) גם כאלו שבשאר ימי השנה אין הקשר וההתאחדות שלהם עם [עניני] התורה, כמו שרואים במוחש]. וענין זה (שהשמחה דשמחת תורה היא בכל אחד מישראל) מתבטא גם בזה שמרקדין עם ספר תורה — תורה שבכתב דוקא, שאפילו זה שלא ידע מאי קאמר מברך ברכת התורה כשקורא בתושב״כ⁴. ומכיון שזה מה שמברך ברכת התורה הוא ע״פ ציווי תורת אמת, הרי פשוט שכן היא המציאות, שגם זה שלא ידע מאי קאמר ממשיך אוא״ס ועד עצמות ומהות (נותן התורה) בהתורה שלומד. גם ידוע⁵ הדיוק למה עושין שמח״ת בשמע״צ (ובחו״ל ביו״ט שני דשמע״צ), דלכאורה הי׳ צ״ל בחגה״ש זמן מתן תורתינו.\nב) ומובא הביאור בזה⁶ ע״פ מה דאיתא במדרש⁷ ראוי׳ היתה העצרת של חג שתהא רחוקה חמשים יום כנגד העצרת של פסח, אלא עצרת של חג ע״י שהן יוצאין מן הקיץ לחורף לית ביומייהו דיזלון וייתון, משל למה״ד למלך שהיו לו בנות הרבה, מהן נשואות למקום קרוב ומהן נשואות למקום רחוק, יום אחד באו כולן לשאול שלום המלך אביהם, אמר המלך אלו שנשואות במקום קרוב אית בעונתן למיזל ולמיתי, ואילין שנשואות במקום",[["1","1","ד״ה ביוהשמע״צ תרפ״ט. ד״ה עץ חיים תרצ״ט. ד״ה להבין ענין שמחת תש״ה ותש״ו."],["2","2","שאז אין שייך ללמוד אותה. ובפרט ע״פ מרז״ל (גיטין ס, ב) דברים שבכתב אי אתה רשאי לאומרן בע״פ."],["3","3","ואתחנן ד, ו."],["4","4","הל׳ ת״ת לאדה״ז פ״ב סי״ב־יג. וש״נ."],["5","5","אוה״ת שמע״צ ע׳ א׳תשעט ואילך. ד״ה ביוהשמע״צ תרפ״ט ותש״ו."],["6","6","ד״ה ביוהשמע״צ שם."],["7","7","שהש״ר פ״ז, ב (ב)."]]],[1300201269,"רחוק לית בעונתן למיזל ולמיתי, עד דאינון כולן אצלי הכא נעביד כולן חד יו״ט ונחדי עמן, כך עצרת של פסח עד דאינון נפקין מחורף לקיץ אמר הקב״ה אית ביומא למיזל ולמיתי, אבל עצרת של חג ע״י שהן יוצאין מהקיץ לחורף כו׳ אמר הקב״ה לית ביומא למיזל ולמיתי אלא עד דאינון הכא נעביד כולן חד יו״ט ונחדי. וזהו מה שעושין שמח״ת בשמע״צ, כי ה״יום אחד״ שבו באים כל הבנות [בנות ציון וירושלים, היינו נש״י⁸] לשאול שלום המלך אביהם קאי⁹ על יום הכפורים, ולאח״ז אומר נעביד כולן חד יו״ט ונחדי, הוא⁹ שמח״ת (שנקבע בשמע״צ), שהוא „חד יו״ט״ בדוגמת ה״יום אחד״ דיוהכ״פ.\nג) ויובן זה ע״פ מה שנת״ל (ד״ה בסוכות תשבו⁹*) שכל המועדים דחודש תשרי הם בבחי׳ של אחת. דהנה על ר״ה ארז״ל¹⁰ מצות היום בשופר. היינו, דזה מה שהיום דר״ה הוא חלוק משאר המועדים הוא במצוה אחת (איין און איינציקע מצוה), מצות שופר. ובמצוה זו גופא כותב הרמב״ם¹¹ שהיא גזירת הכתוב למעלה מטעם. דהגם שהמצוה דשופר גם מרמזת על ענינים הכי נעלים בענין התשובה (כמו שממשיך הרמב״ם¹¹ רמז יש בדבר כו׳) מ״מ ענינה הוא גזירת הכתוב למעלה מטעם. ועד״ז הוא גם בנוגע ליוהכ״פ [סיום העשרת ימים שבין ר״ה ליוהכ״פ], שהיא בחי׳ אחת דכל הג׳ בחי׳ דעולם שנה נפש. שהעבודה המיוחדת דיוהכ״פ היא בקודש הקדשים בחי׳ אחת דעולם (מקום), ביום דיוהכ״פ שנקרא¹² בשם אחת בשנה, בחי׳ אחת דשנה (זמן), ונעשית ע״י כה״ג [אלא שהכה״ג עושה זה בתור שלוחם של כל ישראל] דכתיב¹³ בי׳ ויבדל אהרן להקדישו קודש קדשים, בחי׳ אחת דנפש. ועד״ז הוא גם בנוגע לסוכות, שבענין הסוכה [שמצות ישיבה בסוכה היא במשך כל שבעת ימי הסוכות, מרגע הראשון שבהתחלתם] מודגש ענין האחדות (בחי׳ אחת) דכל ישראל כמרז״ל¹⁴ ראוים כל ישראל לישב בסוכה אחת. וכמו״כ הוא גם במצות נטילת ד׳ מינים [שענינה הוא להמשיך המקיף (דסוכה אחת) בפנימיות¹⁵], שבכל אחד מד׳ מינים אלו ניכר",[["8","8","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381155\" data-slug=\"likkutei-torah\" data-id=\"4001381155\">לקו״ת שה״ש ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381218\" data-slug=\"likkutei-torah\" data-id=\"4001381218\">כב, ב</a>. אוה״ת שה״ש ע׳ פט ואילך."],["9","9","סד״ה ביוהשמע״צ תרפ״ט, סד״ה להבין ענין שמחת תש״ו. 9*) תשל״ח (סה״מ — מלוקט ח״א (ע׳ רמה) קה״ת, ברוקלין, תשמ״ז)."],["10","10","משנה ר״ה כו, ב."],["11","11","הל׳ תשובה פ״ג, ה״ד."],["12","12","אחרי טז, לד."],["13","13","דה״א כג, יג."],["14","14","סוכה כז, ב."],["15","15","סידור רסה, סע״א ואילך. המשך תרס״ו ס״ע לב. ובכ״מ."]]],[1300201270,"ומודגש ענין האחדות, ובפרט באתרוג, שבו מודגש ענין האחדות עוד יותר [שלכן בסדר הד׳ מינים שבכתוב¹⁶ (שגם סדר בתורה הוא תורה) ההתחלה היא מאתרוג פרי עץ הדר], דזה מה שאתרוג נקרא בכתוב בשם פרי עץ הדר הוא לפי שדר באילנו משנה לשנה¹⁷, היינו שהוא סובל את שינויי ד׳ האוירים שבמשך השנה, ועד אשר (לא רק שהוא סובל את כל האוירים, אלא) הוא גדל מהם. ומענין האחדות שבאתרוג נמשך גם זה בשאר הג׳ מינים, שלכן הענין דהדר שבג׳ המינים למדים מאתרוג¹⁸. ונוסף לזה שכל אחד מהד׳ מינים מורה על ענין האחדות, הנה המצוה בנטילת ד׳ מינים היא לאחד את כל ד׳ המינים, שמורים על ד׳ הסוגים שבבנ״י¹⁹, שיהי׳ וייעשו כולם אגודה אחת לעשות רצונך בלבב שלם.\nד) והנה בכדי שיוכל להיות ההתאחדות האמתית (ובת קיימא) של כל הד׳ סוגים דישראל, הוא ע״י התשובה. דהנה ענין התשובה הוא למעלה מהתחלקות, שלכן היא בשעתא חדא וברגע חדא²⁰. דזהו ההפרש שבין לוחות הראשונות (ענין התורה מצ״ע) ללוחות השניות (ענין תורה ע״י תשובה), שבכדי לקבל לוחה״ר הי׳ משה בהר ארבעים יום, נוסף על ההכנה דשבעה שבועות תספר לך שהי׳ לפנ״ז²¹. משא״כ בלוחות השניות, הרי הארבעים יום שהי׳ משה בהר הוא (בעיקר) בכדי לפעול שיתרצה הקב״ה לישראל בשמחה ובלב שלם²², ולאח״ז ניתנו הלוחות בשעתא חדא. והנה ענין זה [מה שהתשובה היא בשעתא חדא וברגע חדא] מדגיש שענין התשובה הוא למעלה מכל מדידה והגבלה²³, מפני שתשובה אמיתית מגעת (דערנעמט) בפנימיות ועצמות הנפש, שבחינה זו היא למעלה מהתחלקות, בחי׳ אחת (בשעתא חדא וברגע חדא) דנפש. וזהו מה שע״י התשובה נעשה ההתאחדות של כל הסוגים דישראל, מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, ובאופן דאתם",[["16","16","אמור כג, מ."],["17","17","סוכה לה, א."],["18","18","סוכה לא, א. שו״ע אדה״ז סתרמ״ה ס״ב. ואף ששם הוא בנוגע להדר כפשוטו — הרי ע״פ הביאור שגדל מהם מובן שגם הדר כפשוטו גדל מהם."],["19","19","ויק״ר פ״ל, יב."],["20","20","זח״א קכט, סע״א."],["21","21","ראה ר״ן סוף מס׳ פסחים שענין ז׳ השבועות שמיצי״מ עד מ״ת הוא מקור ענין שבעה שבועות תספר לך. וראה זח״ג (צז, ב) שביצי״מ הייתה צ״ל ההכנה והעבודה דז׳ שבועות קודם לקבלת התורה."],["22","22","פרש״י תשא לג, יא."],["23","23","ראה לקו״ת שבת שובה סה, א."]]],[1300201271,"נצבים כולכם גו׳, נצבים מלשון נצב²⁴ מלך²⁵, שישראל נעשים מלכים און בעלי בתים על המציאות דעולם, מתחיל מזה שהם נכתבים ונחתמים בכתיבה וחתימה טובה לשנה טובה ומתוקה בטוב הנראה והנגלה למטה מעשרה טפחים גם בענינים הגשמיים, מכיון שמצד בחי׳ זו אין שייך לחלק בין רוחניות לגשמיות ובין מעלה למטה, און דאס נעמט דורך את כל סדר ההשתלשלות וגם מה שלמעלה מסדר ההשתלשלות.\nוזהו״ע יום אחד באו כולן לשאול שלום המלך אביהם כו׳ נעביד כולן חד יו״ט ונחדי עמן, יום אחד (שבו באו כולן לשאול שלום המלך אביהם) הוא יוהכ״פ, אחת דשנה (וגם אחת דעולם ודנפש), ומזה נמשך אח״כ נעביד כולן חד יו״ט כו׳ שקאי על שמח״ת, שהוא ג״כ יום אחד (חד יו״ט), בחי׳ אחת.\nה) והנה ההתעוררות דבחי׳ אחת שבנפש שלמעלה מהתחלקות צריך להמשיכה בהדרגות דנפש שבבחי׳ התחלקות [ובדוגמת מה שהתעוררות זו צריכה להיות קשורה בעשי׳ גשמית, וכמו בהעשי׳ דישיבה בסוכה, נטילת ד׳ מינים, ריקוד ברגלים]. דזהו מה שלאחרי שנאמר אתם נצבים גו׳ כולכם גו׳ שכל ישראל הם באופן ד״כולכם״²⁶ מצד בחי׳ אחת שבהם, מונה אח״כ כל העשר סוגים בפרטיות, מראשיכם שבטיכם עד חוטב עציך ושואב מימיך, היינו שהענין דכולכם (בחי׳ אחת) דישראל צריך להיות ניכר בהם גם כמו שהם בבחי׳ התחלקות. וכמו שהוא בנפש עד״ז הוא גם בשנה, שבחי׳ יום אחד דיוהכ״פ ודשמח״ת פועלת און פירט אן מיט אלע ימי השנה (מתחיל מאסרו חג), שבכל פרטי עשיותיו (בכל מעשיך ובכל דרכיך), ניכר אז ער איז אט ערשט געקומען מיום אחד דיוהכ״פ ודשמח״ת. וענין זה הוא במשך כל השנה כולה, דאף שכבר עברו כמה וכמה ימים שבועות וחדשים מיוהכ״פ ושמח״ת, אעפ״כ ההתעוררות דיום אחד אינה נחלשת כלל ובתקפה עומדת, מכיון שבאה מבחי׳ שלמעלה מענין ההתחלקות והשינויים, בחי׳ אני²⁷ הוי׳ לא שניתי. וע״י שהבחי׳ דיום אחד שלמעלה מהתחלקות נמשכת בכל ימי השנה שבבחי׳ התחלקות ושינויים, עי״ז נעשה עילוי גם בהבחי׳ דיום אחד, ע״ד מה שנת״ל בענין פרי עץ הדר אשר לא רק שהוא סובל כל שינויי האוירים אלא שהוא גדל מהם.",[["24","24","לשון הכתוב — מ״א כב, מח."],["25","25","אוה״ת נצבים ע׳ א׳רא."],["26","26","ראה לקו״ת ר״פ נצבים."],["27","27","לשון הכתוב — מלאכי ג, ו."]]],[1300201272,"ו) ויהי רצון, שכל הנ״ל יתקיים בכל אחד ואחת בתוככי כלל ישראל, שתהי׳ שנה טובה ומבורכת בטוב הנראה והנגלה למטה מעשרה טפחים, בבני חיי ומזוני ובכולם רויחי, הן בבני חיי ומזוני כפשוטם והן בבני חיי ומזוני ברוחניות²⁸ (שמהם משתלשלים הענינים כפשוטם²⁹), אשר מתוך שמחה וטוב לבב תהי׳ מיד לאחרי שמח״ת העבודה דויעקב הלך לדרכו³⁰ גם בנוגע לעניני הרשות [שענין ויעקב הלך לדרכו שלאחרי יוהכ״פ³¹ הוא ב״דרכו״ בענין המצוות, שהרי בד׳ הימים שבין יוהכ״פ לסוכות כל ישראל עסוקים במצוות³². משא״כ ענין ויעקב הלך לדרכו שלאחרי שמח״ת הוא ב״דרכו״ גם בעניני הרשות], שבכל יום ויום, הן בימי החול ועאכו״כ בשבת ויו״ט (כולל גם ר״ה ויוהכ״פ), זיינען דורכגענומען כל עניניו, הן ענינים הכללים והן ענינים הפרטים, בנקודה העיקרית והפנימית דפנימיות ועצמות הנשמה, שהיא קשורה בפנימיות ועצמות א״ס ב״ה.\nז) ומכיון שזה בא משמחת תורה, ששמחה פורצת כל הגדרים, למעלה ממדידה והגבלה³³, הרי זה פורץ ומבטל כל הגדרים וההגבלות דגלות הפנימי, וכן הגדרים וההגבלות דגלות כפשוטו, וזוכים שבקרוב ממש יהי׳ ותחזינה עינינו בשובך לציון ברחמים, בגאולה האמיתית והשלימה ע״י משיח צדקנו, יבוא ויוליכנו קוממיות לארצנו במהרה בימינו ממש, ויבנה³⁴ ביהמ״ק במקומו ויקבץ נדחי ישראל וכו׳ (ועד אשר) אז³⁵ אהפוך אל עמים שפה ברורה וגו׳ ולעבדו³⁶ שכם אחד, והיתה³⁷ לה׳ המלוכה.",[["28","28","להעיר מחנוך לנער בסופו. אוה״ת להצ״צ ד״ה והוי׳ פקד (בראשית כ״ד ע׳ 1510 ואילך)."],["29","29","ע״ד המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ״ג</a>."],["30","30","לשון הכתוב ויצא לב, ב. וראה שיחת אחש״פ תרצ״ה (נדפסה בסה״מ תשי״א ע׳ 240)."],["31","31","וככה תרל״ז רפצ״ו."],["32","32","ויק״ר פ״ל, ז."],["33","33","ראה ד״ה שמח תשמח תרנ״ז ע׳ 49 (סה״מ תרנ״ז ע׳ רכג) ואילך."],["34","34","רמב״ם הל׳ מלכים ספי״א."],["35","35","צפני׳ ג, ט."],["36","36","בצפני׳ שם: לעבדו (בלא וא״ו). אבל ברמב״ם שם (ועוד): ולעבדו (בוא״ו). וראה הערה במכתב י״ג תשרי תשל״ו*."],["37","37","עובדי׳ א, כא. *) לקו״ש חי״ד ע׳ 414. המו״ל."]]],[1300201273,"א. אזוי ווי מצד א סיבה רעדט מען נאך הבדלה, קען מען נוצן אויך אזוינע דרכים וואס גיבן איבער דאס וואס מ׳רעדט אויך למקומות רחוקים\n— רחוקים בגשמיות, אבער (זעלבסט־פארשטענדליך) קרובים ברוחניות, און ביי אידן איז דאך דאס (רוחניות) דער עיקר, ווארום ס׳איז דאך עושים נשמתם עיקר וגופם טפל ווי דער אלטער רבי זאגט אין תניא¹ —\nוואס דורך דערויף ווערט א קשר און א פארבונדנקייט און א התאחדות צווישן די אלע וואס הערן, ווארום מ׳הערט דאך דעם זעלבן ענין.\nובפרט נאך אז דאס רעדט זיך וועגן אן ענין פון תורה, וואס תורה ווערט דאך אנגערופן „תורה אחת״, מצד דערויף וואס זי איז געגעבן פון „הוי׳ אחד״, און געגעבן געווארן צו „גוי אחד בארץ״, ווי דער אלטער רבי טייטשט אפ² אז דער ענין פון „אחד״ בא אידן איז אפילו ווען זיי געפינען זיך „בארץ״ (בא בעלי עסקים אויף א כשר׳ן אופן, ווי דאס איז די הנהגה פון זבולון, תומכי תורה, ביז אפילו בא די וואס זיינען נאך (דערווייל) ווייט פון דער הנהגה),\nאיז אין די רגעים וואס מען הערט, ווערן אלע פארבונדן דורך דברי אלקים חיים, דורך אן ענין פון תורה, ווארום עס ווערן דאך גע׳חזר׳ט דברים הנאמרים פון רבותינו נשיאינו נשיאי ישראל.\nב. נאך אן ענין ועיקרי: ווייבאלד דער קשר ווערט אויפגעטאן דורך תורה, און אין תורה איז דאך אן עיקר גדול דער „ברכו בתורה תחלה״³, אז מ׳איז ממשיך [„ברכו״ מלשון המשכת בריכה״ת] דעם נותן התורה אין תורה⁴, וואס דארט איז ניט שייך קיין התחלקות — איז ווייבאלד אז אין דעם ענין וואס פאראיינציקט זיי איז ניטא אינגאנצן דער גדר פון התחלקות, דעריבער, איז אויך זייער פאראיינציקונג אין אזא אופן שלמעלה מגדר התחלקות.\nובפרט נאך אז מען וויל אז די דברים הנאמרים זאלן (ווי כל עניני תורה) אראפקומען בהבנה והשגה, דורך דערויף וואס מען וועט דערנאך זיך מתבונן זיין אין זיי — ווערט דאך דורך דעם א „יחוד נפלא שאין יחוד כמוהו ולא כערכו נמצא כלל״ (אז דער שכל מיטן מושכל מיטן משכיל ווערן איין זאך⁵), ווי דער אלטער רבי איז מבאר בארוכה אין תניא⁶.\nג. ונוסף לזה: אויך מצד דעם זמן — געפינט מען זיך דאך אין חודש תשרי, ובפרט נאך אז ס׳איז בהמשך צו שמע״צ (ושמח״ת), וואס „ביום השמיני עצרת גו׳ והקרבתם גו׳ פר אחד״⁷.",[["1","1","פרק לב."],["2","2","אגה״ק ס״ט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו״א כז, סע״ד</a>."],["3","3","ב״מ פה, רע״ב. נדרים פא, א."],["4","4","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380691\" data-slug=\"likkutei-torah\" data-id=\"4001380691\">לקר״ת ראה כט, א</a>. וראה גם לקו״ת מסעי צא, ד. ובכ״מ."],["5","5","ראה מו״נ ח״א פס״ח. סהמ״צ (להצ״צ) מצות האמנת אלקות פ״ג ואילך. וש״נ. ובנדו״ד מתאים יותר שכל וכו׳ (אפילו קודם בואו להמסקנא דיעה כו׳)."],["6","6","פ״ה."],["7","7","פינחס כט, לה־לו. וראה סוכה נה, ב: פר יחידי למה כנגד אומה יחידה. וראה בחי׳ ס״פ"]]],[1300201274,"דלכאורה: ווייבאלד דער „והקרבתם״ איז פארבונדן מיט „ביום השמיני״, האט מען דאך געדארפט מקריב זיין כמה פרים, בהמשך למספר הפרים שביום השביעי [אזוי ווי בשבעת ימי הסוכות וואס דער מספר הפרים שבכל יום איז בהמשך צום מספר הפרים דיום שלפניו (באופן דפוחת והולך)] — און פונדעסטוועגן איז מען מקריב „פר אחד״. ס׳איז א מספר אבער וואס ווייזט⁸ אויף א דרגא שלמעלה מענין המספר והתחלקות.\nועד״ז איז אויך בנוגע צום זמן פון שמע״צ, אז ער איז „יום אחד״ (וואס ווייזט אויף למעלה מהתחלקות)⁹.\nד. מאמר ד״ה להבין ענין שמח״ת.\nה. איידער מען גייט זיך פאנאנדער בגשמיות — איז כאן המקום דערמאנען נאך אמאל וועגן די שיעורים הידועים פון חומש תהלים און תניא,\nאון אויך וועגן דעם ענין פון קרן השנה, ווי שוין גערעדט כמה פעמים די פרטי הדבר¹⁰,\nאון אויך דערמאנען און מעורר זיין אויף די מבצעים, אנהויבנדיק פון „מבצע אהבת ישראל״\n— וואס אויך אין דערויף איז אונטערגעשטראכן דער ענין האחדות [ביז התאחדות אמיתית] פון כל אחד מבני ישראל, ניט קוקנדיק אויף זייער התחלקות אין אנדערע ענינים, כמבואר בארוכה אין תניא פרק לב —\nאון דערנאך קומט דאס אראפ אין „מבצע חינוך״, „מבצע תורה״, „מבצע תפילין״, „מבצע מזוזה״, „מבצע צדקה״, און „בית מלא ספרים — יבנה וחכמי׳״,\nאון אויך די מצוות וואס זיינען איבערגעגעבן געווארן במיוחד צו נשי ובנות ישראל, וואס יעדערע פון זיי איז די עקרת הבית פון איר פרטית׳דיקע הויז און אויך פון בית ישראל כולו: „מבצע נרות שבת קודש ויו״ט״, „מבצע כשרות האכילה ושתי׳״, און „מבצע טהרת המשפחה״.\nאון אויך דאס וועט ברענגען בקרוב ממש דעם מבצע הכי גדול וואס דער אויבערשטער אליין וועט טאן — „ואתם תלוקטו לאחד אחד בני ישראל״¹¹, ווי רש״י טייטשט אפ¹², אז דער אויבערשטער נעמט יעדער אידן פארן האנט און פירט אים ארויס פון גלות און ברענגט אים אין ארצנו הקדושה, ארץ אשר גו׳ עיני ה״א בה מראשית השנה ועד אחרית שנה¹³,\nובקרוב ממש, ובשמחה ובטוב לבב, קהל גדול ישובו הנה¹⁴,\nאון ווי ס׳שטייט בנוגע צו די גאולה האחרונה, וואס זי וועט זיין בקרוב ממש, אז קיין איין און איינציקער איד וועט ניט בלייבן אין גלות¹⁵, און דער אויבערשטער וועט זיי אלעמען ארויס־נעמען, בחסד וברחמים ובטוב הנראה והנגלה, בקרוב ממש ובעגלא דידן.",[["","","פינחס. חדא״ג מהרש״א בסוכה שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091233\" data-slug=\"likkutei-sichot\" data-id=\"1300091233\">לקו״ש ח״ט ע׳ 233</a>."],["8","8","ראה תו״א שבהערה הבאה."],["9","9","ראה תו״א קי, רע״א (לענין יום אחד דשבועות. וראה שהש״ר פ״ז, ב (ב), ועד״ז הוא בתנחומא פינחס טו: ראוי׳ היתה עצרת.. כנגד העצרת של פסח כו׳ (הובא בהמאמר))."],["10","10","וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021375\" data-slug=\"likkutei-sichot\" data-id=\"1300021375\">לקו״ש ח״ב ס״ע 651</a> ואילך."],["11","11","ישעי׳ כז, יב."],["12","12","נצבים ל, ג."],["13","13","עקב יא, יב."],["14","14","ירמי׳ לא, ח."],["15","15","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111001\" data-slug=\"likkutei-sichot\" data-id=\"1300111001\">לקו״ש חי״א ע׳ 1</a> ואילך. וש״נ."]]],[1300201275,"בס״ד. מוצאי שבת בראשית — בחדרו — ה׳תשל״ח\nבראשית ברא אלקים את השמים ואת הארץ, וארז״ל¹ אמר ר׳ יצחק לא הי׳ צריך להתחיל את התורה אלא מהחודש הזה לכם כו׳ ומה טעם פתח בבראשית משום כח מעשיו הגיד לעמו לתת להם נחלת גוים², שאם יאמרו אומות העולם לישראל לסטים אתם שכבשתם ארצות שבעה גוים הם אומרים להם כל הארץ של הקב״ה היא הוא בראה ונתנה לאשר ישר בעיניו ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו. ומבואר בזה בדרושי רבותינו נשיאינו³, דזה מה שהי׳ צריך להתחיל את התורה מהחודש הזה לכם הוא, כי ענין „החודש הזה” הוא יחוד סובב וממלא. כי חודש הוא בחינת מלכות, חודש אשתו⁴, בחי׳ ממכ״ע, ו„זה” הו״ע גילוי [כמרז״ל⁵ מראה באצבעו ואומר זה], יסוד וז״א, יחוד סוכ״ע וממכ״ע. ופירוש „החודש הזה (לכם)” הוא שבבחי׳ ממכ״ע (חודש) יהי׳ בו גילוי סוכ״ע (הזה). והי׳ צריך להתחיל את התורה מהחודש הזה לכם, כי תכלית התורה ומצותי׳ הו״ע יחוד סובב וממלא.\nב) והנה ענין המשכת הסובב שע״י תומ״צ בשרשו הראשון הוא המשכת אוא״ס שלפני הצמצום. וכדאיתא בעמה״מ בתחלתו⁶, דבריאת העולמות הי׳ ע״י צמצום הראשון שהי׳ באוא״ס ונשאר חלל ומקום פנוי, ומזה הוא שרש התהוות הכלים ומציאות העולמות (ענין מעשה בראשית). ומ״ש⁷ ויניחהו בג״ע לעבדה ולשמרה [שקאי על העבודה דתומ״צ, לעבדה זה רמ״ח מ״ע ולשמרה זה שס״ה מל״ת⁸] הוא להמשיך תוספות אורות ע״י הקו מאוא״ס שלפה״צ, עד שלעתיד יהי׳ גילוי אוא״ס במקום החלל כמו שהי׳",[["1","1","תנחומא (באבער) יא. ועוד — הובא בפרש״י עה״ת."],["2","2","תהלים קיא, ו."],["3","3","אוה״ת בא ע׳ רסב."],["4","4","שם ע׳ רנה, רעה."],["5","5","תענית בסופה (ובפרש״י שם). פרש״י בשלח טו, ב."],["6","6","הובא באוה״ת שם. ובארוכה יותר בהמשך תרס״ו בתחלתו (ס״ע ג ואילך), ד״ה יו״ט של ר״ה תש״י ס״ז. ובכ״מ."],["7","7","בראשית ב, טו."],["8","8","אוה״ת בראשית (ח״ו ע׳ 2082 — בשם ארז״ל). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381323\" data-slug=\"likkutei-torah\" data-id=\"4001381323\">לקו״ת שה״ש (מח, ד</a>). יל״ר בראשית. זח״א כז, א. תקו״ז תכ״א (סב, א). שם תנ״ה (פח, ב)."]]],[1300201276,"קודם הצמצום. וזהו לא הי׳ צריך להתחיל את התורה אלא מהחודש הזה לכם כו׳, כי סיפור מע״ב הכל הוא אחר הצמצום, ומכיון שענינה של התורה הוא המשכת אוא״ס שלמעלה מהצמצום, הוצרך להתחיל את התורה (לא במע״ב, כ״א) מהחודש הזה שהו״ע המשכת בחי׳ הסובב („הזה”), שבשרשו הוא המשכת אוא״ס שלפה״צ.\nג) ומה טעם פתח בבראשית משום כח מעשיו הגיד לעמו לתת להם נחלת גוים. והיינו שהענין דכח מעשיו גו׳ לתת להם נחלת גוים הוא נעלה יותר גם מענין המשכת הסובב, בחי׳ אוא״ס שלפה״צ. דהנה תכלית הכוונה (דתומ״צ) הוא להמשיך בחי׳ אור חדש, היינו בחי׳ עצמות אוא״ס שלמעלה מהאור שהי׳ ממלא מקום החלל⁹. והמשכת אור זה הוא דוקא ע״י עבודת הבירורים¹⁰. וזהו היתרון שבכח מעשיו גו׳ לתת להם נחלת גוים על החודש הזה, כי ענין החודש הזה הוא המשכת אור הסובב, שבשרשו הוא בחי׳ האור שהי׳ ממלא מקום החלל, וע״י¹¹ עבודת הבירורים דעניני העולם שנפלו מז״מ, מלכי אדום שברצונו נתנה להם — כמרז״ל¹² בונה עולמות ומחריבן — ובנ״י מבררים ויורשים¹³ אותם ונעשו נחלת יעקב, ממשיכים בחי׳ אור חדש שלמעלה מהאור שהי׳ ממלא מקום החלל. וכמו שהוא בכלל העולם (עולמות בי״ע, דמשם יפרד) בא ג״כ בפרט הבירור דכיבוש ארצות שבעה גוים, שישראל מהפכים אותם לארץ ישראל.\nד) והנה מכיון דזה ש„ברצונו נתנה להם” (לזמן מסויים) הוא בכדי שיהי׳ אח״כ „ברצונו נטלה מהם ונתנה לנו”, הרי פשוט, שבאם מחליטים בתוקף, אזי מבררים בנקל יותר את ארצות שבעה גוים, וכל העולם כולו, שיהי׳ דירה לו ית׳. וזה מה שנדמה שצריך לזה יגיעה ועמל, ועד שאומות העולם טוענים בנוגע לכל בירור¹⁴ לסטים אתם הוא מצד גודל ההעלם והסתר, מה שאין נרגש בעולם אשר „כל הארץ של הקב״ה היא” („כי¹⁵ ממך הכל”¹⁶). אבל הרי תכלית הכוונה של ההעלם והסתר הוא בכדי שיהי׳",[["9","9","המשך תרס״ו שם (ע׳ ד׳). ע׳ תקט. ד״ה יו״ט של ר״ה תש״י שם. ועוד."],["10","10","המשך תרס״ו ע׳ שלז ואילך. ס״ע שנד ואילך. ועוד."],["11","11","להעיר גם מהמשך הנ״ל ס״ע שמ ואילך."],["12","12","קה״ר פ״ג, יא."],["13","13","המשך וככה תרל״ז פס״ח. ד״ה אם רוח המושל תרצ״ה פ״ו. ובכ״מ."],["14","14","ראה אוה״ת שבהערה 3. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101003\" data-slug=\"likkutei-sichot\" data-id=\"1300101003\">לקו״ש ח״י ע׳ 3</a>, 5."],["15","15","לשון הכתוב — דה״א כט, יד."],["16","16","ראה אוה״ת שבהערה 3."]]],[1300201277,"ובקשתם משם¹⁷, אז אידן זאלן זוכן און געפינען דעם אויבערשטן בכל עניני העולם, בהעלמות וההסתרים¹⁸ [וכמשל האב המסתיר את עצמו מבנו הקטן בכדי להראות את חכמת הבן שמבין שההסתר וההעלם אינו אלא בכדי שיבקשנו וימצאנו¹⁹], והבטיחה תורה שכאשר ובקשתם משם אז בודאי „ומצאת”²⁰, שכובשים את כל העולם ועושים ממנו דירה לו ית׳, עד אשר אז אהפוך אל עמים שפה ברורה וגו׳ לעבדו שכם אחד²¹. והיתה לה׳ המלוכה²².\nה) ויש לקשר זה גם עם ענין ד„ויעקב הלך לדרכו” (שבמוצאי שבת בראשית²³), דהגם שהולך לדרכו (גם) בעניני הרשות ובעובדין דחול במשך כל השנה, מ״מ אינו ירא מזה, כי אם, הולך לבטח דרכו, ובשמחה ובטוב לבב. וזהו גם מה שבמוצאי שבת [ובפרט במוצאי שבת בראשית, שאז מתחיל (בעיקר) הסדר דויעקב הלך לדרכו²³] אומרים²⁴ אל תירא עבדי יעקב²⁵, כי „במוצאי שבת מסתלקת הנשמה יתירה וצריך לחזור ולירד בבחי׳ יעקב עבדי בכל ששת ימי המעשה לברר בירורים בבי״ע כו׳ לכך אומר אל תירא עבדי יעקב כו׳ מלירד שם, ובזה נותנים כח ועוז כו׳”²⁶. והטעם לזה (לענין אל תירא) הוא כי הוי׳ אלקיו עמו²⁷, שכאו״א מישראל (גם מי שהוא בבחי׳ יעקב), בכל מקום ובכל זמן ובכל ענין (גם בחו״ל ובימי החול ובעובדין דחול), הוי׳ אלקיו (הוא) עמו, ועד שנעשה שותף להקב״ה במעשה בראשית²⁸, שהוא פועל חידוש בהבריאה (כמו הקב״ה כביכול). כי ע״י",[["17","17","ואתחנן ד, כט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380845\" data-slug=\"likkutei-torah\" data-id=\"4001380845\">לקו״ת ראה לב, ג</a>."],["18","18","ומכיון שמצד ההעלמות וההסתרים, הבירור הוא „בבחי׳ התחדשות גמורה כחידוש יש מאין”, לכן, עי״ז דוקא הוא עיקר המשכת האור חדש (המשך תרס״ו ע׳ שנד־ה)."],["19","19","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381052\" data-slug=\"likkutei-torah\" data-id=\"4001381052\">לקו״ת סוכות פב, א</a>. שער האמונה בהקדמה. המשך תרס״ו ע׳ רמח ואילך (ולהעיר גם מהמשל המובא שם ס״ע שפ ואילך)."],["20","20","ואתחנן שם."],["21","21","צפני׳ ג, ט."],["22","22","עובדי׳ א, כא."],["23","23","כמבואר בהשיחה (סעיף ד׳)."],["24","24","כ״ה בלקו״ת שבהערה 26. ולהעיר, שבכ״מ בדא״ח מבוארים גם (נוסחאות ו)מנהגים שאין נוהגים בחב״ד."],["25","25","לשון הכתוב — ישעי׳ מד, ב. ירמי׳ ל, יו״ד. ועוד."],["26","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו״ת בלק עב, ב</a>."],["27","27","בלק כג, כא. ובלקו״ת שם (עא, סע״ד), שענין זה (דהוי׳ אלקיו עמו) „הוא העזר מלמעלה” לבחי׳ יעקב. — ושייך לתרועת מלך בו — עבודה דר״ה (לקו״ת ר״ה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">נד, ג</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו״ת בלק עב, סע״ב</a>)."],["28","28","שבת קיט, רע״ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061022\" data-slug=\"likkutei-sichot\" data-id=\"1300061022\">לקו״ש ח״ו ע׳ 22</a> הע׳ 73."]]],[1300201278,"עבודתו בעבודת הבירורים לעשות את העולם דירה לו ית׳, הוא פועל חידוש בהבריאה [דזהו גם מה שבשבת בראשית קוראין בתורה בראשית ברא אלקים את השמים ואת הארץ, שעי״ז נעשה בריאת השמים והארץ וכל צבאיהם מחדש ובאופן חדש], ועד שיהי׳ השמים החדשים והארץ החדשה גו׳²⁹.",[["29","29","ישעי׳ סו, כב. ובסה״מ תרע״ח ע׳ רפד: והוא ההמשכה מבחי׳ עצמות א״ס שלמעלה מגילוי הקו ולמעלה מהאור שהי׳ ממלא מקום החלל."]]],[1300201279,"שיחת מוצאי שבת בראשית — בחדרו — ה׳תשל״ח.\nא. בהמשך צו דעם וואס מ׳האט גערעדט במוצאי שמח״ת — וואס (מוצאי) שבת בראשית קומט בתור השלמה צו שמח״ת און שמע״צ און (אויך) צו די מועדים שלפנ״ז, ווי געשריבן (און אפגעדרוקט) אין דעם מכתב פון רבי׳ן נשיא דורנו¹ — דערפאר איז צוגעפאסט, אז אויך איצטער (במוצאי שבת בראשית) זאל מען ריידן אין אזא אופן, אז די דברים הנאמרים זאלן דערגרייכן אין די זעלבע צייט אויך למקומות רחוקים (בגשמיות), וואס דאס פועל׳ט א קשר און א התאחדות צווישן די אלע וואס הערן די רייד, ווי דערקלערט בארוכה במוצאי שמח״ת.\nובפרט נאך אז דער „ויעקב הלך לדרכו” שבמוצאי שבת בראשית איז אין אן אופן וואס מען גייט זיך פאנאנדער (בחיצוניות), יעדער איינער אין זיין עבודה פרטית — נאך מער ווי במוצאי שמח״ת (כדלקמן) — דערפאר איז במוצאי שבת בראשית נאך מער נוגע צו מדגיש זיין דעם קשר און התאחדות פון אלע אידן.\nב. שוין גערעדט אמאל בארוכה², אז אין דעם ענין פון „ויעקב הלך לדרכו” וואס הויבט זיך אן נאך דעם ווי בר״ה וביוהכ״פ באקומען אלע אידן, און יעדער איד, די כתיבה וחתימה טובה לשנה טובה ומתוקה\n— וואס אין דעם „ויעקב הלך לדרכו” ווערן אונטערגעשטראכן צוויי קצוות³: פון איין זייט איז דער פירוש פון „ויעקב הלך לדרכו” אז דער איד גייט צו זיין וועג, צו זיינע וואכעדיקע ענינים (אויף מאכן פון זיי א דירה לו ית׳, דורך „כל מעשיך לשם שמים”⁴ און „בכל דרכיך דעהו”⁵, וואס מצד דערויף איז דא (און דארף זיין) א התחלקות צווישן איין אידן מיטן צווייטן: אבער ביחד עם זה איז פון דעם וואס אויף אלע אידן צוזאמען זאגט מען דוקא דעם לשון „ויעקב הלך לדרכו”, לשון יחיד⁶, שטרייכט עס אונטער ווי אלע אידן (טראץ דעם וואס (בחיצוניות) זיינען זיי בהתחלקות) זיינען זיי א „גוי אחד” —\nזיינען פאראן כמה דרגות און זמנים:\nדי התחלה פון „ויעקב הלך לדרכו” איז במוצאי יוהכ״פ.\nאין די עשרה ימים שבין ר״ה ליוהכ״פ, כאטש אז אויך דעמולט זיינען דא כמה עבודות אין וועלכע עס זיינען אויסגעטיילט ראשיכם שבטיכם פון חוטב עציך און שואב מימיך — איז דאך אבער „אתם נצבים היום כולכם”, אז אין דעם טאג פון ר״ה [וואס „היום” גייט אויף ר״ה⁷] זיינען אלע צען סוגים (פון „ראשיכם” ביז „שואב מימיך”) אין אן אופן פון „כולכם”, „לאחדים כאחד”:\nעד״ז (אבל לא ממש), איז אויך אין די",[["1","1","דמחרת יוהכ״פ תרפ״ט (נדפס בסה״מ תשי״א ע׳ 48)."],["2","2","ראה שיחות י״ג תשרי ושבת בראשית תשל״ה. ד׳ מ״ח תשל״ז. ועוד."],["3","3","ראה עד״ז שיחת מוצאי שבת בראשית תשל״ה (נדפסה בלקו״ש ח״ט בתחלתו)."],["4","4","אבות פ״ב מי״ב."],["5","5","משלי ג, ו."],["6","6","אע״פ שבהעבודה המתחילה עתה — החידוש הוא ההתחלקות והריבוי."],["7","7","לקו״ת ר״פ נצבים."]]],[1300201280,"טעג שלאחרי ר״ה ביז יוהכ״פ,\nובפרט ביוהכ״פ: וויבאלד יוהכ״פ איז דער „אחת בשנה”⁸, בחינה „אחת” ד„שנה” [און די עבודה (המיוחדת) דיוהכ״פ איז אין „קודש הקדשים”, בחינת „אחת” ד„עולם”, און ווערט געטאן און אויפגעטאן דורכן כהן גדול, בחינת „אחת” ד„נפש”⁹], זיינען דערינבער אלע אידן דעמולט אין א התאחדות גמורה.\nבשעת עס קומט אבער מוצאי יוהכ״פ, ווען אידן הויבן זיך אן פאנאנדערגיין, יעדער איד איז פארנומען מיט צוגרייטן זיין סוכה¹⁰ און זיינע ד׳ מינים (ולקחתם לכם, משלכם¹¹) — דאן הויבט זיך אן דער סדר פון „ויעקב הלך לדרכו”, און ווי מען געפינט בדרושי רבותינו נשיאינו¹², אז דער ענין פון „ויעקב הלך לדרכו” הויבט זיך אן גלייך במוצאי יוהכ״פ.\nג. די צווייטע דרגא אין „ויעקב הלך לדרכו” איז במוצאי שמחת תורה:\nאין די ד׳ ימים שבין יוהכ״פ לסוכות, וויבאלד אז דעמולט איז „כל ישראל עסוקים במצוות”¹³ — שטייען דאך במילא אלע אידן אין א התאחדות, ווארום אלע מצוות קומען דאך פון זעלבן בעל הרצון, יחידו של עולם.\n[ובפרט אז די מצוות אין וועלכע אידן זיינען עסוקים בד׳ ימים אלו — סוכה און ד׳ מינים — ווייזן אויף ענין האחדות. ווי גערעדט פריער¹⁴, אז אויף סוכה שטייט „ראוים כל ישראל לישב בסוכה אחת”¹⁵, און אויך די מצוה פון נטילת ד׳ מינים איז (נוסף אויף דעם וואס יעדער מין באזונדער ווייזט אויף אחדות) צו פאראייניקן אלע פיר מינים, וואס ווייזן אויף די פארשידענע פיר סוגים פון אידן¹⁶, אז זיי זאלן ווערן אן אגודה אחת — „ויעשו כולם אגודה אחת לעשות רצונך בלבב שלם”.\nאון דוקא ווען ס׳איז דא דער „כולם” (אויך די אידן שנמשלו לערבה שאין בה לא טעם ולא ריח¹⁶. ווארום די מצוה „ולקחתם לכם” מוז מען אנקומען צו די ערבה ניט ווייניקער ווי צום אתרוג), און אין אן אופן פון „אגודה אחת” — דאן דוקא ווערט דער „לעשות רצונך בלבב שלם”].\nעד״ז איז אויך בנוגע צו די טעג פון",[["8","8","אחרי טז, לד."],["9","9","כמשנת׳ בארוכה בהמאמרים ד״ה בסוכות תשבו (סעיף ז — סה״מ — מלוקט ח״א ע׳ רמח) וד״ה להבין ענין שמח״ת (ס״ג — לעיל ע׳ 256־7)."],["10","10","דמכיון ש„תשבו כעין תדורו” (או״ח סתרל״ט) — הרי צ״ל לכל אחד סוכה בפ״ע, בדוגמת מה שבכל השנה דר בדירה שלו. — ובפרט שגם עשייתו הסוכה היא מצוה (שו״ע אדה״ז רסתרמ״א, ובכיו״ב מצוה בו יותר מבשלוחו, ועד שרשב״י הפסיק גם לעשיית סוכה (ירושלמי ברכות פ״א ה״ב). בירושלמי שם, שהפסיק גם לעשיית לולב. שגם עשיית הלולב היא מצוה [שלכן לדעת הירושלמי (ברכות פ״ט ה״ג) מברכין לעשות לולב. וגם להבבלי יש לומר שעשיית הלולב היא מצוה* (וראה חדא״ג מהרש״א סוכה מה, א: עשיית לולב באגודה... היא מצוה כאילו בנה מזבח). והא דאין מברכים על זה — יש לומר, שזהו „לפי שעשייתה אינה גמר המצוה” (כמ״ש בשו״ע אדה״ז שם בנוגע עשיית סוכה). וראה לקו״ש ח״ב ע׳ 214]."],["11","11","אמור כג, מ. סוכה מא, ב. או״ח סתרמ״ט (וראה ירושלמי שבהערה הקודמת). *) שעפ״ז מובן מה שרשב״י הפסיק לעשיית לולב גם להבבלי, דאין סברא לומר דהבבלי פליג על הירושלמי (גם) בענין דמציאות האם רשב״י הפסיק לעשייה (ולאפושי במחלוקת). ---"],["12","12","וככה תרל״ז רפצ״ו."],["13","13","ויק״ר פ״ל, ז."],["14","14","בד״ה בסוכות תשבו (סעיף ט, סי״ד — סה״מ — מלוקט ח״א ע׳ רמט, רנג ואילך), להבין עניין שמח״ת (ס״ג — לעיל שם)."],["15","15","סוכה כז, ב."],["16","16","ויק״ר שם, יב."]]],[1300201281,"חג הסוכות, אז וויבאלד¹⁷ אז דעמולט איז „מועדים לשמחה” מצד דערויף וואס אלקות שטייט בגילוי¹⁸ — ובפרט אז ימי חג הסוכות זיינען זמן שמחתנו, די שמחה כפולה פון „ישמח הוי׳ במעשיו” און „ישמח ישראל בעושיו”¹⁹,\nועאכו״כ בשמע״צ ושמח״ת וואס דעמולט איז (נוסף אויף דעם ענין פון „מועדים לשמחה” און „זמן שמחתנו”²⁰) מודגש די אחדות און העדר ההתחלקות נאך מערער ווי בסוכות, וכמרז״ל²¹, אז די התאחדות פון אידן וואס דריקט זיך אויס אין הקרבת „פר אחד” בשמע״צ איז אז אלע אידן זיינען אן „אומה יחידה” (באופן ד„יחיד” שלמעלה מ„אחד”²²), ביז אז די התאחדות איז שולל דעם „(קשה עלי) פרידתכם”²³ אויך לאחרי שמע״צ ושמח״ת²⁴\nוואס דאס (שבשמע״צ ושמח״ת מו־שלל בתכלית ענין הפירוד וההתחל־קות) דריקט זיך אויס אויך אין דעם וואס דער אופן השמחה דשמע״צ ושמח״ת איז דורך ריקוד ברגלים²⁵. וואס אין דעם (רגלים) גלייכן זיך אויס אלע אידן פון ראשיכם שבטיכם ביז חוטב עציך ושואב מימיך\n[ואדרבה, אין דעם איז מודגש די מעלה פון די אידן וואס זיינען בבחי׳ רגלים. בדוגמת ענין הריקוד כפשוטו, אז דורך דעם וואס די פיס טאנצן — דורך דעם דוקא הויבט זיך (און טאנצט) אויך די קאפ],\nוואס דערפון איז מובן בפשטות, אז (טראץ דעם וואס אידן זיינען צושפרייט אין פארשידענע ערטער, פונדעסטוועגן, איז) בשעת א איד פראוועט שמח״ת אין חו״ל און א צווייטער איד פראוועט שמח״ת אין אה״ק ת״ו, איז עס ניט א צווייטער איד נאר דאס איז (צוזאמען מיטן ערשטן) אן „אומה יחידה”. און די איינציקייט זעט זיך אן בגלוי, דורך די ריקודים.\nאון לאחרי שמח״ת, ווען מען גייט פון דער שמחה (און קדושה) פון „זמן שמחתנו” דסוכות, און מען גייט אריין אין וואכעדיקן יאר — דאן דארף מען (נאכאמאל) מדגיש זיין דעם ענין האחדות, אז די אחדות פון אידן וואס איז געווען בגילוי בשמע״צ ובשמח״ת זאל נמשך ווערן, און זאל זיין ניכר בגילוי, אויך לאחרי שמע״צ ושמח״ת.\nוואס דאס איז אויך פון די טעמים אויף דעם מנהג צו מכריז זיין במוצאי שמח״ת „ויעקב הלך לדרכו”²⁶ — צו מדגיש זיין, און געבן דעם נתינת כח, אז אויך נאך שמח״ת ווען א איד גייט „לדרכו” אויך בעניני הרשות (ניט ווי דער „ויעקב הלך לדרכו” שבמוצאי יוהכ״פ, וואס (אויך) דער „דרכו” איז בענין המצוות²⁷), איז עס „ויעקב הלך לדרכו” בלשון יחיד, אז אויך דעמולט זאל זיין ניכר ווי אלע אידן זיינען א „גוי אחד (אויך) בארץ”²⁸.",[["17","17","נוסף על זה מה שהמצוות דחגה״ס (סוכה וד׳ מינים) מורים על ענין האחדות, כנ״ל בפנים."],["18","18","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380123\" data-slug=\"likkutei-torah\" data-id=\"4001380123\">לקו״ת צו יא, ד</a>. שמע״צ פח, ד. ובכ״מ."],["19","19","ראה לקו״ת שמע״צ שם ואילך."],["20","20","שגם בזה יש יתרון בשמע״צ על חגה״ס (ראה לקו״ת שם פט, א)."],["21","21","סוכה נה, ב."],["22","22","כדיוק לשון רז״ל (סוכה שם): „פר יחידי כר אומה יחידה” — אף שבכתוב (פינחס כט, לו) נאמר „פר אחד”."],["23","23","פירש״י עה״ת אמור כג, לו. פינחס שם. בחיי פינחס כט, לה."],["24","24","דעפ״ז מובן התיקון ד„עכבו עוד יום אחד” לקשה עלי כו׳. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091234\" data-slug=\"likkutei-sichot\" data-id=\"1300091234\">לקו״ש ח״ט ע׳ 234</a>."],["25","25","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091233\" data-slug=\"likkutei-sichot\" data-id=\"1300091233\">לקו״ש שם ע׳ 233</a>."],["26","26","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101192\" data-slug=\"likkutei-sichot\" data-id=\"1300101192\">לקו״ש ח״י ע׳ 192</a>. וש״נ."],["27","27","כמשנת׳ בד״ה להבין ענין שמח״ת ס״ו (לעיל ע׳ 259)."],["28","28","ראה אגה״ק ס״ט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370130\" data-slug=\"torah-or\" data-id=\"3901370130\">תו״א כז, סע״ד</a>."]]],[1300201282,"ד. אעפ״כ איז אויך במוצאי שמח״ת קומט עס ניט צו די הדגשה אויף ענין האחדות וואס עס פאדערט זיך במוצאי שבת בראשית:\nוויבאלד אז בשבת איז דער „ויכולו” (בכל הפירושים שבזה²⁹) פון די ששת ימים שלפני השבת — איז דאך פארשטאנדיק, אז די עבודה פון שמע״צ ושמח״ת (וואס דער „ויכולו” פון די עבודה איז בשבת בראשית) איז (עכ״פ) מאיר אויך אין די טעג שלאחרי שמח״ת ביז שבת בראשית ועד בכלל,\nואדרבה: בשבת בראשית, זיינען די ענינים דשמע״צ ושמח״ת (באופן ד„ויכולו” —) בתכלית השלימות.\nוואס דערפאר זעט מען אויך במוחש, אז טראץ דעם וואס לאחרי שמח״ת הויבן זיך אן ימי החול, פונדעסטוועגן, איז ביז שבת בראשית — פילט זיך נאך ניט קיין אמת׳ע וואכעדיקייט: גלייך אויף מארגן פון שמח״ת איז „אסרו חג”³⁰, און דערנאך (ווען עס ווערט נעענטער צו שבו[ע]ת בראשית) איז מען פארנומען מיט מאכן הכנות צו שבת בראשית. און בכלל איז מען נאך דורכ־גענומען בימים אלו מיט דער יו״ט־דיקייט פון (חגה״ס, ובפרט, פון) שמע״צ ושמח״ת.\nאון דערפאר איז בשעת עס קומט מוצאי שבת בראשית, וואס דעמולט הויבט זיך אן פילן די וואכעדיקייט פון די ימי החול שבמשך השנה — איז נוגע נאך מער צו מכריז זיין (נאכאמאל) „ויעקב הלך לדרכו”\n— און די הכרזה דארף זיין אין אזא אופן אז זי זאל דורכנעמען די מחשבה דיבור ומעשה, והמעשה הוא העיקר —\nאון אע״פ אז יעדער איד האט זיין תפקיד און שליחות מיוחדת אויף צו מאכן פון חלקו בעולם (פון זיין חלק) א דירה לו ית׳³¹, פונדעסטוועגן איז עס „ויעקב הלך לדרכו” בלשון יחיד. ביז (ווי גערעדט פריער³²), אז במשך כל ימי השנה, דארף זיך הערן אז מען איז אט ערשט געקומען פון דעם „יום אחד” דשמע״צ, וואס אין אים שטייט בגלוי ווי אזוי אידן זיינען אן „אומה יחידה”.\n• • •\nה. שוין גערעדט אמאל באריכות³³, אז נוסף צום תוכן פון „ויעקב הלך לדרכו” (וואס איז אויך אלע דריי ווערטער צוזאמען), איז אויך אין יעדער ווארט פארזיך פארן א הוראה, ביז צו א הוראה עיקרית און א הוראה נפלאה.\n„ויעקב”:\nדער נאמען „יעקב” איז ניט דער שם המעלה פון אידן [אזוי ווי דער נאמען „ישראל”, וואס איז על שם „כי שרית עם אלקים ועם אנשים ותוכל”³⁴], נאר אדרבה מלשון „עקב”, און נאכמער: דער נאמען יעקב איז על שם „וידו אחזת בעקב עשו”³⁵. דאס הייסט, אז דער נאמען יעקב באצייכנט ווי א איד פארנעמט זיך (באופן דאחיזה) מיט עניני העולם, מיט ענינים פון „נחלת גוים”³⁶ (עשו), אויף מאכן פון זיי „נחלת יעקב”.",[["29","29","ראה אוה״ת ד״ה ויכולו (בראשית מב, ב ואילך)."],["30","30","ראה שו״ע אדה״ז סתכ״ט סי״ז."],["31","31","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מח, א</a>)."],["32","32","בד״ה להבין ענין שמח״ת ס״ה (ע׳ 258)."],["33","33","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101195\" data-slug=\"likkutei-sichot\" data-id=\"1300101195\">לקו״ש ח״י ע׳ 195</a>. מכתב ד׳ מ״ח תשל״ז.*"],["34","34","וישלח לב, כט."],["35","35","תולדות כה, כו."],["36","36","ראה רש״י ר״פ בראשית. *) נדפס ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151494\" data-slug=\"likkutei-sichot\" data-id=\"1300151494\">לקו״ש חט״ו ע׳ 481</a> ואילך."]]],[1300201283,"און אע״פ אז דאס איז לכאורה א נידעריקע מדריגה — איז אבער אין אמת׳ן, אז אין דעם באשטייט דער תכלית השלימות. ווארום כשם ווי אין כללות העולמות איז דאך „נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים”³⁷, און ווי דער אלטער רבי איז מבאר³⁸ אז דער תכלית הכוונה איז ניט אין עולמות העליונים נאר אין עוה״ז הגשמי „שאין תחתון למטה ממנו” — עד״ז איז אויך אין דעם „עולם מלא” וואס בא יעדער אידן בפרט³⁹, אז דער תכלית הכוונה איז אין דעם כח הכי תחתון „שאין תחתון למטה ממנו” פון זיין ציור קומה.\nוואס דאס איז אויך וואס דער נאמען יעקב הויבט זיך אן מיט א יו״ד, וואס גייט אויף דעם יו״ד פון שם הוי׳⁴⁰\n[וואס אין שם הוי׳ גופא (וואס ער איז דער „שם המפורש”⁴¹, „שם העצם”⁴² און „שם המיוחד”⁴³) איז ער (דער יו״ד) דער עיקר⁴⁴, ביז אז (כפי המובן ב־שעהיוה״א⁴⁵) ער איז למעלה מהתחל־קות, העכער אפילו פון דעם אופן ההתחלקות שבשם הוי׳],\nוואס אין אים איז אויך דא דער קוצו של יו״ד, וואס איז העכער פון כל ציור (אפילו פון ציור דיו״ד),\nאון דער יו״ד (מיטן קוצו של יו״ד) ווערט נמשך אין בחינת „עקב”⁴⁶, און די המשכה איז אזא אופן אז דער עקב ווערט (איין ווערט) איינס מיטן יו״ד (און קוצו של יו״ד),\nאון נאך מער: דער יו״ד איז דער „ראש” פון ווארט, וואס כשם ווי א ראש איז כולל דעם חיות פון אלע איברי הגוף, וואס דערפאר פירט ער אן מיט זיי אויך לאחרי ווי זיי זיינען א „מהות בפע״ע”⁴⁷ — עד״ז איז אויך בנוגע צום יו״ד פון יעקב, אז (א) דער יו״ד איז כולל אויך דעם „עקב”, און (ב) אויך לאחרי ווי דער „עקב” שטייט בגלוי [ביז ווי מען זעט עס בפשטות אין דעם ווארט יעקב, אז די אותיות עקב זיינען דער רוב (ושורש) התיבה, און זיי זיינען מער מודגש (אין דעם ווארט) ווי דער יו״ד] ווערט ער אנגעפירט פון דעם יו״ד מיטן קוצו של יו״ד.\nו. „הלך”:\nדי הוראה פונעם ווארט „הלך” איז אז ניט בלויז וואס ער טוט זיין עבודה, נאר אז ער האלט אין איין „גייך” און עולה זיין העכער און העכער.\nאון נאך מער: וויבאלד אז דער ווארט „הלך” שטייט אין תורת אמת⁴⁸ — מיינט דאך דאס הליכה אמיתית, וואס ענינה",[["37","37","תנחומא נשא טז. במדב״ר פי״ג, ו. ועוד."],["38","38","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז</a>."],["39","39","סנהדרין לז, א (במשנה)."],["40","40","ראה תו״א (כא, א. כט, א) שהיו״ד דיעקב היא בחי׳ חכמה, ובאוה״ת ויצא (קצב, א בשוה״ג) שהיא היו״ד דשם הוי׳."],["41","41","סוטה לח, א. סנהדרין ס, א. רמב״ם הל׳ יסוה״ת פ״ו ה״ב."],["42","42","כ״מ הל׳ עכו״ם פ״ב ה״ז. פרדס שי״ט. מו״נ ח״א פס״א ואילך. עיקרים מאמר ב׳ פכ״ח."],["43","43","סוטה שם. סנהדרין שם."],["44","44","ראה שעהיוה״א פ״ב: שכל אות הקודמת בצירוף היא הגוברת והיא העיקר."],["45","45","ראה שעהיוה״א רפ״ד, שהיו״ד דשם הוי׳ מורה על הפעולה שהיא בלשון הוה ותמיד. וראה „הדרך” על הרמב״ם (קה״ת, תשמ״ה) ח״א סעיף יח (ע״פ תולדו״ב למס׳ מדות ס״ע ערב ואילך (וראה שם ע׳ קסז)), שהטעם לזה שענין התמידות שבההתהוות נרמז באות יו״ד דוקא, הוא לפי שאות יו״ד מורה על --- ספירת החכמה, ובמדריגת החכמה [„אחד האמת” — <a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל״ה</a> בהגהה] אין שייך שינוי (והתחלקות)."],["46","46","תו״א שבהערה 40."],["47","47","עטר״ת בתחלתו."],["48","48","ויצא לב, ב."]]],[1300201284,"איז⁴⁹ אז מען גייט אוועק לגמרי פון דעם פריערדיקן ארט און מדריגה. דאס הייסט, אז די מדריגה אין וועלכע ער איז עולה איז שלא בערך צו דער מדריגה הקודמת (ווארום בשעת די עלי׳ איז בערך, איז ער נאך אלץ ניט אוועק־געגאנגען באמת ממקומו — הייסט עס נאך אלץ מיטן נאמען „עמידה”).\nז. „לדרכו”:\nאמיתית הענין פון דרך איז אז זי פארבינדט דעם ווייטסטן ווינקל פון מדינת המלך מיטן עיר הבירה, ביז מיטן היכל המלך, ביז מיטן (קיטון — דער) חדר המיוחד פון מלך⁵⁰.\nדערפון איז מובן אויך בנוגע צו „(ויעקב הלך) לדרכו”, אז אע״פ אז נאך שבת בראשית גייט אוועק א איד פון די מועדים דחודש תשרי און גייט אריין אין עניני הרשות און עובדין דחול (כנ״ל סעיף ד׳), טוט ער עס אבער אין אן אופן פון „דרכו” — א דרך וואס איז מחבר זיינע עובדין דחול מיטן קיטון המלך מלכי המלכים הקב״ה, ביז אז אלע זיינע ענינים ווערן א דירה לו ית׳, לו לעצמותו.\nוואס דאס איז אויך די הדגשה אינעם ווארט „לדרכו” (זיין דרך), אז די „וועג” אין וועלכע דער איד גייט במשך דעם גאנצן וואכעדיקן יאר, איז עס „דרכו” — זיין וועג, די ספעציעלע וועג פון א אידן (כפס״ד הרמב״ם⁵¹) צו דורכפירן דעם אויבערשטנס רצון, וואס נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים,\nצו פארבינדן דעם ווייטסטן ווינקל פון סדר השתלשלות [וואס דאס איז דער עוה״ז הגשמי „התחתון במדריגה שאין תחתון ממנו”³⁸, און אין עוה״ז גופא — די עניני הרשות ועובדין דחול], און מאכן פון אים א דירה לו ית׳.\nח. און דער כח אויפן „דרך” [צו פארבינדן דעם תחתון שאין תחתון למטה ממנו מיטן קיטון המלך] איז — תורה⁵². וכידוע⁵³, אז דורך אורייתא ווערן ישראל וקוב״ה כולא חד.\nוואס דאס איז אויך וואס „אורייתא” איז נוטריקון „אור ייתא”⁵⁴:\nאין תורה איז דאך (גנוזו⁵⁵ פון) דעם אור שנברא ביום הראשון, ביז צום אור שהבדילו לעצמו, וואס דאס גייט אויף דעם „אור עצמי שאינו בגדר להאיר בעולמות”⁵⁶, בחי׳ אור שלגלגלות עצמותו⁵⁷,\nביז דער אור ווי ער איז כלול אין מאור, וואס זייענדיק כלול אין מאור איז ער ניט „אור” נאר „מאור”, ווי ער זאגט אין שעהיוה״א⁵⁸ אז ער איז „עצם אחד ממש עם גוף המאיר ואין לו שום מציאות כלל בפני עצמו”,",[["49","49","ראה תו״א ס״פ וישב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560061\" data-slug=\"or-hatorah-hb\" data-id=\"8316560061\">אוה״ת שם</a>. המשך תרס״ו ע׳ תצז. ובכ״מ."],["50","50","ביאוה״ז ר״פ וישלח. ד״ה הוי׳ יחתו רפ״ס. תקעו תשי״ז. ועוד."],["51","51","הל׳ גירושין ספ״ב."],["52","52","להעיר מתו״א ס״פ ויצא (בענין ו„יעקב הלך לדרכו”): דתורה אקרי דרך."],["53","53","ראה זח״ג עג, א."],["54","54","סה״ש תש״ד ריש ע׳ 116."],["55","55","מדרש רות בזהר חדש פה, א (עייג״כ זח״א רסד, א. זח״ב קמט, א), ובדגל מחנה אפרים פ׳ בראשית בשם הבעש״ט. כתר ש״ט (קרוב לתחלתו) הה״מ בשם הבעש״ט כו׳ (באריכות). ובכ״מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו״ת במדבר יח, ד</a>. שם דברים פט, ד. ספר החקירה סה, א. וכל העם תרצ״ט ס״ג. ועוד."],["56","56","סה״מ עת״ר ע׳ צב."],["57","57","המשך תער״ב פמ״ח."],["58","58","פ״ז. וראה לקו״ב (להר״י שי׳ קארף) לתניא שם."]]],[1300201285,"ביז אויך דער אור ווי ער איז כלול אין עצמות, וואס ער איז העכער⁵⁹ אויך פון „מאור”,\nאיז דורך „אורייתא” ווערט דער „אור ייתא”, אז תורה בריינגט אראפ דעם אור הנ״ל, אין יעדער פרט פון דעם ווייטסטן ווינקל, סיי פון „עולם” סיי פון „שנה” סיי פון „נפש”.\nט. אזוי ווי המעשה הוא העיקר — איז דער סיכום פון כל הנ״ל בנוגע למעשה בפועל, אז בכל מקום ומקום, ביז אין א פינה נדחת, דארף מען מפיץ זיין תורה ויהדות, אנהויבנדיק פון די ענינים כלליים,\nוואס אין דעם גייען אריין אויך די שיעורים הידועים פון חומש תהלים און תניא, און נתינת הצדקה בכל יום (דורך תורם זיין צדקה אויף „קרן השנה”⁶⁰, וכיו״ב),\nופשיטא, אז דערמיט ווערן געמיינט די מבצעים הידועים, אנהויבנדיק פון „מבצע אהבת ישראל”, וואס שטרייכט אונטער ווי אלע אידן זיינען איין זאך (כמבואר אין תניא פרק לב),\nאון דערנאך קומט דאס אראפ אין „מבצע חינוך”, „מבצע תורה”, „מבצע תפילין”, „מבצע מזוזה”, „מבצע צדקה”, און „בית מלא ספרים — יבנה וחכמי׳”,\nאון אויך די מצוות וואס זיינען איבערגעגעבן געווארן במיוחד צו נשי ובנות ישראל\n[וואס יעדערע פון זיי איז די עקרת הבית פון איר פרטית׳דיקע הויז און אויך פון בית ישראל כולו (ביז אז דער גאנצער אידישער פאלק איז בדוגמת אשה און עקרת הבית צום אויב־ערשטן⁶¹)]:\n„מבצע נרות שבת קודש ויו״ט”, „מבצע כשרות האכילה ושתי׳”, און „מבצע טהרת המשפחה”,\nוואס דער מבצע טהרת המשפחה (און אזוי אויך די אנדערע מבצעים) היילן צו נאך מער קיום היעוד „וזרקתי עליכם מים טהורים וטהרתם גו׳”⁶², וואס וועט זיין בקרוב ממש, בגאולה האמיתית והשלימה ע״י משיח צדקנו.\nיוד. נאך א נקודה עיקרית בהנ״ל: די עבודה הנ״ל (צו מפיץ זיין תורה און יהדות ביז אין א פינה נדחת) — דארף געטאן ווערן בשמחה ובטוב לבב. דאע״פ וואס מ׳געפינט זיך נאך אין גלות\n[און חס ושלום צו זאגן אז ס׳איז שוין דא די אתחלתא דגאולה. און ווי דער רמב״ם⁶³ פסק׳נט אפ בפס״ד ברור (וכל מפרשיו — הב״י וכו׳ — שתקו (והודו⁶⁴) לו בזה) אז די אתחלתא דגאולה („ויקבץ נדחי ישראל”) וועט זיך אנפאנגען ערשט לאחרי ביאת המשיח, און דורך אים, און נאך דעם וואס „יכוף כל ישראל לילך בה ולחזק בדקה וילחום מלחמת ה׳”, און נאך דעם ווי „בנה מקדש במקומו”],\nאון אין גלות גופא געפינט מען זיך אין עקבתא דמשיחא, חושך כפול ומכופל,\nפונדעסטוועגן, האבנדיק די שליחות און נתינת כח פון אויבערשטן צו מפיץ",[["59","59","המשך תרס״ו ע׳ קפא. ס״ע תסג ואילך."],["60","60","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021375\" data-slug=\"likkutei-sichot\" data-id=\"1300021375\">לקו״ש ח״ב ע׳ 651</a> ואילך."],["61","61","מחז״ל ומפרשים לשה״ש."],["62","62","יחזקאל לו, כה."],["63","63","הל׳ מלכים ספי״א. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051161\" data-slug=\"likkutei-sichot\" data-id=\"1300051161\">לקו״ש ח״ה ע׳ 149</a> בהערה."],["64","64","ראה משל״מ הל׳ כלאים פ״ט הי״א, ובס׳ שנסמנו בשד״ח כללי הפוסקים ס״ו סק״א."]]],[1300201286,"זיין תורה ויהדות, צוזאמען מיט דער הבטחה אז דורך דעם וועט מען מאכן א סוף צום גלות,\nאיז די דאזיגע בשורה טובה גיט אריין א חיות און א שמחה אין דער עבודה פון הפצת התורה והיהדות\n[ע״ד ווי עס שטייט בא יעקב׳ן (וואס זיין נשמה איז כולל אלע נשמות⁶⁵) „וישא יעקב רגליו”⁶⁶, אז טראץ דעם וואס ער איז געגאנגען קיין חרן, חרון אף של מקום בעולם⁶⁷, פונדעסטוועגן, „משנת־בשר בשורה טובה כו׳ נשא לבו את רגליו ונעשה קל ללכת”⁶⁸],\nוואס דער ענין השמחה דריקט זיך אויס אין דעם אז מען טוט עס בזריזות, ביז צו זריזות נפלאה⁶⁹,\nוואס דאס וועט אויך מזרז זיין (און אויך בזריזות נפלאה) די אתחלתא דגאולה, און דערנאך די גאולה שלימה, אז עס וועט זיין „אחישנה” אין דעם „אחישנה” גופא⁷⁰,\nאז בקרוב ממש, און אויך „בעגלא דידן” (בלשון תרגום), וועט זיין די גאולה האמיתית והשלימה דורך משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו במהרה בימינו ממש ובעגלא דידן.\nיא. מאמר ד״ה בראשית ברא.\nיב. שוין גערעדט פיל מאל, אז אלע ענינים וואס רש״י בריינגט בפירושו עה״ת (אפילו ווען ער בריינגט עס פון מאמרי חז״ל) זיינען פשוטו של מקרא [ווי רש״י אליין זאגט כמה וכמה פעמים⁷¹ „ואני לא באתי אלא לפשוטו”], וואס איז פארשטאנדיק אויך צו א „בן⁷² חמש למקרא”.\nדערפון איז מובן, אז דער תירוץ וואס רש״י בריינגט פארענטפערן די טענה „לסטים אתם שכבשתם ארצות שבעה גוים”, אז וויבאלד „כל הארץ של הקב״ה היא” דעריבער איז „ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו” — איז דער תירוץ (וויבאלד אז רש״י האט אים אריינגעשטעלט בפירושו עה״ת) מובן גאר בפשטות, ביז אויך צו א פינף יאריקן קינד.\nאון נאך מער: וויבאלד אז רש״י זאגט עס אלס ענטפער צו אומות העולם — „שאם יאמרו אומות העולם לישראל כו׳ הם אומרים להם” — איז פארשטאנדיק, אז בשעת מען וועט עס זאגן צו אומות העולם [און מען וועט עס ניט פאר־וואסערן, נאר זאגן זיי דברים כהווייתם, אזוי ווי עס שטייט אין תורת אמת], וועלן זיי אנערקענען דעם אמת פון דעם דאזיקן ענטפער,\nביז אז זיי וועלן צוהעלפן אז עס זאל מקויים ווערן דער „לתת להם נחלת גוים”, וויסנדיק אז דאס איז אויך אן עילוי און חשיבות פאר זיי, ביז אז „והיו מלכים אומניך ושרותיהם מיניקותיך”⁷³, אז אפילו די וואס פירן אן מיט די אומות העולם (מלכים און שרותיהם) וועלן זיך בעטן און משתדל זיין, און גרויסן זיך דערמיט, וואס זיי קענען זיין עכ״פ „אומניך” און „מיניקותיך”.",[["65","65","אגה״ק ס״ז."],["66","66","ויצא כט, א."],["67","67","פרש״י ס״פ נח. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151063\" data-slug=\"likkutei-sichot\" data-id=\"1300151063\">לקו״ש חט״ו ע׳ 63־4</a> הערה 3, 7."],["68","68","פרש״י ויצא שם."],["69","69","אגה״ק סכ״א."],["70","70","מכיון ש„אחישנה” תלוי ב„זכו” (סנהדרין צח, א)."],["71","71","פרש״י בראשית ג, ח. וראה בהנסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו״ש ח״ה ע׳ 1</a> הע׳ 1."],["72","72","אבות פ״ה מכ״ב."],["73","73","ישעי׳ מט, כג."]]],[1300201287,"יג. און דאס וואס מען זעט אז מען האט געזאגט צו אחדים פון אוה״ע דעם אויבנדערמאנטן ענטפער (וואס שטייט אין פירש״י), און זיי זיינען געבליבן פאר׳עקשנ׳ט אין זייער טענה „לסטים אתם”\nאיז עס אדער מצד דערויף וואס דער וואס האט זיי געגעבן דעם ענטפער הנ״ל איז עס ביי אים ניט געווען דברים היוצאים מן הלב, אדער עס קען זיין אז דער ענטפער איז (מצד איזה סיבה) נאך ניט דערגאנגען צום שר פון דער אומה.\nס׳איז אבער א זיכערע זאך, אז וויבאלד דער ענטפער הנ״ל איז ארויס־געקומען בגילוי (דורך דעם וואס מען האט עס געזאגט פאר די אומות דא למטה), וועט ער אנקומען (וסו״ס בזריזות) און דערגרייכן אויך צו זייערע שרים שלמעלה\n[וואס זיי דערהערן דעם אמת פון דעם ענטפער, אפילו אויב ס׳איז ניט קיין דברים היוצאים מן הלב],\nאון דורך דעם וועט עס אראפקומען אין דעם לב מלכים ושרים שלמטה, אז אויך זיי וועלן מחליט זיין (אדער וויסנדיק דעם טעם דערפון, אדער ניט וויסנדיק), אז גאנץ ארץ ישראל לגבולותי׳ געהערט צו אידן.\nובכדי צו דורכפירן דאס בפועל, פאדערט זיך בלויז אז אידן זאלן שטיין מיט א תוקף בנוגע צו שלימות הארץ (צוזאמען מיט שלימות התורה און שלימות העם).\nיד. וויבאלד אז מען קען ניט ווארטן ביז אלע וועלן שטיין מיטן תוקף הנ״ל — איז דאך דער פסק דין⁷⁴ אז כל העולם כולו איז נידון על פי רובו, און אז כל העולם כולו שטייט אין א מצב שקול מחצה על מחצה⁷⁵\n[וואס דאס וואס תורת אמת זאגט אן א אידן אז ער זאל קוקן אויף זיך און אויף דער גאנצער וועלט אז זיי זיינען שקול⁷⁶, איז עס ווייל דער אמת איז אזוי, אז „כל השנה כולה”, אלע מאל איז „כל אדם” און „כל העולם” אין א מצב פון מחצה על מחצה⁷⁶],\nוואס דעריבער איז א פסק דין ברור⁷⁵, אז דורך אין פעולה טובה („מצוה אחת”) וואס א איד טוט, סיי במעשה סיי בדיבור סיי במחשבה, איז ער מכריע את עצמו ואת כל העולם כולו לכף זכות, און ער איז גורם לו ולהם תשועה והצלה.\nטו. ויהי רצון, אז כל האמור לעיל בנוגע צו פעולות טובות במעשה דיבור ומחשבה, אנהויבנדיק פון די ענינים און מבצעים כלליים (ראה לעיל סעיף ט׳), זאל זיין באופן דמוסיף והולך ואור,\nאון ווי דער רבי נשיא דורנו שרייבט אין בריף׳ א דבר נפלא, אז בשבת בראשית דארף זיין ניט נאר „כעין השלמה” נאר אויך א „תוספת”, און אז די הוספה וואס מען דארף מוסיף זיין בשבת בראשית איז ב„אור כי טוב”, וואס דער לשון „אור כי טוב”⁷⁷ שטייט אויף דעם אור שנברא ביום ראשון⁷⁸,\nוואס דערפון איז מובן, אז שבת בראשית גיט דעם כח צו יעדער אידן, אפילו צו א פשוט שבפשוטים, צו",[["74","74","רמב״ם הל׳ תשובה פ״ג ה״ב."],["75","75","שם ה״ד."],["76","76","ראה שם ה״ב: ושקול זה אינו לפי כו׳."],["77","77","בראשית א, ד."],["78","78","ראה בארוכה בכ״ז שיחת שבת בראשית תשי״א (נדפסה בלקו״ש ח״ב ע׳ 443 ואילך)."]]],[1300201288,"אויפטאן (דורך אין פעולה טובה, במעשה או בדיבור או במחשבה) א הוספה אין „אור כי טוב”.\nאון ממשיך זיין דעם אור על כל השנה כולה, אז עס זאל זיין א שנת אורה, און דערנאך אויך די אלע איבעריקע ענינים טובים וואס הויבן זיך אן מיט די אותיות פון אל״ף בי״ת, ביז צו שנת תורה,\nביז עס וועט זיין דער מבצע הכי גדול, שנת גאולה — גאולה האמיתית והשלימה ע״י משיח צדקנו, בקרוב ממש.\n• • •\nטז. כנהוג בכל שנה, זאל מען אויך היינט טיילן בשליחותי בקבוקים של משקה צו די וואס פארן אין שליחות, און צו די וואס פארן אין מוסדות — בכדי זיי זאלן מיטנעמען מיט זיך פון חודש תשרי אין וועלכן מען איז געווען צוזאמען, עכ״פ א מקצת פון דעם חודש, ווארום כשאתה תופס במקצתו אתה תופס בכולו.\nיז. אזוי ווי מען דארף דאך פארבינדן יעדער ענין מיט א פעולה גשמית⁷⁹ — איז בקשר צום ענין הגאולה וואס מען האט גערעדט פריער, איז א דבר הכי נכון וטוב — ובפרט נאך במוצאי שבת — צו פראווען א סעודת מלוה מלכא, וואס ווערט אנגערופן (און איז) „סעודתא דדוד מלכא משיחא”⁸⁰,\nצו אראפבריינגען אים בשמחה ובטוב לבב, אז ער זאל נתגלה ווערן למטה מעשרה טפחים, ויוליכנו קוממיות לארצנו, ובקרוב ממש.",[["79","79","ראה רמב״ן לך יב, ו. וראה לבוש לרקנטי לך שם. דרשות הר״ן דרוש ב׳."],["80","80","סידור האריז״ל (להר״ש מרשקוב). פע״ח סוף שער השבת."]]],[1300201289,"בס״ד. מוצאי ש״פ נח - בחדרו - ה׳תשל״ח\nמים רבים לא יוכלו לכבות את האהבה ונהרות לא ישטפוה גו׳¹, ואיתא בדרושי רבותינו נשיאינו², שמים רבים הם כל טרדות הפרנסה והמחשבות שבעניני עוה״ז, ועכ״ז לא יוכלו לכבות את האהבה המסותרת שיש בכל נפש מישראל. ונהרות לא ישטפוה, שגם כאשר מחשבות הנ״ל הם מטרידות ביותר, עד שהן משוטטות במרוצה בתמידות בלי הפסק כלל, כמו הנהרות³ שנובעים תמיד בלי הפסק וניידי ואזלי בשטף גדול⁴, מ״מ לא ישטפוה להאהבה (ולא יוכלו לכבותה⁵).\nב) וביאור דיוק הלשון „טרדות הפרנסה״, הנה כתיב⁶ יגיע כפיך כי תאכל גו׳, וידוע הדיוק בזה⁷, יגיע כפיך דוקא אבל לא יגיעת המוח והלב. והיינו דהגם אשר (מצד זה שהשפע בעוה״ז נמשכת דרך לבוש הטבע⁸) צריך להיות עשי׳ שבזה תתלבש השפע שלמעלה, וכמ״ש⁹ וברכך הוי׳ אלקיך בכל אשר תעשה (דוקא), ועד שלפעמים (מצד גודל ההעלם וההסתר¹⁰) צריכים גם ליגיעה, מ״מ אין צריך להעסיק בעשי׳ זו כ״א רק את כחות החיצונים שלו, יגיע כפיך [כפים ושארי אברים החיצונים¹¹], אבל לא את כחות הפנימיים והנעלים (שבמוח ולב), כי כחות אלו צריכים להיות מוקדשים לשמש את קונו, שזהו תכלית בריאתו¹². והגם שמכיון שהשפע מתעלם ומסתתר בלבושי הטבע צריך להשתמש גם בשכלו לצורך העסק, הוא",[["1","1","שה״ש ח, ז."],["2","2","תו״א ר״פ נח. תו״ח נח נח, ד ואילך. מים רבים תרל״ו (בתחלתו. פע״ה)."],["3","3","משא״כ „מים״, מי הים „הם מכונסים ועומדים״ (תו״א ותו״ח שבהערה הבאה)."],["4","4","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670249\" data-slug=\"torat-chaim\" data-id=\"2300670249\">תו״ח שם סב, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370038\" data-slug=\"torah-or\" data-id=\"3901370038\">תו״א ט, ב</a> (ד״ה אם יתן). יו״ד, א (ד״ה וזהו הפי׳)."],["5","5","כ״ה בתו״א שם, ש„לא יוכלו לכבות גו׳״ קאי גם על „נהרות״."],["6","6","תהלים קכח, ב."],["7","7","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380483\" data-slug=\"likkutei-torah\" data-id=\"4001380483\">לקו״ת שלח מב, ד</a>. חוקת סו, ג. ובכ״מ."],["8","8","דרמ״צ קז, א (וראה גם שם ח, א). קונטרס ומעין מכ״ה פ״א."],["9","9","ראה טו, יח. ובספרי שם: יכול יהא יושב ובטל* ת״ל בכל אשר תעשה."],["10","10","להעיר, ש„בזעת אפיך תאכל לחם״ (בראשית ג, יט) נתחדש לאחרי חטא עה״ד."],["11","11","לקו״ת שלח שם."],["12","12","קדושין בסופה. *) כן הובא בקונט׳ ומעין שם ובכ״מ. ובספרי שלפנינו: יכול בטל. וביל״ש (עה״פ): יכול כשעומד ובטל כו׳."]]],[1300201290,"רק מה שמוכרח להעשי׳, אבל לא באופן דיגיעה בהתחכמות ותחבולות. ובפרט שברכת הוי׳ היא תעשיר¹³, והעסק אינו אלא לבוש לברכת הוי׳ (ולא שהעסק הוא מקור פרנסתו ח״ו), הרי מובן¹⁴, שבדוגמת הלבושים „המרבה בלבושים לא העדיף מאומה, ואדרבה¹⁵ מקלקל יותר״¹⁶. וזהו דיוק הלשון „טרדות הפרנסה״, דהגם שהוא במצב נמוך שיש לו טרדות הפרנסה [שזה מראה אשר אינו מתבונן כדבעי אליבי׳ דנפשי׳ שברכת הוי׳ היא תעשיר¹⁷], מ״מ, הנה גם הטרדות לא יוכלו לכבות ח״ו את האהבה המוסתרת שבכ״א מישראל.\nג) והנה החידוש בזה שמים רבים לא יוכלו לכבות את האהבה, דידוע דשרש המים רבים [שהוא טרדות הפרנסה] הוא בבחי׳ התהו שקדם לתיקון¹⁸. דזהו שנקראים מים רבים להיותם „רבים״ (גם) מצד שרשם ומקורם¹⁹. וזהו הרבותא²⁰ בזה שמים רבים לא יוכלו לכבות את האהבה ונהרות לא ישטפוה, דהגם ששרש המים רבים והנהרות²¹ הוא בבחי׳ התהו שקדם לתיקון (שרש נפש האלקית), מ״מ לא יוכלו לכבות ח״ו את האהבה שבנפש האלקית²². והטעם לזה הוא (כמ״ש לפנ״ז²³) רשפי׳ רשפי אש שלהבת י־ה²⁴, ששרש הנשמה והאהבה מסותרת שבה הוא בעצמות אוא״ס שלמעלה גם מבחי׳ תהו. ששרש האהבה שבנפש האלקית הוא בבחי׳ שלהבת י־ה כמו שהיא קשורה וגנוזה בגחלת (רשפי אש²⁵), ולמעלה יותר²⁶ — כמו שהוא",[["13","13","משלי י, כב."],["14","14","ראה בכ״ז דרמ״צ קז, ב. קונט׳ ומעין שם פ״ב."],["15","15","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380051\" data-slug=\"likkutei-torah\" data-id=\"4001380051\">לקו״ת</a> חוקת שם: ואדרבה מחשבה מועלת. וראה גם ד״ה בהקדמה (ג, ב)."],["16","16","דרמ״צ שם. ועד״ז ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">לקו״ת תצא לז, רע״ג</a>."],["17","17","דרמ״צ שם (קז, א ואילך). קונט׳ ומעין שם פ״ג. ד״ה וידעת תרנ״ז."],["18","18","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו״א יו״ד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670173\" data-slug=\"torat-chaim\" data-id=\"2300670173\">תו״ח שם סא, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560388\" data-slug=\"or-hatorah-hb\" data-id=\"8316560388\">אוה״ת נח (כרך ג׳) תרס, ב</a>."],["19","19","להעיר, שבתהו היו אורות מרובים. וראה אוה״ת שם, שענין מים רבים הוא דוגמת ענין רשות הרבים שהוא בחי׳ עולם הנקודים."],["20","20","ועד „שזהו רבותא גדולה״ (תו״ח שם)."],["21","21","בתו״א שם, ש„מים רבים״ ו„נהרות״ הם ב׳ בחי׳ בתהו."],["22","22","תו״ח שם."],["23","23","שה״ש ח, ו."],["24","24","ראה גם שהש״ר עה״פ (בסופו): שלהבת י־ה .. כאש של מעלה .. ולא המים מכבין לאש. וראה בפירוש מהרז״ו שם."],["25","25","ראה פירוש הראב״ע לשה״ש שם (וראה גם מצודת שם): רשפי׳ — גחלי׳. ובתיב״ע שם: גומרין דאשא (אוה״ת והמשך מים רבים שבהערה 27)."],["26","26","ראה ד״ה ואברהם זקן תרס״ו. ובכ״מ."]]],[1300201291,"בבחי׳ צור²⁷ (שלמעלה מהוי׳²⁸), ששם הוא שרש הנשמה, כמבואר בלקו״ת²⁹ בפירוש הכתוב³⁰ והרוח תשוב אל האלקים אשר נתנה, שבחי׳ האלקים (אשר נתנה) הוא בחי׳ צור הנ״ל.\nד) והנה לא זו בלבד שאין ביכולת המים רבים הנ״ל לכבות ח״ו את האהבה של הנשמה, אלא יתירה מזו, שעל ידם נעשה יתרון בהאהבה. והוא שע״י ירידת הנשמה למטה בעוה״ז והתלבשותה במים רבים הנ״ל היא מגיעה למדריגה נעלית יותר ממדריגתה קודם ירידתה למטה³¹. [וזהו תכלית הכוונה של מים רבים הנ״ל. ולכן סו״ס אין ביכולתם לכבות את האהבה, לפי³² שתכלית עומק כוונתם של המים רבים גופא הוא אדרבא בכדי לפעול יתרון בהאהבה³³]. ובעבודה העילוי שנעשה בהנשמה ע״י ירידתה למטה והתלבשותה במים רבים הנ״ל הוא שבאה לענין התשובה³⁴. וכידוע³⁵, שהנשמות קודם ירידתן לגוף הם בבחי׳ צדיקים גמורים, והיתרון שנעשה בהם ע״י ירידתן בגוף הוא שנעשים בבחי׳ בעלי תשובה, אשר במקום שבעלי תשובה עומדין צדיקים גמורים אינם עומדין³⁶, ויתירה מזו, שאין יכולין לעמוד בו³⁷, שאין זה (אפילו) ביכולת³⁸ שלהם. וזהו הטעם שירדה הנשמה למטה, כי ענין התשובה [הגם שאינה על עבירות דוקא, כ״א השבת הנפש למקורה ושרשה³⁹] שייך דוקא כאשר אינו נמצא במקומו האמיתי (מקורו ושרשו), שאז שייך שישוב לשרשו ומקורו, בחי׳ והרוח תשוב אל האלקים אשר נתנה⁴⁰. ומכיון שמעלת הבע״ת היא נעלית יותר ממעלת הצדיקים [ועד",[["27","27","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560310\" data-slug=\"or-hatorah-hb\" data-id=\"8316560310\">אוה״ת נח</a> תרכא, ב. מים רבים תרל״ו פע״ג. וראה גם אוה״ת שה״ש עה״פ (ע׳ תשמו)."],["28","28","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו״ת אחרי כו, ג</a>."],["29","29","ר״פ האזינו (עב, א). שמע״צ פה, רע״ב."],["30","30","קהלת יב, ז."],["31","31","תו״א ותו״ח שבהערה 2. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560311\" data-slug=\"or-hatorah-hb\" data-id=\"8316560311\">אוה״ת נח כרך ג</a> תרכב, א. מים רבים הנ״ל פע״ה ואילך."],["32","32","והיינו, דזה שאין ביכולתם לכבות את האהבה הוא לא רק מצד שרש האהבה (כנ״ל ס״ג), אלא גם מצד „תכלית עומק כוונתם״ של המים רבים גופא."],["33","33","ראה המשך מים רבים שם."],["34","34","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו״א שם ט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו״ח שם נט, סע״ד</a>."],["35","35","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו״ת בלק עג, סע״א</a>. ובכ״מ. ובלקו״ת שם, שזהו „התירוץ האמיתי״ למה ירדה הנשמה לעוה״ז."],["36","36","ברכות לד, ב."],["37","37","רמב״ם הל׳ תשובה פ״ז ה״ד (וגם בלקו״ת שם מובא הגירסא אינם יכולים)."],["38","38","שלמעלה מבחי׳ כח (המשך ר״ה תש״ג פי״ג. ועוד)."],["39","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380815\" data-slug=\"likkutei-torah\" data-id=\"4001380815\">לקו״ת ראה כד, ד</a>. ש״ש סו, ג. ובכ״מ."],["40","40","לקו״ת ר״פ האזינו."]]],[1300201292,"שהחילוק שביניהם הוא שלא בערך, שלכן מקום שבעלי תשובה עומדין אין צדיקים גמורים יכולין לעמוד בו, כנ״ל], לכן, ע״י ענין התשובה שמתחדש בהנשמה בירידתה למטה ה״ה מתעלית יותר גם מכפי שהיתה בשרשה, בבחי׳ האלקים אשר נתנה⁴¹.\nה) והגם ששרש הנשמות הוא בעצמותו ית׳ שלמעלה מכל הגילויים, וכדמוכח (גם) ממה שארז״ל⁴² במי נמלך בנשמותיהן של צדיקים, שענין ההמלכה הוא גם על גילויים הכי נעלים (מכיון שהם ברצון ולא בהכרח ח״ו), הרי מובן שהנשמות שבהן נמלך הן למעלה מכל הגילויים⁴³, מ״מ שייך לומר שע״י התשובה (בירידתן למטה) נעשית בהן עלי׳ גם לגבי הדרגא שהי׳ בשרשן. ויובן זה ע״פ מ״ש הה״מ⁴⁴ בפירוש מרז״ל⁴⁵ ישראל עלו במחשבה, שהוא כמשל אדם שיש לו בן, דגם כשהבן עבר מכנגד פניו והלך מאתו, עכ״ז נחקקה הצורה של הבן במחשבה של האב. אלא שבבני אדם שייך זה דוקא במי שיש לו בן כו׳. אבל אצל השי״ת שייך זה לומר אף קודם שנבראו ישראל הי׳ נחקק צורתם במחשבה, כמ״ש רז״ל⁴⁵ ישראל עלו במחשבה, כי אצלו ית׳ העבר והעתיד אחד. ומובן מזה, דזה מה שהנשמות מושרשות בעצמותו ית׳ ובהם נמלך כו׳ — הו״ע הנשמות כמו שהן בבחי׳ נברא (וכמו שהן יורדות למטה), ורק ש(גם) צורה זו היא חקוקה במחשבתו ית׳, לפי שאצלו ית׳ העבר והעתיד אחד. וכידוע⁴⁶ בפירוש במי נמלך כו׳, שזהו מה שעלה לפניו ית׳ התענוג שיתענג כביכול בעבודת הנשמות למטה. ועפ״ז יובן ענין העלי׳ שנעשה בהנשמות ע״י ירידתן למטה, הגם שגם לפני ירידתן הן מושרשות בעצמותו ית׳, כי זה מה שהן מושרשות בעצמותו ית׳ (ובהם נמלך כו׳) הוא מצד ידיעתו ית׳ שתהי׳ אח״כ ירידתן למטה כו׳ וישלימו הכוונה⁴⁷. והגם שגם בתחלה יודעים בודאות גמורה שישלימו",[["41","41","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו״ת שם עב, רע״א</a>: והתשובה היא להיות .. כמו קודם ירידתה ויתר על כן. ומ״ש והרוח תשוב אל האלקים אשר נתנה — ראה לקמן הערה 47."],["42","42","רות רבה רפ״ב."],["43","43","ד״ה העושה סוכתו תרצ״ט פי״ב. וראה גם המשך תער״ב (ח״ב) ע׳ תתק."],["44","44","אור״ת (ב, ג) עה״פ נעשה אדם — הובא גם בהמשך הנ״ל ס״ע תתקב (ומהמשך הענין שם (ראה שם ריש ע׳ תתקג) משמע שזה שייך גם לענין במי נמלך כו׳]."],["45","45","ב״ר פ״א, ד."],["46","46","המשך ר״ה תש״ג פ״ג. ובכ״מ."],["47","47","ועפ״ז יובן מ״ש „והרוח תשוב אל האלקים אשר נתנה״ — אף שע״י התשובה נעשית בעילוי יותר — כי גם העילוי דנשמה שע״י התשובה הוא בבחינת „האלקים אשר נתנה״ (שרש הנשמות בעצמותו ית׳). אלא שבתחלה הוא רק בכח, כבפנים. ועצ״ע."]]],[1300201293,"הכוונה, הרי זהו בכח, ותכלית העילוי (והכוונה) הוא⁴⁸ הפועל. [וזהו גם דיוק הלשון במי נמלך בנשמותיהן של צדיקים, שבהיותן בבחינת ההמלכה [שאז העילוי שלהן הוא בכח, שיודעים שישלימו הכוונה] הן בבחינת צדיקים, ולאחרי ירידתן למטה [שאז הם משלימים את הכוונה בפועל] נעשים בבחי׳ בעלי תשובה].\nו) ויש לקשר זה עם ענין ד„ויעקב הלך לדרכו״ (שבמוצאי שבת פרשת נח⁴⁹), דהגם שלאחרי חודש תשרי הוא הולך לדרכו (גם) בעניני הרשות ובעובדין דחול, ועד לבחינת מים רבים הנ״ל, מ״מ עי״ז גופא הוא מתעלה יותר, שנעשה בבחינת מהלך⁵⁰, וכלשון הכתוב⁵¹ ויעקב הלך לדרכו. וידיעה זו [שהירידה (לדרכו בעניני הרשות וכו׳) היא צורך עלי׳] פועלת שההליכה תהי׳ בשמחה ובטוב לבב [וע״ד מ״ש⁵² גבי יעקב וישא יעקב רגליו גו׳ משנתבשר בשורה טובה כו׳]. וזה פועל שעבודתו תהי׳ בתכלית השלימות ולמעלה ממדידה והגבלה (בחי׳ בכל מאדך⁵³), כי שמחה פורץ⁵⁴ כל הגדרים. וע״י שעובד עבודתו [בכל הג׳ קוין (ג׳ בני נח⁵⁵) דתורה עבודה וגמ״ח] בתכלית השלימות ובשמחה ובטוב לבב, נמשך לו גם ברכת הוי׳ בכל המצטרך לו [בג׳ הענינים דבני חיי ומזוני⁵⁶] בתכלית השלימות ובשמחה ובטוב לבב, הן ברוחניות והן בגשמיות, וברוחניות ובגשמיות גם יחד.",[["48","48","ראה בארוכה לקמן בהשיחה סעיף ד׳ ואילך."],["49","49","ראה בארוכה בהשיחה סעיף ב׳ ואילך. ושם (ס״ג ואילך), שהחידוש שבמוצאי ש״פ נח על מוצאי שבת בראשית הוא — שאז ישנו כבר הענין ד„ויעקב הלך לדרכו״ בפועל."],["50","50","וע״ד הידוע (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו״א ל, סע״א</a> ואילך. ובכ״מ) בענין העלי׳ שע״י (כללות) ירידת הנשמה למטה, שהעלי׳ היא מה שנעשית בבחי׳ מהלך."],["51","51","ויצא לב, ב. וראה לעיל ע׳ 270־1."],["52","52","ויצא כט, א. פירש״י שם. וראה לעיל ע׳ 272־3."],["53","53","להעיר, שזהו (בחי׳ בכל מאדך) גם העילוי שנעשה ע״י ה„מים רבים״ (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו״א ט, א</a>. ובכ״מ)."],["54","54","ד״ה שמח תשמח תרנ״ז ע׳ 49 (סה״מ תרנ״ז ע׳ רכג) ואילך."],["55","55","ג׳ בני נח הם בחי׳ חג״ת (תו״א ר״פ וישב ואוה״ת נח סג, א), ענין הג׳ קוין דתורה עבודה וגמ״ח."],["56","56","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490173\" data-slug=\"or-hatorah-hb\" data-id=\"8316490173\">אוה״ת (כרך ד</a>׳) וירא תשנו, סע״א ואילך."]]],[1300201294,"שיחת מוצאי ש״פ נח - בחדרו - ה׳תשל״ח.\nא. קומענדיק פון סיום חודש תשרי, חודש השביעי\n— שביעי (אויך) מלשון שובע¹, ווי דער מדרש זאגט²: „שהוא משובע בכל״, אז דער חודש איז אנגעזעטיקט מיט אלע ברכות און מיט אלע גוטע זאכן, סיי בגשמיות סיי ברוחניות.\nאון זייענדיק א חודש כללי³, וערן נמשך, די אלע ענינים מיט וועלכע ער איז „משובע״, בכל השנה כולה⁴ —\nצוזאמען דערמיט וואס איצטער (במוצאי שבת) איז אויך דער סיום און אפשלוס פון א וואך\n— וואס סיי דער אפשלוס פון דער וואך, סיי דער אפשלוס פון חודש (השביעי) איז (ווי אין אלע ענינים פון קדושה, וואס עס דארף זיין „מעלין בקודש״⁵) אויך א התחלה פון און עלי׳, אז עס זאל זיין נאך און נאך בעסער ווי ס׳איז געווען ביז איצטער —\nאיז כאן המקום והזמן צו מאכן א סך־הכל פון דער נקודה העיקרית וואס האט זיך געדעדט אין די פריערדיקע שיחות⁶, אז דער ענין כללי וואס מען נעמט מיט פון חודש תשרי על כל השנה כולה איז — די עבודה פון „ויעקב הלך לדרכו״\n[וואס נוסף צום תוכן הכללי פון „ויעקב הלך לדרכו״ (וואס איז אלע דריי ווערטער צוזאמען), זיינען פאראן אויך ענינים און הוראות פרטיות אין יעדן ווארט באזונדער (אין „ויעקב״, אין „הלך״ און אין „לדרכו״⁷). וואס יעדער פרט (פון די דריי ענינים) גיט אויך צו אין דעם תוכן הכללי פון „ויעקב הלך לדרכו״],\nוואס דאס האט א שייכות מיוחדת מיטן סיום און אפשלוס פון דער וואך פון פרשת נח — די וואך וואס נאך שבת בראשית כדלקמן (סעיף ב׳ ואילך),\nאון דאס האט אויך א שייכות מיוחדת מיטן תוכן פון פרשת נח [וואס ס׳איז דאך ידוע דער ווארט פון אלטן רבי׳ן⁸ אז מען דארף לעבן מיט דער פרשה פון דער וואך], כדלקמן (סעיף ז׳ ואילך).\nב. אע״פ אז דער „ויעקב הלך לדרכו״ שבמוצאי שמחת תורה איז שוין אויך בנוגע צו עניני הרשות ועובדין דחול⁹ („לדרכו״ בפשטות), ביז אז דער־נאך במוצאי שבת בראשית הויבט זיך שוין אן פילן דער חול פון די ימות החול¹⁰\nפונדעסטוועגן, איז בשעת עס קומט מוצאי שבת פרשת נח — טוט זיך אויף א נייער ענין אין „ויעקב הלך לדרכו״, וואס איז ניטא במוצאי שבת בראשית.",[["1","1","ראה גם קיצורים והערות לתניא ע׳ נח."],["2","2","ויק״ר פכ״ט, ח. וראה ד״ה ירים של ר״ה השי״ת בתחלתו."],["3","3","אוה״ת סוכות ע׳ א׳תשנו. ברכה ס״ע א׳תתסו ואילך. ד״ה צהר תעשה תש״ב פ״ג. ועוד."],["4","4","ובלשון הבעש״ט (היום יום ע׳ צ): שהוא המושבע והמשביע .. על כל השנה."],["5","5","ברכות כח, א. וש״נ."],["6","6","דמוצאי שמח״ת ומוצאי שבת בראשית."],["7","7","כמשנת״ת בארוכה לעיל ע׳ 269 ואילך."],["8","8","סה״ש תש״ב ע׳ 29 ואילך."],["9","9","ראה ד״ה להבין ענין שמח״ת תשל״ח סעיף ז׳ (לעיל ע׳ 259). לעיל ע׳ 267 ואילך."],["10","10","ראה לעיל ע׳ 269."]]],[1300201295,"[נוסף אויף דעם וואס לויט דעם מכתב הידוע¹¹ איז בשבת בראשית דארף זיין ניט נאר „כעין השלמה״ נאר אויך א „תוספת״, ביז צו א „תוספת״ אין „אור כי טוב״, וואס דאס (דער לשון „אור כי טוב״) שטייט¹² אויפן אור שנברא ביום הראשון — קומט דאך אויס, אז ביז (מוצאי) שבת בראשית איז דא (ובמילא — גובר) דער „ויעקב הלך לדרכו״ לויטן פירוש¹³ „לדרכו״ איז „בחי׳ תורה ומצות, דתורה אקרי¹⁴ דרך״, ווארום דעם אור שנברא ביום ראשון איז דאך „גנזו בתורה״¹⁵].\nוהביאור בזה¹⁵*:\nבמוצאי שבת בראשית, אע״פ אז א איד איז מחליט בהחלטה תקיפה [און די החלטה איז באופן של שלימות. ובפרט נאך אז עס קומט נאך דער עבודה פון חודש תשרי] אז בא אים זאל זיין די עבודה פון „ויעקב הלך לדרכו״ [אז זיין גיין אין די עובדין דחול („לדרכו״ בפשטות) זאל זיין „לדרכו״ פון יעקב׳ן, די ספעציעלע וועג פון א אידן, די וועג פון תורה ומצוות], פונדעסטוועגן, וויבאלד אז דאס איז בלויז בהחלטתו, און ס׳איז נאך ניט געקומען בפועל ממש — איז „אל יתהלל חוגר כמפתח״¹⁶;\nמשא״כ במוצאי שבת פרשת נח, לאחרי ווי עס איז שוין א דורך א גאנצע וואך (פון מוצאי שבת בראשית) וואס אין יעדער טאג פון דער וואך איז „כל יומא ויומא עביד עבידתי׳״¹⁷\n— וואס דער היקף פון שבעת ימי השבוע איז כולל כל משך הזמן [וכידוע¹⁸ דער טעם אויף דעם וואס יעדער וואך הויבט מען אן ציילן: יום ראשון, יום שני וכו׳ (אע״פ אז ס׳זיינען שוין דורכגעגאנגען אלפים ורבבות ימים פון ברה״ע), ווייל יעדער וואך חזר׳ן זיך איבער די זעלבע ימי ההיקף] —\nדעמולט קען שוין זיין „יתהלל״, וויבאלד אז מען איז שוין אין א מצב פון „מפתח״.\nג. לכאורה קען מען פרעגן אויף דעם: דער טעם (בפשטות) פון „אל יתהלל חוגר כמפתח״ איז¹⁹ מצד דעם וואס אפילו בשעת ער (דער חוגר) איז א גבור וכו׳, איז מען נאך ניט זיכער בבירור גמור, ס׳איז נאך דא א מקום לספק, צי ער וועט מנצח זיין. ולפי זה:\nוויבאלד אז כל ישראל זיינען בחזקת כשרות²⁰ [וואס אויף חזקה פארלאזט מען זיך בנוגע צו די גרעסטע ענינים²¹], איז דאך במילא זיכער אז די החלטות",[["11","11","דמחרת יוהכ״פ תרפ״ט (נדפס בסה״מ תשי״א ע׳ 48)."],["12","12","בראשית א, ד."],["13","13","תו״א ס״פ ויצא."],["14","14","קדושין ב, ב."],["15","15","נסמן לעיל ע׳ 271 הערה 55. 15*) ועוד ענין בזה: מכיון שחודש תשרי הוא חודש כללי (כנ״ל. ובהנסמן בהערה 3) — הרי ענין „ויעקב הלך לדרכו״, בעבודה פרטית, מתחיל בעיקר לאחרי חודש תשרי. ומכיון שה„ויכלו״ של הימים דסיום חודש תשרי הוא בשבת פרשת נח [שבת הראשונה שלאחרי חודש תשרי] היינו, דעד אז מאיר עדיין הענין דחודש הכללי — נמצא [ע״ד המבואר לעיל ע׳ 269] שעיקר הענין ד„ויעקב הלך לדרכו״ מתחיל במוצאי ש״פ נח."],["16","16","מ״א כ, יא."],["17","17","זח״ג צד, ב."],["18","18","ד״ה ויהי ביום השמיני תש״ד (סעיף יו״ד). וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">לקו״ת שה״ש כה, א</a>."],["19","19","ראה רש״י מלכים שם: שאינו יודע אם ינצח כו׳."],["20","20","רמב״ם הל׳ קדה״ח פ״ב ה״ב. וראה גם הל׳ יסוה״ת ספ״ז."],["21","21","כמובן גם מזה שסומכין על עדותן בנוגע לכל דבר (ראה לח״מ להל׳ קדה״ח שם)."]]],[1300201296,"וואס אידן האבן מחליט געווען במוצאי שבת בראשית, וועלן זיי דורכפירן בפועל — טא וואס איז דער אויפטו פון דעם „ויעקב הלך לדרכו״ (בנוגע צו יעקב׳ן) ווי ער איז שוין בפועל (במוצאי ש״פ נח) אויף דער החלטה בזה (שבמוצאי שבת בראשית) ?\nאיז דער ביאור אין דעם: דער תכלית העילוי והשלימות פון יעדער ענין איז, אז ער זאל זיין ניט בלויז „בכח״ נאר ער זאל קומען „בפועל״ (אפילו ווען „בכח״ איז אין אזא אופן אז ס׳איז זיכער אז ביכלתו לבוא לידי פועל), כדלקמן (סעיף ד׳ ואילך). איז דעריבער, וויבאלד אז במוצאי שבת בראשית איז נאך ניטא דער בפועל פון „ויעקב הלך לדרכו״ (אע״פ אז מען איז שוין זיכער אז דער־נאך וועט זיין דער בפועל), איז עס נאך ניט דער תכלית השלימות.\nד. א הוכחה אויף דעם (אז דער תכלית השלימות פון יעדער ענין איז דוקא ווען ער קומט בפועל) איז פון כללות ענין הבריאה\n[וואס דאס (ענין הבריאה) האט א שייכות מיוחדת מיט חודש תשרי (אותיות ראשית²¹* וראש שלו — ראש השנה), ובפרט מיט (שמח״ת און) שבת בראשית וואו מען לייענט „בראשית ברא אלקים את השמים ואת הארץ״, אז די שמים וארץ וכל צבאיהם וערן באשאפן מחדש. ווארום וויבאלד אז תורת אמת זאגט „בכל יום יהיו (בעיניך) חדשים״²² — איז דאך דער אמת אזוי, אז בכל שנה ווען מען לייענט אין תורה בראשית ברא וגו׳ ווערט באשאפן די גאנצע וועלט מחדש.\nאון אע״פ אז א איד האט בחירה חפ־שית צי ער זאל מקיים זיין דעם ציווי „בכל יום יהיו בעיניך חדשים״ — איז דאך די בחירה בלויז בנוגע צו אים, אז בא אים זאלן זיי זיין „חדשים״: דאס וואס דברי תורה זיינען אלע מאל „חדשים״ (און אז בכל שנה, ווען מען לייענט בראשית ברא וגו׳, וערן באשאפן שמים וארץ וכל צבאיהם מחדש) — איז ניט אפהענגיק בבחירתו;\nאון דאס וואס פאדערט זיך פון אים אז ער זאל בוחר זיין, איז אז אויך ער זאל אנערקענען דעם אמת, לעבן מיט אים, און איבערלעבן דאסניי דעם ענין אין תורה וועלכן ער לערנט],\nוואס איינער פון די טעמים אויף דער בריאה איז (ווי ער זאגט אין זהר²³) „בגין דישתמודעון לי׳״, און בלשון העת״ח²⁴ — „שיתגלו שלימות כחותיו וכו׳״, אז די „כחות״ פון אויבערשטן זאלן ארויסקומען בגילוי, ובפועל.\nולכאורה איז ניט מובן: בשעת עס רעדט זיך וועגן א כח מוגבל, וואס איז שייך אז ער זאל (מצד איזה טעם) ניט קענען קומען לפועל — איז פאר־שטאנדיק, אז ס׳איז דא א מעלה אין דעם וואס ער ווערט נתגלה בפועל; וויבאלד אבער אז „כחותיו״ ית׳ זיינען אן קיינע הגבלות, און ס׳איז ניט שייך אז עס זאל זיין אן ענין וואס זאל זיין מונע זיין פון קומען לפועל — איז וואס פאר א עילוי קומט צו דורכן „שיתגלו כו׳״ (דורך זייער קומען לפועל) ?",[["","","21*) אוה״ת סוכות שבהערה 3."],["22","22","פרש״י יתרו יט, א. עקב יא, יג. תבא כו, טז."],["23","23","פרשת בא מב, ב."],["24","24","בתחלתו. וכן בשער ההקדמות הקדמה ג׳. וממ״ש בע״ח שם „וכבר נתבאר טעם זה בספר הזהר . . וגם בס׳ בא כו׳״, מובן שבכללות הו״ע אחד עם „בגין דישתמודעון לי׳״. וראה גם המשך תרס״ו ע׳ ז, ד״ה שוקיו עמודי שש תש״ב פ״ח, אשר ענין „יתגלו כו׳״ הוא פירוש במאה״ז „בגין כו׳״."]]],[1300201297,"בשלמא להטעם²⁵, אז די כוונה איז מצד דעם וואס „נתאוה הקב״ה להיות לו ית׳ דירה בתחתונים״²⁶ — איז פאר־שטאנדיק, אז ס׳איז ניט מספיק דאס וואס מצד כחו ית׳ קען זיין „דירה בתחתונים״, וויבאלד אז מען וויל האבן (ניט דעם גילוי פון כחו ית׳ (אז ער קען זיך געפינען אויך „בתחתונים״), נאר די מציאות פון) „דירה בתחתונים״²⁷, דארף זיין א פעולה בתחתונים;\nמשא״כ לטעם הבריאה אז דאס איז „שיתגלו שלימות כחותיו כו׳״ (ארויס־באקומען די שלימות כחותיו של הקב״ה), איז ניט מובן (כנ״ל): וואס פאר א עילוי קומט צו דורכן „שיתגלו כו׳״ ? ²⁸\nה. עד״ז געפינט מען אויך בנוגע צו ירידת הנשמה בגוף (שהי׳ בר״ה — ויפח באפיו נשמת חיים — נשמת אדה״ר שכוללת כל הנשמות²⁹ — ושקורין עד״ז בשמח״ת ובפ׳ בראשית), אז איינער פון די טעמים אויף דעם איז³⁰, בכדי אז די כחות פון דער נשמה [צו זיין פארבונדן מיטן אויבערשטן, אפילו ווען זי איז אין א גוף גשמי וכו׳] זאלן ארויסקומען בפועל ובגילוי.\nוכידוע³¹ המשל פון א מלך וואס האט געהאט א בן יחיד מושלם בכל המעלות, און האט אים אוועקגעשיקט למקום רחוק, בכדי ארויסצובריינגען זיינע כשרונות מן הכח אל הפועל, ווי ער קען זיך מפרנס זיין מיגיע כפיו און דארף ניט אנקומען צו נכסי אביו.\nולכאורה: וויבאלד אז דער מלך ווייס די כשרונות הנעלים פון בנו יחידו — ובפרט ווי דאס איז אין נמשל, וואס דער מלך איז יודע עתידות און ווייס בודאות אז יעדע נשמה וועט ארויסברייגען",[["25","25","המשך תרס״ו שם. ד״ה שוקיו הנ״ל פ״ס. התיווך של ביאור זה עם הביאור שבזהר ועת״ח שם — ראה המשך תרס״ו ע׳ תמו (הובא לקמן הערה 28). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101021\" data-slug=\"likkutei-sichot\" data-id=\"1300101021\">לקו״ש ח״י ע׳ 21</a> הערה 69."],["26","26","תנחומא נשא טז. במדב״ר פי״ג, ו. <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["27","27","ואפילו את״ל שאין בזה מעלה ושלימות — הרי הענין ד„נתאוה״ הוא למעלה מהטעם."],["28","28","בהמשך תרס״ו שם (ע׳ ה) ובד״ה למען ידעו תש״ב (פס״ו), ש„א״א לומר שזו (הענין ד„יתגלו שלימות כחותיו כו׳״) היא תכלית הכוונה האמיתית״, כי למעלה „אין כח חסר פועל״ — הרי מדגיש „האמיתית״ — וכמבואר בסוף ההמשך (ע׳ תמו) דיתגלו וכו׳ הוא הטעם בנשמות דאצילות ובאצילות. ועוד י״ל דהשאלה שבפנים השיחה אינה השאלה שבתרס״ו ותש״ב שם. כי זה מה שלמעלה „אין כח חסר פועל״ — הכוונה בזה היא שמצד הכח נעשה כבר גם הפועל [וכמובא בתרס״ו שם מפרדס ש״א פ״ג: כאשר עלה ברצונו כו׳ אז נאצל ונצטייר כו׳. וראה בארוכה ד״ה שובה, ולקחתם אתכם], והשאלה שם היא, שמצד הטעם ד„יתגלו שלימות כחותיו כו׳״ מספיק הפועל כמו שהוא כלול בהכח (העי״ס שנאצלו באוא״ס לפני הצמצום) ואין צריך להפועל כמו שהוא מחוץ להכח (ושאלה זו היא גם להביאור דלקמן ס״ו): משא״כ השאלה שבפנים השיחה (שמכיון שהכח הוא בלתי מוגבל, אין מתוסף בו שלימות) היא — גם על כללות ענין ה„פועל״ (גם כמו שכלול בה„כח״)."],["29","29","שער הגלגולים הקדמה וא״ו ואילך. ובכ״מ. וראה שמו״ר פ״מ, ג."],["30","30","ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מח, ב</a>), שירידת הנשמה למטה היא בכדי לתקן את הגוף ונה״ב וחלקו בעולם [וזה בא בהמשך להמבואר שם פל״ו שתכלית הבריאה הוא שיהי׳ לו ית׳ דירה בתחתונים]. ובכ״מ מבואר (ראה קונטרס ומעין מ״ו פ״א. וירח ש״ת (ע׳ ח׳). ד״ה ומעין תש״י ספ״ג. וראה גם דרמ״צ קם, ב. קנד, א) שירידת הנשמה למטה היא (גם*) לצורך הנשמה, ירידה צורך עלי׳, ושהעלי׳ שלה היא מצד זה שגם בהיותה מלובשת בגוף ונה״ב שמעלים ומסתיר כו׳ מ״מ היא עומדת בנסיון ועוסקת בתומ״צ כו׳. ויש לומר, שב׳ ענינים אלו הם דוגמת ב׳ הטעמים דסיבת הבריאה: „יתגלו שלימות כחותיו כו׳״, ו„דירה בתחתונים״."],["31","31","ראה המשך תרס״ו ס״ע שם ואילך. *) בד״ה וירח שם, שה„תכלית״ דירידת הנשמה למטה היא עליית הנשמה, וה„כוונה״ בירידת הנשמה למטה היא לזכך ולברר את הגוף ונה״ב."]]],[1300201298,"אירע כחות בגילוי וכמ״ש³² לבלתי ידח ממנו נדח — איז צוליב וואס דארף ער אים שיקן למקום רחוק, מאיגרא רמה לבירא עמיקתא³³, ובפרט נאך אז דאס (ירידת הנשמה בגוף) איז אן ענין של הכרח פאר דער נשמה (כמרז״ל³⁴ על כרחך אתה חי), היפך ענין התענוג והרצון וכו׳ ?\nו. זעט מען דערפון, אז אפילו ווען אויך פריער איז ניטא קיין ספק און ספק ספיקא אז די כחות פון דעם בן מלך קענען און וועלן ארויסקומען בפועל — איז ניט מספיק דער „בכח״, און מען דארף האבן אז דער בכח זאל קומען לידי פועל.\nועד״ז אפילו בנוגע לכחותיו ית׳ (וואס אין זיי איז דאך אודאי ניט שייך קיין שום ספק ח״ו אז זיי קענען קומען בפועל), אז דער רצון העליון איז אז זיי זאלן קומען בפועל, כנ״ל סעיף ד׳.\nוואס דערפון איז מובן אויך בענינינו: אע״פ אז אויך במוצאי שבת בראשית איז מען זיכער אז די החלטה פון א אידן (צו טאן אין דער עבודה פון „ויעקב הלך לדרכו״) וועט קומען בפועל — און נאך מער: אז ער וועט אפטאן די עבודה הנ״ל בתכלית השלימות, בשמחה ובטוב לבב — פונדעסטוועגן, קומט עס ניט צו דער שלימות שבמוצאי שבת פרשת נח, ווען די עבודה פון „ויעקב הלך לדרכו״ איז שוין דא (במשך פון א גאנצע וואך, שבעת ימי ההיקף) בפועל³⁵.\nז. כאמור לעיל (סוף סעיף א׳) איז דער ענין פון „ויעקב הלך לדרכו״ האט א שייכות מיוחדת מיט די ענינים פון פרשת נח. ובהקדים:\nשוין גערעדט כמה פעמים³⁶ בנוגע צו די שמות הסדרות, אז (אע״פ וואס בפשטות איז דער נאמען פון יעדער סדרה על שם ההתחלה) וויבאלד זיי זיינען נעמען ע״פ תורה [ובפרט ע״פ תורת הבעש״ט³⁷ אז שמו אשר יקראו לו בלה״ק איז מהוה מחי׳ ומקיים דעם דבר הנקרא בהשם], איז דער נאמען פון יעדער סדרה בריינגט ארויס דעם תוכן פון דער גאנצער סדרה.\nא ראי׳ מוכחת אויף דעם איז³⁸ פון דעם נאמען פון אונזער סדרה — נח: אויב די שמות הסדרות וואלטן געווען נאר מצד התחלתם — וואלט מען געדארפט רופן די סדרה (ניט מיטן נאמען „נח״, נאר) „תולדות״ (ווארום דער ווארט „תולדות״ איז נעענטער צו תחלת הסדרה ווי דער ווארט „נח״), און פ׳ „תולדות״ שלאחרי׳ — אויף מבדיל זיין איר פון אונזער פרשה — „יצחק״.\nדערפון וואס די סדרה הייסט מיטן נאמען נח איז מוכח, אז דאס איז מצד דערויף וואס דער ווארט „נח״ בריינגט ארויס דעם תוכן פון דער סדרה.\nח. ולכאורה איז ניט מובן: „נח״ איז (ע״ש זה ינחמנו) פון לשון מנוחה³⁹ און „נייחא״⁴⁰; היינט ווי קען מען זאגן אז דער נאמען „נח״ בריינגט ארויס דעם תוכן פון דער סדרה, בשעת אז כמה",[["32","32","ש״ב יד, יד."],["33","33","לשון הגמרא — חגיגה ה, ב."],["34","34","אבות ספ״ד."],["35","35","להעיר מרמב״ן וירא כב, א (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו״ת ראה יט, רע״ג</a>), שטעם הנסיון (הגם שהכל גלוי לפניו ית׳ ויודע בראש מה שיהי׳ בסוף) הוא כדי להיות לאדם שכר מעשה טוב ולא שכר לב טוב לבלבד."],["36","36","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151058\" data-slug=\"likkutei-sichot\" data-id=\"1300151058\">לקו״ש חי״ה ע׳ 58</a>. 355. ועוד."],["37","37","שעהיוהי״א פ״א."],["38","38","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151368\" data-slug=\"likkutei-sichot\" data-id=\"1300151368\">לקו״ש שם ע׳ 355</a>."],["39","39","רש״י בראשית ה, כט."],["40","40","ראה ב״ר פ״ל, ה (ובמ״כ שם). תו״א ריש פרשתנו."]]],[1300201299,"ורוב הענינים שבפרשתנו — והתחלתה וסופה, מבול און הפלגה⁴¹ — זיינען היפך ענין המנוחה און נייחא ?\nאיז דער ביאור אין דעם: די כוונה פנימית פון מבול און הפלגה איז אז דורך זיי זאל זיין און ווערן „נייחא דרוחא״. אע״פ וואס זיי זיינען ענינים בלתי רצויים — איז אבער דורך דעם וואס א איד איז זיך מתגבר אויף די העלמות והסתרים, קומט אים צו א תוספת בעבודתו, דורך דעם וואס ער איז מברר און נעמט ארויס די ניצוצות הקדושה וועלכע געפינען זיך אין די העלמות והסתרים פון מבול און הפלגה\n[וע״ד מאמר רז״ל⁴² „עשרה דורות מנח ועד אברהם כו׳ עד שבא אברהם אבינו וקבל שכר כולם״, אז אברהם אבינו [וואס „אחד הי׳ אברהם״⁴³] האט מקבל געווען דעם שכר פון די אלע עשרה דורות, כולל אויך דעם דור הפלגה]\nוואס דאס איז אויך דער טעם פון דעם וואס די מי המבול וערן אנגערופן מיטן נאמען „מי נח״⁴⁴, ווייל דער מבול איז געקומען „לטהר את הארץ״, וואס דורך דעם איז געווארן „נייחא דרוחא״⁴⁵ [וואס נביאים (און הפטורה) — איז דאך גלה סודו אל עבדיו הנביאים⁴⁶ — בריינגען ארויס בגלוי די כוונה פון דער זאך, איז אין נביא (הפטורה) וערן זיי אנגערופן (ניט „מי המבול״, נאר) „מי\nנח״ על שם התכלית, צו שאפן „נייחא דרוחא״],\nביז ווי מען זעט בפשטות, אז דורך דעם וואס נח איז „צדיק תמים הי׳ בדורותיו״ איז ניט נאר דער מבול וואס האט אים ניט אנגערירט לרעה ח״ו, נאר אדרבה — „ראה עולם חדש״⁴⁷, ס׳איז בא עם צוגעקומען א חידוש בעולם,\nביז אז (דורך עבודתו של נח לאחרי המבול, איז) „וירח הוי׳ את ריח הניחח״⁴⁸ („ניחח״ איז נח״ר לפני, „נייחא דרוחא״), וואס דאס האט געבראכט א תוקף (עילוי⁴⁹) אין עולם, אז ס׳איז ניט שייך קיין הפסק וביטול אין סדרי העולם⁵⁰,\nביז אז דער אויבערשטער האט כורת ברית געווען אויף דעם⁵¹, און האט געמאכט אן אות ברית אויף דעם (קשת) „לדורות עולם״⁵²,\nביז (עקבתא דמשיחא) די צייט ווען דער קשת וועט זיין „בגווני נהירין״, וואס „כדין צפי לי׳ למשיח״⁵³.\nט. און דאס איז אויך די שייכות פון פרשת נח מיטן ענין פון „ויעקב הלך לדרכו״:\nבשעת א איד גייט פון חודש תשרי און גייט אריין אין די עובדין דחול במשך דעם גאנצן וואכעדיקן יאר, קען ער דאך זיך דערשרעקן פאר די „מים רבים״ פון",[["41","41","ודורות שביניהם ג״כ „מכעיסין ובאין״ (אבות פ״ה מ״ב)."],["42","42","אבות שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151070\" data-slug=\"likkutei-sichot\" data-id=\"1300151070\">לקו״ש חט״ו ע׳ 70</a> ואילך."],["43","43","יחזקאל לג, כד. — (וכהמשך הכתוב) ויירש את הארץ."],["44","44","ישעי׳ נד, ט."],["45","45","תו״א ריש פרשתנו (ח, סע״ג ואילך)."],["46","46","עמוס ג, ז."],["47","47","ב״ר פ״ל, ח."],["48","48","פרשתנו ח, כא."],["49","49","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151051\" data-slug=\"likkutei-sichot\" data-id=\"1300151051\">לקו״ש חט״ו ע׳ 51</a> ואילך, שהתוקף שנעשה בעולם לאחרי המבול („לא ישבותו״) הוא מצד הטהרה והזיכוך שנעשה בו ע״י המבול."],["50","50","פרשתנו שם, כא־כב."],["51","51","שם ט, ח ואילך."],["52","52","שם, יב."],["53","53","זח״א עב, ב."]]],[1300201300,"וועלט, די „טרדות הפרנסה והמחשבות שבעניני עוה״ז״⁵⁴ — אויף דעם איז די הוראה פון פרשת נח, אז די „מים רבים״ וערן גאר אנגערופן „מי נח״, ווייל דורך זיי ווערט דער „נייחא דרוחא״.\nאון די וועג דערצו איז „בא אל התיבה גו׳״, כפירוש הבעש״ט⁵⁵ — אריינגיין אין די ווערטער (תיבה) פון תפלה און תורה: בשעת א איד שטעלט זיך אוועק מיט א תוקף אויף (ניט נתפעל ווערן פון די „מים רבים״, און) „להכניס את עצמו בהתיבות דתפלה ותורה ולהדבק בהם״⁵⁵ — איז ניט נאר וואס ער ווערט געראטעוועט פון די מי המבול, נאר נאך מער: די „מים רבים״ גופא ווערן „מי נח״, דורך זיי קומט צו אן עילוי⁵⁶ אין די תיבות התפלה והתורה,\nביז אז דער „נייחא דרוחא״ איז ניט בלויז אין די תיבות התפלה והתורה (וואס קומט דורך די מים רבים), נאר אויך אין זיינע עניני הרשות,\nווי עס שטייט אין מדרש⁵⁷ (בנוגע צו דעם וואס עס שטייט „נח נח״ צווי מאל) „נייחא לעליונים נייחא לתחתונים״, אז דער „נייחא״ איז ניט בלויז אין עניני התורה ומצוות („עליונים״) נאר אויך אין זיינע עניני רשות („תחתונים״),\nביז אז ער דערזעהט אן „עולם חדש״, אז ער טוט אויף א חידוש אין דער בריאה, בדוגמת „השמים החדשים וה־\nארץ החדשה״⁵⁸ וואס וועלן זיין לעתיד לבוא.\nיוד. מאמר ד״ה מים רבים.\nיא. ווי גערעדט כמה פעמים, אז בשעת ס׳איז דא א (געוויסע) התעוררות — דארף מען איר פארבינדן מיט אן ענין פרטי⁵⁹. וואס דורך דעם וואס זי האט א „אחיזה״ אין אן ענין פרטי, איז בנקל (ובודאות) יותר אז זי זאל אראפ־קומען אין א מעשה בפועל.\nובנוגע לעניננו: בכדי צו מאכן לייכטער אז די התעוררות הנ״ל אין דעם ענין פון „ויעקב הלך לדרכו״ זאל קומען אין א מעשה בפועל (ובאופן של זריזות) — איז כדאי צו פארבינדן איר מיט א הוראה פרטית וועלכע איז שייך צו דעם יאר ביחוד [וואס „את הכל עשה יפה בעתו״⁶⁰],\nובפרט נאך, אז כשם ווי כללות הענין פון „ויעקב הלך לדרכו״ האט א שייכות מיוחדת מיט פרשת נח (כנ״ל סעיף ט׳), אזוי אויך די הוראה פרטית דשנה זו ביחוד — האט אויך א שייכות מיוחדת מיט (אן ענין אין) פרשת נח (כדלקמן סעיף טו).\nיב. פון די ענינים המיוחדים שבשנה זו איז — אז דער יאר איז א עיבור־יאר, וואס דער ענין פון א עיבור־יאר איז צו אויסגלייכן שנת הלבנה מיט שנת החמה. און נאך מער: היינטיקער יאר איז א ספעציעלער עיבור־יאר — דער לעצ־טער יאר פון א מחזור קטן, וואס דאן איז די אויסגלייכונג (פון שנת הלבנה מיט שנת החמה) בתכלית השלימות, ווי",[["54","54","תו״א ריש פרשתנו."],["55","55","הובא בד״ה צהר תעשה תרצ״ה בתחילתו. וראה גם הוספות לכתר שם טוב (קה״ת) ס״י."],["56","56","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו״א ט, סע״א</a>: „וזהו ותלך התבה על פני המים דוקא ותרם התבה כו׳ שע״י המים דוקא מתעלות תיבת התפלה ועולה למעלה מעלה״."],["57","57","ב״ר פ״ל, ה."],["58","58","ישעי׳ סו, כב. וראה לעיל ע׳ 265 הערה 29."],["59","59","להעיר גם מקונטרס העבודה פ״ו."],["60","60","קהלת ג, יא."]]],[1300201301,"דערקלערט בארוכה (בצירוף המראי מקומות) אין דעם מכתב כללי⁶¹.\nדי הוראה דערפון אין עבודת האדם, איז (ווי דערקלערט אין מכתב הנ״ל):\nבא יעדער אידן דארפן זיין די צווי אופני עבודה, שבדוגמת השמש ודהירח: פאראן ענינים און צייטן, וואס ער דארף זיין א משפיע — בדוגמת השמש וואס איז משפיע בכח עצמו; און פאראן ענינים און צייטן, וואס פריער דארף ער זיין א מקבל און ערשט לאחרי זה דארף ער משפיע זיין דאס וואס ער האט מקבל געווען — בדוגמת הלבנה וואס (זי האט ניט קיין אייגענע ליכטיקייט, נאר) נאך דעם ווי זי איז מקבל און באקומט די ליכטיקייט פון שמש איז זי משפיע און לייכט (דעם אור וואס זי איז מקבל) לארץ ולדרים עלי׳.\n[וואס די צווי אופני עבודה, ווי זיי זיינען בכללות — איז עס אויך די עבודה פון לימוד התורה וקיום המצוות, און די עבודה פון „כל מעשיך לשם שמים״⁶² און „בכל⁶³ דרכיך דעהו״⁶⁴: לימוד התורה וקיום המצוות — „שמש״, ווארום תורה און מצוות זיינען ליכטיק מצד עצמם כמ״ש⁶⁵ כי נר מצוה ותורה אור: משא״כ די עניני רשות („מעשיך״ און „דרכיך״) — וויבאלד אז מצד עצמם זיינען זיי ניט ליכטיק, און א איד טראגט אריין אין זיי אור (דורך דעם וואס ער טוט זיי „לשם שמים״ און אין אן אופן\nפון „דעהו״) — זיינען זיי בדוגמת לבנה⁶⁵*].\nאון אע״פ אז יעדער איינער פון די צווי אופני עבודה (אויך ווי ער איז פארזיך) איז אן ענין נעלה ביותר, ביז אן ענין בשלימותו — בדוגמת שנת החמה און שנת הלבנה, וואס יעדע פון זיי (שנת החמה אליין, און שנת הלבנה אליין) ווערט גערעכנט (בכו״כ ענייני תורת אמת) אלס א שנה שלימה⁶⁶ —\nאיז אבער דא די ספעציעלע הוראה פון שנת העיבור, ובפרט פון שנת העיבור שבסיום מחזור קטן, אז מען דארף פארבינדן ביידע עבודות צוזאמען.\nוואס דאס (די פארבינדונג) בריינגט אריין א העכערע שלימות אין יעדער איינער פון זיי — סיי אין דער עבודה פון „שמש״, סיי אין דער עבודה פון „לבנה״,\nובצירוף שניהם יחד⁶⁷, ווערט די אמת׳ע שלימות. ווי די משנה זאגט⁶⁸ „(שנה) תמימה — להביא את חודש העיבור״, אז דורכן חודש העיבור וואס איז מחבר (און מאחד) שנת הלבנה מיט שנת החמה — ווערט די אמת׳ע „שנה תמימה״, תכלית התמימות והשלימות.",[["61","61","דוא״ו תשרי. וראה גם שיחת ר׳ תשרי ש.ז."],["62","62","אבות פ״ב מי״ב."],["63","63","משלי ג, ו."],["64","64","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380969\" data-slug=\"likkutei-torah\" data-id=\"4001380969\">לקו״ת ר״ה (סב, ג</a>) ואוה״ת ואתחנן (ס״ע קב ואילך) שבחינת הנשמה שלמעלה היא בחי׳ שמש, ובחינת הנשמה המלובשת בגוף היא בחי׳ לבנה."],["65","65","משלי ו, כג. *) נדפס בלקו״ש חי״ד ע׳ 477 ואילך. 65*) עוד אופן בשני עבודות אלו: שמש — עבודת הצדיקים, ולבנה — עבודת הבעלי תשובה (אוה״ת ואתחנן ע׳ קי). וענין החיבור ד(שנת ה)חמה ו(שנת ה)לבנה [ההוראה דשנת העיבור, כדלקמן בפנים] — הוא דוגמת ענין (ראה זח״ג קנג, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381142\" data-slug=\"likkutei-torah\" data-id=\"4001381142\">לקו״ת שמע״צ צב, ב</a>. שה״ש ג, סע״ב) „לאתבא צדיקייא בתיובתא״."],["66","66","ראה ערכין לא, ב. וש״נ. אוה״ת לתהלים עה״פ תורת ה׳ תמימה."],["67","67","שעי״ז מיתוסף אור העולה על כולנה (ראה שעהיוהי״א פ״ב. ובכ״מ)."],["68","68","ערכין לא, א."]]],[1300201302,"יג. די שייכות פון דער הוראה (הנ״ל) המיוחדת לשנה זו (אלס שנת העיבור, און סיום מחזור קטן) אלס פרט פון דער הוראה כללית פון „ויעקב הלך לדרכו״ (שבכל שנה ושנה):\nווי גערעדט פריער, איז בחודש תשרי א איד פארנומען (בעיקר) מיט ענינים רוחניים פון תורה ומצוות, וואס זיינען בדוגמת השמש. און דערנאך (נאך שמחת תורה, ובפרט במוצאי שבת בראשית, ועאכו״כ לאחרי סיום חודש תשרי⁶⁹) הויבט זיך אן דער „ויעקב הלך לדרכו״ אין עניני הרשות ועובדין דחול, וואס זיינען בדוגמת לבנה⁶⁹*.\nאון ווי גערעדט פריער⁷⁰, אז אע״פ אז דער „ויעקב הלך לדרכו״ איז — בחיצוניות — א ירידה, איז אבער דא אין דעם א מעלה אויף דער עבודה דחודש תשרי, וואס דורך דעם דוקא פירט זיך אויס די כוונה פון „דירה בתחתונים״.\nאיז אין דעם קומט צו די הוראה פרטית (הנ״ל) פון שנת העיבור און סיום מחזור קטן: אע״פ אז יעדע איינע פון די צווי עבודות — סיי די עבודה פון התעסקות אין עניני קדושה (שמש) שבחודש תשרי (ודוגמתה בכל השנה), סיי די עבודה פון בירור עניני הרשות (לבנה) שבמשך כל השנה — איז אן עבודה שלימה ונעלית,\nפונדעסטוועגן, פאדערט זיך פון א אידן, אז בא אים זאלן זיין פארבונדן ביידע עבודות צוזאמען: אויך גייענדיק „לדרכו״ בעניני הרשות — זאל ער זיך ניט באגנוגענען דערמיט וואס ער טוט עס אין אן אופן פון „כל מעשיך לשם שמים״ ביז צו „בכל דרכיך דעהו״ (אע״פ אז דאס איז אן ענין נעלה ביותר, ביז אז אין דעם איז דא א מעלה (כנ״ל) אפילו אויף דער עבודה פון חודש תשרי), נאר ער זאל זיין (בעת מעשה) דורכגענומען אויך⁷⁰* מיטן ענין פון חודש תשרי, ווען ער איז געווען אינגאנצן פארנומען מיט עניני קדושה.\nיד. די הוראה הנ״ל המיוחדת לשנה זו — אז דער „ויעקב הלך לדרכו״ דארף זיין אין אזא אופן אז די ענינים רוחניים מיט די ענינים גשמיים (באופן ד„לשם שמים״ און „דעהו״) זאלן זיין פארבונדן צוזאמען — איז אויך אנגעוויזן אין דעם, וואס דער ראש־השנה פון דעם יאר [און אויך דער טאג פון י״ט כסלו, וואס ער איז דער ראש־השנה לחסידות⁷¹] איז ביום השלישי — יום שהוכפל בו כי טוב⁷², טוב לשמים וטוב לבריות⁷³.\nאון ווי גערעדט פריער⁷⁴, אז דער אויפטו פון „יום שהוכפל בו כי טוב״ איז [ניט בלויז אז אין אים זיינען דא סיי דער „טוב לשמים״ סיי דער „טוב לבריות״, נאר אויך] אז די ביידע טוב׳ס (וואס אין",[["69","69","ראה לעיל הערה 15*. 69*) להעיר גם מהמבואר בהמאמר (סעיף ד׳), שע״י הירידה ב„מים רבים״ מגיעים לענין התשובה. וגם מצד זה שייך ענין „ויעקב הלך לדרכו״ ללבנה — כי ההליכה „לדרכו״ בעובדין דחול במשך השנה הו״ע הירידה במים רבים (כנ״ל סעיף ט׳), ולבנה הו״ע עבודת הבע״ת (כנ״ל הערה 65*)."],["70","70","לעיל ע׳ 269־70. 70*) מהדוגמאות לדבר: י״ל „שלשה שאכלו על שלחן אחד ואמרו עליו ד״ת כאילו אכלו משלחנו של מקום״ (אבות פ״ג, מ״ג)."],["71","71","אגה״ק של כ״ק אדמו״ר (מוהרש״ב) נ״ע לחג הגאולה די״ט כסלו תרס״ב — נדפסה בהיום יום בתחלתו. ובכ״מ."],["72","72","רש״י בראשית א, ז."],["73","73","קדושין מ, א. ובאוה״ת (בראשית לג, ב. משפטים ע׳ א׳קנז. ועוד) מקשר זה עם יום השלישי שהוכפל בו כי טוב."],["74","74","בהתוועדות דליל ערב ר״ה, ויום ב׳ דר״ה."]]],[1300201303,"אים) זיינען פארבונדן און פארייניקט צוזאמען.\nביז אז יעדער רגע און יעדער פעולה שביום זה — איז א רגע און א פעולה פון א טאג וואס ער איז טוב לשמים ולבריות גם יחד.\nאון וויבאלד אז ראש השנה איז דער קאפ פון דעם יאר, וואס ער (איז כולל, און) פירט אן מיט׳ן גאנצן יאר⁷⁵ — איז דאך פארשטאנדיק, אז כל יום און כל ענין שבשנה זו, דארף זיין דורכ־גענומען פון ביידע ענינים: פון „טוב לשמים״ (שבדוגמת ענין שנת החמה), און פון „טוב לבריות״ (שבדוגמת ענין שנת הלבנה),\nאון אין אן אופן אז פון ביידע צוזאמען ווערט איין זאך (יאר) — „שנה תמימה״.\nטו. ענין הנ״ל איז מרומז אויך אין פירוש רש״י בפרשתנו:\nאין פסוק „ובחודש השני בשבעה ועשרים יום לחודש יבשה הארץ״⁷⁶, זאגט רש״י, אז דאס וואס דער מבול האט אויפגעהערט („יבשה הארץ״) „בשבעה ועשרים״ — און ער האט זיך אנגעפאנגען „בחודש השני בשבעה עשר יום לחודש״⁷⁷ — זיינען עס די „י״א ימים שהחמה יתירה על הלבנה, שמשפט דור המבול שנה תמימה הי׳״.\nולכאורה: דער מבול וואס האט אויפגעהערט „בשבעה ועשרים״ באווייזט אז דער משפט פון דור המבול איז געווען א יאר פון שנת החמה — האט דאך רש״י געדארפט זאגן „שמשפט דור המבול שנת החמה הי׳״, פארוואס זאגט ער דעם לשון „שנה תמימה״?⁷⁷*\nנאר דערמיט איז ער מרמז, אז די ירידה אין „מים רבים״ פון וועלט וואס הויבט זיך אן בעיקר „בחודש השני״ („זה מרחשון״⁷⁸)\n— ווי גערעדט פריער⁷⁹, אז דער „ויעקב הלך לדרכו״ וואס א איד גייט פון חודש תשרי [שגם הוא נרמז בפרשתנו וכמבואר בזהר⁸⁰ אויפן פסוק „ותנח התיבה בחודש השביעי גו׳״⁸¹, אז „בחודש השביעי״ גייט אויף חודש תשרי, וואס דאן איז „בשבעה עשר״, ווי דער צ״צ איז מבאר בזה⁸² אז דאס גייט אויף עשרת ימי תשובה און שבעת ימי הסוכות] איז בדוגמת די „מים רבים״ פון מבול —\nאיז דער תכלית פון דער ירידה (מבול) איז אז עס זאל ווערן א „שנה תמימה״ — דער חיבור פון שנת הלבנה⁸³ („טוב לבריות״) מיט שנת החמה („טוב לשמים״).\nאון דאס איז רש״י מרמז „שנה תמימה״, און ניט „שנת החמה״: דער ענין הירידה אין די „מים רבים״ פון מי המבול — „טרדות הפרנסה והמחשבות",[["75","75","עטרת ראש בתחלתו."],["76","76","פרשתנו ח, יד."],["77","77","שם ז, יא. 77*) ע״ד הפשט י״ל (בדוחק) — דאם הי׳ אומר „שנת החמה״ עדיין חסר ביאור למה לא שנת הלבנה, לכן אומר „שנה תמימה״ (יותר משנת הלבנה)."],["78","78","דעת ר״א (ר״ה יא, סע״ב) — הובא בפירש״י עה״ת שם. וראה אוה״ת נח (סט, א) שקו״ט בב׳ הדעות בדעת ר״א."],["79","79","סעיף ט׳."],["80","80","ח״ג קמט, ב. רנה, ב."],["81","81","פרשתנו ח, ד."],["82","82","אוה״ת נח ע, א."],["83","83","להעיר מתורת הה״מ [וביאורה באוה״ת (ואתחנן ע׳ קט ואילך. ר״ה ע׳ א׳ת ואילך)] ד״ה ועינינו מאירות כשמש וכירח (אור״ת פד, ד)."]]],[1300201304,"שבעניני עוה״ז״⁵⁴ — איז ניט דער ענין פון „שנת החמה״, אדרבה: דאס איז דער ענין פון „שנת הלבנה״. נאר אין דערויף ווערט צוגעגעבן דער ענין פון „שנת החמה״ [די „י״א ימים שהחמה יתירה על הלבנה״], אז די עבודה פון בירור עניני הרשות שבמשך כל השנה (שנת הלבנה) זאל זיין דורכגענומען מיט די רוחניות און קדושה פון חודש תשרי (שנת החמה), וואס דורך דעם ווערט די תמימות און שלימות פון (שנת הלבנה, און זי ווערט א) — „שנה תמימה״.\nטז. בכדי צו מקשר זיין נאכמער⁸⁴ די התעוררות פון „ויעקב הלך לדרכו״, וואס איז פארבונדן מיט „בא אל התיבה״ וואס גייט אויף תיבות התפלה והתורה⁸⁵, מיט אן ענין פרטי — איז א דבר טוב ונכון, אז יעדערער זאל זיך משתדל זיין, אז עס זאל צוקומען (בעירו (און אויב מעגליך אויך בסביבתו) לכל הפחות) איין מוסד וואס איז פארבונדן מיט תפלה און איין מוסד וואס איז פאר־בונדן מיט תורה.\nזעלבסטפארשטענדליך, אז יעדערער דארף זיך משתדל זיין צו מחזק זיין און מבסס זיין די מוסדות התורה והתפלה וועלכע זיינען שוין דא בעירו, אז זיי זאלן זיין וואס גרעסער וכו׳, יגדיל ויאדיר⁸⁶.\nאבער אזוי ווי עס גייט א נייער יאר — דארף מען זעהן אז עס זאל צוקומען (בעירו און בסביבתו) א מוסד חדש פון תפלה און א מוסד חדש פון תורה.\nאון דאס דארף געטאן ווערן אין אן אופן פון „בא אל התיבה״ — „אריינגיין״ אין דעם בכל מציאותו, ובלשון הבעש״ט⁸⁷: „להכניס את עצמו . . ולהדבק״, ביז אז ניט נאר ער אליין זאל זיין פארקאכט אין דעם, נאר בלשון הכתוב⁸⁸: „אתה ובניך ואשתך ונשי בניך אתך״ — אריינגענומען אין דערויף אלע זיינע נאענטע וכו׳ — בכל מקום שידו מגעת.\nאון וויבאלד אז „מצוה גוררת מצוה״⁸⁹ — איז מובן, אז די השתדלות בהקמת מוסדות חדשים, וועט בריינגען אויך א הצלחה נוספת אין אלע ענינים פון תורה ומצוות — ובפרט אין די מבצעים כלליים, אנהויבנדיק פון מבצע אהבת ישראל,\nאון דורך דעם — הצלחה אויך אין די ענינים הגשמיים [ווארום די ענינים הגשמיים וערן דאך נשתלשל פון די ענינים הרוחניים], און עס וועט זיין „נייחא לעליונים (ענינים הרוחניים) נייחא לתחתונים⁵⁷ (ענינים הגשמיים)״,\nאון אין אן אופן אז ביידע זאכן וועלן גיין צוזאמען — בהתאם צו א יאר וואס זיין „ראש״ איז „טוב לשמים וטוב לבר־יות״, ביז באופן אז ביידע ענינים זיינען פארבונדן און פארייניגט.\nיז. נאך אן ענין וואס איז פארבונדן מיט דער עבודה פון „בא אל התיבה״ — תיבת נח:\nאין תיבת נח זיינען געווען אלע חיות און אלע בהמות צוזאמען, און אעפ״כ „לא עשו רעה זל״ז ולא השחיתו זל״ז״ — בדוגמת ומעין פון „וגר זאב עם כבש וגו׳״⁹⁰ און „לא ירעו ולא ישחיתו״⁹¹",[["84","84","מהנ״ל סעיף יא."],["85","85","כנ״ל סעיף ט׳."],["86","86","ע״פ לשון הכתוב — ישעי׳ מב, כא."],["87","87","הובא לעיל שם."],["88","88","פרשתנו ו, יח."],["89","89","אבות פ״ד מ״ב."],["90","90","ישעי׳ יא, ו."],["91","91","שם, ט."]]],[1300201305,"וואס וועט זיין לע״ל⁹².\nוואס דערפאר שטייט⁹³ אז תיבת נח איז די מ״ם סתומה פון „למרבה המשרה״⁹⁴ וואס וועט זיין לע״ל, וואס דאן וועט זיין „ולשלום אין קץ״⁹⁴.\nדי הוראה דערפון אין עבודת האדם:\nבשעת א איד איז מחליט מיט א תוקף אויף ניט נתפעל ווערן פון די „מי המבול״ פון וועלט (וואס קענען שטערן צו עבודת ה׳) און „אריינגיין״ אין „תיבת נח״ — „בא אל התיבה״, ובלשון הבעש״ט⁸⁷: „להכניס את עצמו בהתיבות דתפלה ותורה ולהדבק בהם״ — האט ער דאן עזר וסיוע של הקב״ה „גם אויביו ישלים אתו״⁹⁵, אז ניט בלויז וואס די „מי המבול״ פון וועלט וועלן אים ניט שטערן פון עבודת ה׳ — „לא ירעו ולא ישחיתו״, נאר נאך מער: זיי וועלן צוגעבן שלימות בעבודתו — „ישלים״ מלשון שלימות,\nוע״ד הידוע⁹⁶ בענין הנסיונות, אז ווען א איד שטעלט זיך אוועק מיט א תוקף אויף ניט נתפעל ווערן פון די נסיונות — דאן ווערט נתגלה ווי די כוונה פנימית פון די נסיונות גופא איז (נסיון מל׳ ארים נסי⁹⁷) אז דורך זיי זאל צוקומען א תוספת און אן עילוי בעבודתו,\nוואס אזוי איז אויך בענינינו: דורך דער החלטה בתוקף אויף ניט נתפעל ווערן פון די „מים רבים״, ווערט נתגלה תכלית הכוונה שבהם (וואס דאס איז זייער אמת׳ע מציאות) אז זיי זיינען „מי נח״, זיי בריינגען „נייחא דרוחא״⁹⁸,\nביז — צווי מאל (נח, מלשון) נייחא, כלשון המדרש⁵⁷ „נייחא לעליונים נייחא לתחתונים״\nסיי „לעליונים״ און „לתחתונים״ ווי זיי זיינען אין עבודת ה׳, כאמור לעיל⁹⁹ אז „עליונים״ מיינט די עבודה פון תומ״צ, און „תחתונים״ מיינט די עבודה פון „כל מעשיך לשם שמים״ און „בכל דרכיך דעהו״:\nסיי „לעליונים״ און „לתחתונים״ בכ־ללות יותר, כאמור לעיל¹⁰⁰, אז „על־יונים״ מיינט עבודת ה׳ (בכלל, כולל די עבודה אין עניני הרשות), און „תחתונים״ מיינט די ענינים הגשמיים כפשוטם — בני חיי ומזוני (ובכולהו) רויחי.\nחי. די ענינים וואס זיינען דא בנפש זיינען דאך אויך פאראן אין עולם (מקום) — איז דער ענין פון „נייחא בעליונים נייחא בתחתונים״ פאראן אויך אין עולם:\nארץ ישראל, וואס דער אויבערשטער האט איר אויסגעקליבן פון כל הארצות¹⁰¹ [ביז אז עיני ה׳ אלקיך בה שטענדיק, מרשית השנה ועד אחרית שנה¹⁰²] — איז „עליונים״ פון „עולם״¹⁰³, און שאר הארצות — „תחתונים״. און אויף דעם זאגט מען אז",[["92","92","וככה תרל״ז פצ״ה."],["93","93","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560407\" data-slug=\"or-hatorah-hb\" data-id=\"8316560407\">אוה״ת נח (כרך ג׳) תרע, א</a>."],["94","94","ישעי׳ ט, ו."],["95","95","משלי טז, ז."],["96","96","ד״ה וידעת תרנ״ז. ובכ״מ."],["97","97","ישעי׳ מט, כב. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370315\" data-slug=\"torah-or\" data-id=\"3901370315\">תו״א ע, סע״ד</a>. ד״ה כי מנסה ה׳תש״ח."],["98","98","כנ״ל ס״ח."],["99","99","סעיף ט׳."],["100","100","סעיף טז."],["101","101","תנחומא ראה ח."],["102","102","עקב יא, יב."],["103","103","כמרז״ל (זבחים נד, ב) א״י גבוה מכל הארצות — הובא בפרש״י עה״ת (דברים א, כה)."]]],[1300201306,"סיי „לעליונים״ סיי „לתחתונים״ איז „נייחא״:\n„נייחא לעליונים״: „ונתתי שלום בארץ גו׳ וחרב לא תעבור בארצכם״¹⁰⁴, כולל אויך אז אלע וועלן אנערקענען אז גאנץ ארץ ישראל לגבולותי׳ געהערט צו אידן\n[וכמדובר לעיל¹⁰⁵, אז בשעת אידן וועלן זאגן מיט א תוקף אז גאנץ ארץ ישראל איז א נחלת עולם וואס איז געגעבן געווארן פון אלקי עולם צום עם עולם, וועלן די אומות העולם אנער־קענען דעם אמת פון דעם, און דאס וועט פועל׳ן אז ניט נאר וואס זיי וועלן ניט מנגד זיין צו דעם („לא ירעו ולא ישחיתו״) נאר זיי וועלן נאך מסייע זיין אין דעם],\nאון „נייחא לתחתונים״, אז אויך אין חוץ לארץ, וואו נאר אידן געפינען זיך [וואס אפילו דארט וואו עס געפינט זיך בלויז איין איד (כמרז״ל¹⁰⁶ אפילו אחד מכם גולה לברברי׳ ואחד מכם גולה לסמטרי׳), איז אויף אים האלט זיך די גאנצע מדינה], וועלן זיי האבן מנוחה אמיתית, און טאן בכל עניני יהדות אן קיינע שטערונגען, און בשמחה וטוב לבב.\nיט. ס׳איז דאך המעשה הוא העיקר¹⁰⁷ — דער סיכום פון כל הנ״ל: יעדער איד — סיי אין א״י, סיי אין חו״ל — דארף זיך נעמען מיט א תוקף אויף ניט נתפעל ווערן פון קיינע מניעות ועיכובים און דורכפירן די שליחות פון\nאויבערשטן [און שלוחו של אדם כמותו¹⁰⁸] צו מאכן די וועלט פאר א דירה לו ית׳, ביז אז די וועלט ווערט איבערגעמאכט דורך עם, עס ווערט „השמים החדשים והארץ החדשה״⁵⁸,\nאון דורך דעם וואס אידן וועלן דאס טאן מיט א תוקף, ניט רעכענענדיק זיך דערמיט וואס עס ווייזט זיך אויס אז עס זיינען דא מניעות ועיכובים — וועט זיין (כנ״ל ס״י״ז) דער „גם אויביו ישלים אתו״, ע״ד ווי ס׳איז געווען בתיבת נח.\nאון דאס איז אויך א הכנה טובה און א כלי מתאימה [ביז צו א כלי באופן דאבער (ניט בלויז מקבל נאר אויך) ממשיך¹⁰⁹, און באופן פון „אחישנה״ אין דעם „אחישנה״ גופא¹¹⁰] צו „וגר זאב עם כבש״ וואס וועט זיין בביאת משיח צדקנו [וואס בתיבת נח איז עס געווען נאר „בתיבה״, און „לפי שעה״, משא״כ לע״ל וועט עס זיין אויך אין (גאנץ) עולם ובאופן נצחי¹¹¹],\nאון דערנאך — אויך קיום היעוד ד„השמים החדשים והארץ החדשה״¹¹²,\nאון אויך כסיום הכתוב¹¹² „כן יעמוד זרעכם ושמכם״, ווארום די „שמים החדשים״ און די „ארץ החדשה״ וערן אויפגעטאן דורך יעדער אידן, פון „ראשיכם שבטיכם״ ביז „חוטב עציך ושואב מימיך״.\nכ. אפטייטשן ענין הנ״ל (סעיף יט) אין פשוט׳ע אותיות —",[["104","104","בחוקותי כו, ו."],["105","105","בשיחת מוצאי שבת בראשית סעיף יב (לעיל ע׳ 273 ואילך)."],["106","106","שהש״ר פ״ב, ח."],["107","107","אבות פ״א מי״ז."],["108","108","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">ברכות לד, ב</a>. וש״נ. ובלקו״ת ויקרא (א, ג), שכ״ה גם בנוגע לשלוחו של אדם העליון."],["109","109","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370510\" data-slug=\"torah-or\" data-id=\"3901370510\">תו״א קיד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380807\" data-slug=\"likkutei-torah\" data-id=\"4001380807\">לקו״ת ראה כב, סע״ד</a>. ד״ה אדון עולם תש״ג פ״ה. ובכ״מ."],["110","110","מכיון ש„אחישנה״ תלוי ב„זכו״ (סנהדרין צח, א)."],["111","111","וככה תרל״ז ספצ״ו."],["112","112","ישעי׳ סו, כב."]]],[1300201307,"דורך דעם וואס אידן וועלן מחליט זיין ובתוקף צו דורכפירן דעם אוי־בערשטנס שליחות (ניט רעכענענדיק זיך מיט קיינע שטערונגען) — וועט מען, בקרוב ממש, און בעגלא דידן, פארענדיקן דעם גלות, און מקבל זיין פני משיח צדקנו, און אין אן אופן פון מנוחה ומתוך שמחה וטוב לבב.\nוואס דאס האט אויך א שייכות מיוחדת מיט מוצש״ק, ווארום במוצש״ק, פראוועט מען דאך סעודת מלוה מלכא, וואס זי איז פארבונדן מיט שמחה כמנהג ישראל¹¹³, און זי ווערט אנגערופן (און איז) „סעודתא דדוד מלכא משיחא״¹¹⁴ (זי איז פארבונדן מיט דוד׳ן אלס „מלכא משיחא״) — דעריבער איז עס אויך א הכנה און כלי צו אראפבריינגען „מלכא משיחא״ (אין אן אופן פון) מתוך שמחה וטוב לבב.\nכא. און דאס בריינגט ארויס נאכ־מער בגלוי דעם „נייחא לעליונים נייחא לתחתונים״ בכל הפירושים שבזה (וואס נאר א טייל פון זיי זיינען דערמאנט געווארן פריער),\nאון בריינגט אויך, אז דער „רוב טוב״ וואס איז נמשך געווארן בחודש השביעי [„המושבע והמשביע״¹¹⁵] זאל נמשך ווערן בגילוי אין די חדשים שלאחרי חודש תשרי, אנהויבנדיק פון חודש חשון,\nאז אנהויבנדיק פון „סעודתא דדוד מלכא משיחא״ וואס אין היינטיקן מוצאי שבת,\nדי גאולה פרטית¹¹⁶ (פון יעדער אידן), וואס זי איז אויך א הכנה צו דער גאולה הכללית ע״י משיח צדקנו, דוד מלכא משיחא,\nאז עס ווערט א שבוע טוב און א חודש טוב און א שנה טובה בכל הפרטים והענינים, ביז אין תכלית השלימות פון גאולה האמיתית והשלימה ע״י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו „בנערינו ובזקנינו גו׳ בבנינו ובבנותינו״¹¹⁷, „קהל גדול ישובו הנה״¹¹⁸.",[["113","113","ראה בס׳ האריז״ל במקומו „יש לשמוח בסעודה זו כמו בסעודת שבת״. שו״ע אדה״ז סי׳ ש ס״ב."],["114","114","סידור האריז״ל (להר״ש מרשקוב). פע״ח סוף שער השבת."],["115","115","היום יום ע׳ צ."],["116","116","אגה״ק ס״ד."],["117","117","בא יו״ד, ט."],["118","118","ירמי׳ לא, ח."]]],[1300201308,"בס״ד. מוצאי ש״פ לך לך - בחדרו - ה׳תשל״ח\nויאמר ה׳ אל אברם לך לך מארצך וממולדתך ומבית אביך אל הארץ אשר אראך,\nוידוע¹ שיש בזה ב׳ פירושים. פירוש הא׳ שההליכה (דלך לך) היא מלמעלמ״ט. וכמבואר בתו״א² שאברם הוא אב רם, שכל הנעלם מכל רעיון [שהוא למעלה גם מבחי׳ חכמה. כי חכמה (עם היותה ראשית כל הכחות פנימיים) היא בחי׳ גילוי. משא״כ אב רם הוא שכל הנעלם מכל רעיון. וכמבואר בהגהות וביאורי הצ״צ לתו״א שם³ פרטי הדרגות שבזה]. ואמר ה׳ אל אברם לך לך מארצך גו׳ שיצא אורו הנעלם לגילוי ויומשך מלמעלה למטה עד אל הארץ, בחי׳ מלכות. ומוסיף „אשר אראך”, ובזה ב׳ פירושים. א׳ (כפשוטו) שאראך קאי על הארץ, בחי׳ מלכות, שהמלכות היא בחי׳ עלמא דאתגליא לכן אומר עלי׳ אשר אראך⁴. ופירוש ב׳ שאראך קאי על אברם (בחי׳ שכל הנעלם מכל רעיון) — „אראה ואגלה אותך בעצמך”⁵ („במהותך ועצמותך”⁶). והיינו, דהגם שספירת המלכות עלמא דאתגליא (ובפרט כמו שנמשכת בבי״ע⁷) היא קצה הכי תחתון, ושכל הנעלם מכל רעיון (שהוא נעלם גם מרעיון העליון) הוא קצה הכי עליון, אעפ״כ, ע״י הירידה וההמשכה (דאברם, שכל הנעלם מכל רעיון) אל הארץ אשר אראך (כפירוש הא׳), לבחי׳ מלכות עלמא דאתגליא (קצה התחתון), עי״ז יתראה ויתגלה אמיתת ענינו (מהותו ועצמותו) של אברם (כפירוש הב׳), שנעשה עילוי (גם) בבחי׳ שכל הנעלם מכל רעיון (קצה הכי עליון), כמובן מהמבואר בתו״א שם⁸.\nב) ועד״ז הוא גם בענין ירידת הנשמה בגוף⁹, שהעלי׳ הנעשית בהנשמה ע״י ירידתה למטה [שנעשית בבחינת מהלך¹⁰, ענין „לך לך”¹¹], היא",[["1","1","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670494\" data-slug=\"torat-chaim\" data-id=\"2300670494\">תו״ח לך לך פט, ב</a>. אוה״ת שם (כרך ו׳) תתרעס, ב."],["2","2","ר״פ לך לך. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670031\" data-slug=\"torat-chaim\" data-id=\"2300670031\">תו״ח שם (פ, א</a>). אוה״ת שם תתרעב, א ואילך."],["3","3","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490031\" data-slug=\"or-hatorah-hb\" data-id=\"8316490031\">אוה״ת לך לך (כרך ד׳) תרפה, א</a>. וראה גם תו״ח שם."],["4","4","כ״מ ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו״ח שם</a> (תחילת סעיף ב׳). ושם פא, רע״א — באו״א קצת."],["5","5","תו״א יא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו״ח שם פא, רע״א</a>. אוה״ת שם (כרך ו׳) תתרעג, א."],["6","6","תו״ח שם. ובאוה״ת שם: בעצמך ומהותך."],["7","7","ראה לקמן סוס״ב."],["8","8","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו״א שם יא, ב</a> ואילך (וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו״ח שם פא, סע״א</a> ואילך. אוה״ת שם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490035\" data-slug=\"or-hatorah-hb\" data-id=\"8316490035\">תתרעג, ב</a>), שהירידה דבחי׳ אברם למטה היא ע״י (גילוי) בחינה שלמעלה מבחי׳ אברם. ובאוה״ת שם (כרך ד׳) תרפז, א בשוה״ג, שהיא ירידה צורך עלי׳."],["9","9","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490037\" data-slug=\"or-hatorah-hb\" data-id=\"8316490037\">אוה״ת שם תרפח, סע״א</a>, שענין לך לך „קאי על ירידת הנשמה בגוף”."],["10","10","ראה בהמצויין לעיל ע׳ 280 הערה 50. ובכ״מ."],["11","11","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490019\" data-slug=\"or-hatorah-hb\" data-id=\"8316490019\">אוה״ת שם</a> תרעט, א: „לך לך, שיהי׳ בבחי׳ מהלך ולא בבחי׳ עומד”. ושם ע״ב: שזהו „עיקר פי׳ לך לך”."]]],[1300201309,"גם בהדרגות הכי נעלות שבה, ואפילו בבחינת יחידה. דהגם דזה שנקראת יחידה הוא להיותה „מקבלת מיחיד”¹² [שלכן¹²* אין שייך שתהי׳ כנגדה בלעו״ז, בבואה דבבואה לית להו¹³], מ״מ, ע״י שהנשמה יורדת למטה, מאיגרא רמה לבירא עמיקתא¹⁴, נעשה עלי׳ גם בבחינת יחידה שבה. כמבואר בכמה דרושים¹⁵ שע״י עבודת הנשמה בירידתה למטה דוקא נעשה עלי׳ (ועלי׳ שלא בערך) גם בשרש ועצם הנשמה שלמעלה. וכמובן גם מהמבואר בכמה שיחות¹⁶ (בענין עלי׳ לתורה), שהעלי׳ היא בכל חמש הבחינות שבנשמה נפש רוח נשמה חי׳ יחידה, שהם ג׳ הבחינות תחתיים שניים ושלישיים¹⁷ דתיבת נח. וע״פ משנת״ל¹⁸ (ע״פ תורת הבעש״ט¹⁹ עה״פ²⁰ בא גו׳ אל התיבה) שענין תיבת נח הוא „הוראה בסדר עבודה”²¹ לכאו״א מישראל [ובפרט לאחרי חודש תשרי שאז מתחיל סדר העבודה ד„ויעקב הלך לדרכו”²². שהגם שהוא הולך לדרכו (גם) בעניני הרשות ובעובדין דחול, ועד לבחי׳ מים רבים שהם כל טרדות הפרנסה כו׳²³, מ״מ ע״י שמכניס את עצמו בהתיבות דתפלה ותורה הנה לא זו בלבד שהוא „ניצל מהשטף דמבול”²¹ אלא יתירה מזו שע״י המים נעשה ותרם התיבה²⁴ ועד שנעשה ותנח התיבה²⁵], מובן מזה, שעליית הנשמה שנעשה ע״י ירידתה למטה והתלבשותה במים רבים הוא בכל ג׳ הבחינות (דתיבת נח) תחתיים שניים ושלישיים, שענינם בנפש האדם הוא נר״נ חי׳ יחידה²⁶. בדוגמת המבואר לעיל (סעיף א׳)",[["12","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו״ת ראה כה, א</a>. 12*) ראה ד״ה צהר תעשה תש״ז פ״ל (ע׳ 187). וראה גם ד״ה ועשית ציץ עת״ר (ע׳ קס)."],["13","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">גיטין סו, א</a>. לקו״ת תצא לז, ג. ד״ה ועשית ציץ שם. צהר תעשה שם."],["14","14","לשון הגמרא — חגיגה ה, ב."],["15","15","ד״ה זה היום תש״ט ספ״ב ואילך. וראה הביאור בזה לקו״ש ח״ג ע׳ 846."],["16","16","לקו״ד כה, ב ואילך. סה״ש תש״ב ע׳ 75."],["17","17","נח ו, טז. וראה לקמן הערה 26."],["18","18","לעיל ע׳ 286-7."],["19","19","הובאה בד״ה צהר תעשה תרצ״ה בתחלתו ובכ״מ (ראה הוספות לכש״ט (הוצאת קה״ת) סי׳ י)."],["20","20","נח ז, א."],["21","21","לשון כ״ק מו״ח אדמו״ר בד״ה צהר תעשה שם."],["22","22","ראה בארוכה לעיל ע׳ 269, וע׳ 282."],["23","23","ראה ד״ה מים רבים סעיף ו׳ (לעיל ע׳ 280)."],["24","24","(נח ז, יז) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו״א ט, סע״א</a>."],["25","25","נח ח, ד. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560354\" data-slug=\"or-hatorah-hb\" data-id=\"8316560354\">אוה״ת נח ע, א</a>. (כרך ג׳) תרמג, ב ואילך."],["26","26","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560321\" data-slug=\"or-hatorah-hb\" data-id=\"8316560321\">אוה״ת שם תרכז, א</a> (מרמ״ז), שג׳ הבחינות תחתיים שניים ושלישיים הם בי״ע אצילות"]]],[1300201310,"שע״י הליכת וירידת אברם אל הארץ בחי׳ מלכות, שהתכלית (דירידה זו) הוא להיות גילוי בבי״ע²⁷ [וכידוע²⁸, שהליכת אברם אל הארץ הי׳ בכדי להמשיך בבי״ע עד בעוה״ז הגשמי, שעי״ז עשה הכנה לההמשכה שע״י מעשה המצוות בגשמיות לאחרי מ״ת] נעשה עילוי גם בבחי׳ שכל הנעלם מכל רעיון.\nג) ופירוש הב׳ בלך לך גו׳ אל הארץ הוא (כפשטות הכתוב²⁹) שהליכה זו היא מלמטה למעלה, ההליכה מארצך וממולדתך ומבית אביך שהוא (כפשטות הכתוב) ארצו וגו׳ של תרח [היפך ענין הטהרה³⁰], דרגא הכי תחתונה, ומשם ילך ויעלה מלמטלמ״ע עד אל הארץ אשר אראך שקאי (כנ״ל ס״א) על בחי׳ המלכות, ועד לבחי׳ ויבן שם מזבח להוי׳ הנראה אליו³¹ (שהוא למעלה מבחי׳ מלכות), ועד אשר ויבן שם מזבח להוי׳ סתם³², בחי׳ הוי׳ דלעילא, הוי׳ הנעלם, שלמעלה מהוי׳ (דלתתא) הנראה³³. ועד״ז הוא גם בהעבודה ד„ויעקב הלך לדרכו” שבכאו״א שלאחרי חודש תשרי, שהליכה זו היא (לא רק באופן דמלמעלמ״ט, שהולך לדרכו מהמועדים דחודש תשרי לדרכו בעניני הרשות ועובדין דחול במשך כל השנה, אלא) גם באופן דמלמטלמ״ע, מתחיל מכח המעשה שלו, ובכח המעשה גופא כמו שהוא בהעקב שבו, דרגא היותר תחתונה שבגוף האדם [ועד שהוא ענין דהיפך החיים³⁴, בדוגמת המובא לעיל בנוגע לתרח שהוא היפך הטהרה], ומשם מתחיל הליכתו מלמטלמ״ע, שפועל גם בהעקב שלו ער זאל דערהערן אלקות [וכמ״ש באברהם עקב אשר שמע אברהם בקולי³⁵ שגם העקב שלו האט",[["","","ואי״ק. וידוע (שעה״ק להרח״ו ח״ג פ״ב. ע״ח שער דרושי אבי״ע פ״ג — הובא בהמשך תרס״ו ע׳ רל. ד״ה ויהי אומן עטר״ת פ״א. ובכ״מ) שנר״נ הם מבי״ע, חי׳ מאצי׳, ויחידה מא״ק. וזהו גם הכוונה במ״ש בלקו״ד שם, שחמשה השמות נרנח״י הם תחתיים שניים שלישיים רביעיים וחמישיים שהם ד׳ עולמות אבי״ע ועולמות הא״ס שלמעלה מאצילות, שמונה העולמות בי״ע לג׳ בחינות — כהפי׳ (אוה״ת שם, משל״ה), שתחתיים שניים ושלישיים הם בי״ע (ועפ״ז יש „רביעיים וחמישיים” — ובדוגמת ה׳ שמות דנשמה)."],["27","27","תו״א ריש פרשתנו (וראה הגהות הצ״צ לשם אוה״ת פרשתנו כרך ג תרפה, ב. תרפט, ב)."],["28","28","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670266\" data-slug=\"torat-chaim\" data-id=\"2300670266\">תו״ח שם פג, ד</a> ואילך. אוה״ת שם (כרך ו<a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">׳) תתרעה, סע״א</a> ואילך. וראה גם תו״א יא, סע״ג."],["29","29","וכ״ה בלק״ת להאריז״ל — מובא במקומות שבהערה 1."],["30","30","ראה במדב״ר רפי״ט: מי יתן טהור מטמא .. כגון אברהם מתרח."],["31","31","פרשתנו יב, ז."],["32","32","שם, ח."],["33","33","אוה״ת פרשתנו (כרך ד׳) תרפד, ב. תרפז, ב. תרפט, סע״א. ד״ה בחודש השלישי תש״ב."],["34","34","אדר״נ ספל״א."],["35","35","תולדות כו, ה."]]],[1300201311,"דערהערט³⁶. וע״י שהי׳ זה אצל אברהם אבינו, ניתן הכח על זה לכאו״א מישראל (בדוגמת האהבה מסותרת שבכאו״א מישראל שהיא בירושה לנו מאבותינו³⁷, ובפרט מאברהם אבינו³⁸)], ומזה נמשך (באופן דהילוך מלמטלמ״ע) השמיעה (דער דערהער) באלקות בכל הכחות, עד לכח השכל שבראש, שתהי׳ בהם השמיעה למעלה ממדידה והגבלה דשכל.\nוגם ענין זה ד„ויעקב הלך לדרכו” (הליכה מלמטלמ״ע) מתחיל לאחרי חודש תשרי. דהנה העבודה דשמע״צ ושמח״ת (סיום המועדים דחודש תשרי) היא ב(שמחה ו)ריקודים, שענין הריקודים הוא (בעיקר ומתחיל) בהרגלים, ובהם גופא בהעקב שבהם. וע״י שהעקבים מתנשאים (הויבן זיך) ומרקדים, הם מנשאים גם את הראש (וכח השכל שבו)³⁹, שגם הוא מרקד בשמחה גדולה למעלה ממדידה והגבלה. ומזה נמשך כח על העבודה דויעקב הלך לדרכו (הליכה מלמטלמ״ע) במשך כל השנה, מתחיל מכח המעשה כמו שהוא בהעקב [כולל הענינים שאדם דש בעקביו⁴⁰, היינו ענינים אשר (מצד איזה סיבה שתהי׳) אין לו חיות בהם (בדוגמת העקב כפשוטו שהו״ע דהיפך החיים)], ומזה ממשיך (באופן דהילוך מלמטלמ״ע) גם לכח השכל שבראש, כנ״ל.\nד) ושני פירושים הנ״ל בלך לך מארצך גו׳ הם בהתאם לשני הפירושים ב„בעבר הנהר ישבו אבותיכם”⁴¹. הפירוש [שבפנימיות התורה⁴²] שעבר הנהר הוא הבחי׳ שלמעלה (גם) מבחי׳ ונהר יוצא מעדן⁴³ (בינה דאצילות) ופירוש בעבר הנהר ישבו אבותיכם גו׳ הוא ששרש האבות הוא מעבר הנהר שלמעלה מאצילות ומשם נמשכו למטה (בעבר השני של הנהר, היינו) בז״א דאצילות, ועד ש„ואולך אותו בכל ארץ כנען”⁴⁴ הירידה וההמשכה בבחינת המלכות (כנ״ל סעיף א׳ שארץ ישראל קאי על מלכות) — ההליכה מארצך גו׳, שקאי על עבר הנהר, אל הארץ אשר אראך, הוא הליכה מלמעלה למטה⁴⁵. והפירוש (כמו שהוא בפשטות) שעבר הנהר הוא מקומו",[["36","36","סה״מ תש״ח ס״ע 253. התמים ח״ו ע׳ נב."],["37","37","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי״ח</a>."],["38","38","תו״ח שמות תקלו, סע״ב. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו״ת סוכות עח, ד</a>. שמע״צ פט, ב."],["39","39","ראה גם לעיל ע׳ 267 ואילך."],["40","40","רש״י ר״פ עקב."],["41","41","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770315\" data-slug=\"or-hatorah-hb\" data-id=\"8316770315\">יהושע כד, ב</a>. ובאוה״ת פרשתנו שם תרפב, ב הובאו ב׳ הפירושים דלקמן."],["42","42","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370117\" data-slug=\"torah-or\" data-id=\"3901370117\">תו״א כה, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">עה, ד</a>. דרמ״צ פב, ב. ובכ״מ."],["43","43","בראשית ב, יו״ד."],["44","44","יהושע שם, ג."],["45","45","ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770323\" data-slug=\"or-hatorah-hb\" data-id=\"8316770323\">אוה״ת שם תרצ, ב</a>."]]],[1300201312,"של תרח, ומ״ש בעבר הנהר ישבו אבותיכם גו׳ הוא לגריעותא [כדמוכח ממרז״ל⁴⁶ מתחיל בגנות כו׳ מתחילה עובדי ע״ז היו אבותינו כו׳ שנאמר בעבר הנהר ישבו אבותיכם גו׳] — ההליכה מארצך גו׳ (עבר הנהר) אל הארץ אשר אראך, הילוך ועלי׳ מלמטלמ״ע⁴⁷ (כנ״ל סעיף ג׳).\nה) והנה הגם שב׳ פירושים הנ״ל ב„לך לך” הם שני פירושים שונים והפכיים, מ״מ, מכיון שב׳ הפירושים הם באותה התיבה (תיבת לך), מוכח מזה⁴⁸, שענין „לך לך” [וההוראה לכאו״א מישראל שבפרשה זו] כולל ב׳ האופנים יחד, הילוך מלמעלמ״ט והילוך מלמטלמ״ע. ובדוגמת „והתהלכתי בתוככם”⁴⁹ ש„והתהלכתי” (לשון רבים) כולל⁵⁰ ב׳ בחינות הילוך הנ״ל⁵¹. וכ״ה גם בענין ואולך אתכם קוממיות⁵², ש„קוממיות” (לשון רבים)⁵³ מורה על ב׳ קומות⁵⁴ [קומה דאו״י וקומה דאו״ח, שהם דוגמת ב׳ בחינות הילוך הנ״ל⁵⁵], הכוונה בזה היא ש„קוממיות” כולל ב׳ הקומות יחד.\nויש לקשר זה עם שנה זו (ביחוד), שהיא שנת העיבור, ויתירה מזו שהיא שנת העיבור דסיום מחזור קטן, שבה נעשה ההתאמה דשנת החמה עם שנת הלבנה (בתכלית השלימות)⁵⁶. דהנה שמש הוא בחי׳ משפיע — דוגמת ענין ההילוך מלמעלמ״ט, ולבנה (דלית לה מגרמה כלום⁵⁷) הוא בחי׳ מקבל — דוגמת ענין ההילוך מלמטלמ״ע. וענין שנת העיבור (ובפרט שנת העיבור דסיום מחזור קטן) הוא צירוף וחיבור ב׳ העבודות [העבודה דשמש (בחי׳",[["46","46","פסחים קטז, א."],["47","47","ראה גם אוה״ת שם תרצא, ב."],["48","48","ראה לקו״ש כרך ג׳ ע׳ 782 (הראי׳ לזה מ„שעטנז”)."],["49","49","בחוקותי כו, יב."],["50","50","ובנוגע ל„והתהלכתי” — פשוט שכולל ב׳ הבחינות, מכיון (שאין זה שני פירושים כ״א) שפירוש „והתהלכתי” הוא ב׳ אופני הילוך. ועד״ז הוא גם בנוגע ל„קוממיות” (דלקמן בפנים)."],["51","51","דרושי ד״ה והתהלכתי — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940234\" data-slug=\"or-hatorah-hb\" data-id=\"8159940234\">אוה״ת ויקרא (כרך ב׳) ע׳ תרמ</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380820\" data-slug=\"likkutei-torah\" data-id=\"4001380820\">לקו״ת ראה כו, א</a>. אמ״ב שער הק״ש פפ״ז. ספפ״ח ואילך."],["52","52","בחוקותי כו, יג."],["53","53","ראה חדא״ג מהרש״א לב״ב שבהערה הבאה."],["54","54","ב״ב עה, א. סנהדרין ק, א."],["55","55","אמ״ב שם פפ״ט. אוה״ת שם ע׳ תרנג. תערב־ג."],["56","56","ראה בארוכה במכתב דוא״ו תשרי תשל״ח*. וש״נ."],["57","57","זח״ב קמה, ב. ועוד. *) לקו״ש חי״ד ע׳ 477 ואילך. המו״ל."]]],[1300201313,"משפיע, הילוך מלמעלמ״ט, שבכללות הוא⁵⁸ עבודת הצדיקים), והעבודה דלבנה (בחי׳ מקבל, הילוך מלמטלמ״ע, שבכללות הוא⁵⁸ עבודת הבעלי תשובה)], שייעשו ענין אחד (שנה תמימה), כמשנ״ת לעיל⁵⁹ בארוכה. וכמ״ש⁶⁰ ועינינו מאירות כשמש וכירח, שהכוונה בזה היא [לא רק שיהיו ב׳ המעלות, המעלה דשמש והמעלה דירח אלא גם] שב׳ הענינים (והמעלות) יהיו כאחד.\nוענין זה [צירוף ואיחוד ב׳ ענינים הנ״ל] הוא הכנה וכלי [ובאופן דאבר, שהוא לא רק מקבל אלא גם ממשיך⁶¹] להמשכת אוא״ס שלמעלה מגדר „מעלה ומטה”. [וע״ד הידוע⁶² שלאחרי השלימות דאתערותא דלתתא (בחי׳ לבנה) וגילוי אתערותא דלעילא (בחי׳ שמש) (הנמשכת ע״י אתערותא דלתתא) נמשך אח״כ בחי׳ אתעדל״ע ממקום שאין אתעדל״ת מגעת שם כלל]. ששלימות העבודה [בצירוף ב׳ ענינים הנ״ל, שנה תמימה] הוא האתר שלים, שהוא כלי להשראת אוא״ס, דקוב״ה שריא באתר שלים⁶³. ועד שעי״ז נעשה המשכת העצמות שהוא אמיתית ותכלית השלימות. ונעשים ישראל וקוב״ה (ע״י אורייתא) כולא חד⁶⁴, ובאופן שאין שייך לחלק ביניהם, מכיון שתורת אמת מעידה שהם חד.",[["58","58","ראה לעיל ע׳ 288 הערה 65*."],["59","59","לעיל ע׳ 287-8."],["60","60","נוסח התפלה דשבת (נשמת). וראה בהמצויין לעיל ע׳ 290 הערה 83."],["61","61","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370510\" data-slug=\"torah-or\" data-id=\"3901370510\">תו״א קיד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380807\" data-slug=\"likkutei-torah\" data-id=\"4001380807\">לקו״ת ראה כב, סע״ד</a>. ד״ה אדון עולם תש״ג פ״ה. ובכ״מ."],["62","62","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו״ת שה״ש כד, סע״א</a> ואילך."],["63","63","זח״ג צ, ב."],["64","64","ראה זהר שם עג, א."]]],[1300201314,"שיחת מוצאי ש״פ לך לך - בחדרו - ה׳תשל״ח.\nא. שוין גערעדט כמה פעמים¹ בנוגע צו שמות הסדרות, אז דער נאמען פון יעדער סדרה בריינגט ארויס דעם תוכן פון דער גאנצער סדרה. [ביז אז דער נאמען פון יעדער סדרה איז אויף איר חיות, כתורת הבעש״ט² אז זה שמו אשר יקראו לו בלשון הקודש איז מהווה מחי׳ און מקיים די זאך הנקרא בשם זה].\nדערפון איז פארשטאנדיק בנוגע לפרשתנו — לך לך, וויבאלד אז דער נאמען פון דער סדרה איז „לך (לך)”, ענין ההליכה, אז דער תוכן (און חיות) פון דער סדרה איז ענין ההליכה.\nוע״פ תורת כ״ק אדמו״ר הזקן³ אז מען דארף לעבן מיט פרשת השבוע — איז מובן, אז דער ענין מיט וועלכן א איד דארף לעבן במשך כל ימי השבוע דפרשת לך לך (כולל אויך דעם זמן פון מוצאי שבת⁴), איז ענין ההליכה.\nב. פון דעם איז מובן בפשטות די שייכות מיוחדת פון שבוע דפרשת לך לך מיט די ענינים וואס מען האט גערעדט אין די פריערדיקע שיחות און מאמרים (אנהויבנדיק פון מוצאי שמח״ת) בנוגע צו „ויעקב הלך לדרכו”\nווארום פון די הדגשות עיקריות אין „ויעקב הלך לדרכו” איז⁵ אז די עבודה דארף זיין אין אן אופן פון „הלך”.\nואדרבה, בשבוע דפרשת לך לך קומט נאך צו א הוספה אין דעם: אין די פריערדיקע וואכן האט מען נאר געוואוסט און פארשטאנען אז עס דארף זיין „ויעקב הלך לדרכו”; און אין פרשת לך לך איז דאס (בהדגשה ו)בגילוי, מצד דערויף וואס דאס (ענין ההליכה) ווערט ארויסגעגעבן בגילוי אין שם הסדרה.\nאון וויבאלד אז מוצאי שבת איז מחבר דעם שבת שלפנ״ז [וואס מיטן לשון „שבת (שלפנ״ז)” דא מיינט מען אויך די גאנצע וואך, „שבת” מלשון שבוע] מיט דער קומענדיקער וואך — איז דערפון מובן, אז במוצאי שבת פרשת לך לך, דארף מען מיטנעמען דעם ענין ההליכה (ווי ער איז בהדגשה ובגילוי אין פרשת לך לך) אויף די קומענדיקע ימים (שבועות וחדשים).\n[און נאך מער: אז בימים הבאים דארף דאס נאך זיין מיט א הוספה, כהציווי „מעלין בקודש”⁶].\nג. ולכאורה איז ניט מובן: ע״פ מה שנתבאר לעיל⁷ בנוגע די כמה דרגות וואס אין „ויעקב הלך לדרכו”\n— אז דער „ויעקב הלך לדרכו” שבמוצאי שבת בראשית איז אין אופן אז מען גייט שוין „לדרכו” ממש (אויך אין עובדין דחול), וואס אין דעם באשטייט דער חידוש אין „ויעקב הלך לדרכו” ווי ער איז במוצאי שבת בראשית לגבי ווי ער איז במוצאי יוהכ״פ, און אפילו לגבי ווי ער איז במוצאי שמח״ת,",[["1","1","ראה גם לעיל ע׳ 285 ובהנסמן שם."],["2","2","שעהיוה״א פ״א."],["3","3","סה״ש תש״ב ע׳ 29 ואילך."],["4","4","כשמו: „מוצאי שבת פ׳ לך” — ומלוה (הולך ביחד עם) השבת דפ׳ לך."],["5","5","ראה בארוכה לעיל ע׳ 270-1."],["6","6","ברכות כח, א. וש״נ."],["7","7","לעיל ע׳ 266-9. ע׳ 281-2."]]],[1300201315,"און דערנאך במוצאי שבת פרשת נח קומט צו א חידוש נוסף (אפילו לגבי מוצאי שבת בראשית), אז דער „ויעקב הלך לדרכו” [ווי ער איז שוין באופן „לדרכו” ממש, וואס האט זיך אויפ־געטאן במוצאי שבת בראשית] איז שוין געקומען אויף בפועל (במשך כל שבעת ימי ההיקף) —\nאיז וואס איז שייך אז ב(מוצאי שבת) פרשת לך לך זאל נאך צוקומען אין דעם און דערצו נאך — א הוספה עקרית?\nוואלט מען געזאגט אז די הוספה איז מצד דערויף וואס אין אלע עניני קדושה דארף מען האלטן אין מוסיף זיין (כהציווי „מעלין בקודש”⁶) — וואלט קיין קשיא ניט געווען, ווארום דאס איז נאר א הוספה און העלאה אין דעם ענין „ויעקב הלך לדרכו” דמוצאי ש״פ נח; וויבאלד אבער אז מען זאגט אז די הוספה וואס דארף צוקומען ב(מוצאי שבת) פרשת לך לך איז מצד דעם ענין פון פרשת „לך לך” (ווייל דער שם הסדרה איז מדגיש דעם ענין ההליכה, כנ״ל) — פאדערט זיך ביאור: וויבאלד אז דער „ויעקב הלך לדרכו” ווי ער איז במוצאי ש״פ נח איז שוין (לכאורה) די העכסטע דרגא, טא ווי איז שייך אז עס זאל צוקומען אויף דעם א הוספה בתוכן עיקרי (וחדש)?\nד. וועט מען עס פארשטיין בהקדים, וואס די הדגשה אין „ויעקב הלך לדרכו” איז: (א) אז דער „הלך” זאל זיין „לדרכו” (סתם, אן אויסנאם) — אז אלע ענינים פון „דרכו” זאלן זיין באופן דהליכה; (ב) אז דער „הלך לדרכו” זאל זיין אין אזא אופן ווי „יעקב” טוט עס.\nאון די צוויי ענינים זיינען פארבונדן זה בזה. והביאור בזה:\nנוסף צו דעם וואס דער שם „יעקב”\n(יו״ד עקב) ווייזט אויף דערויף, אז ער (ניט קוקנדיק אויף דעם וואס ער איז בבחינת עקב) ווערט אנגעפירט פון דעם יו״ד דשם הוי׳, וואס אין שם הוי׳ גופא [וואס שם הוי׳ (בכלל) איז למעלה מהתחלקות] ווייזט דער יו״ד אויף ענין התמידות (למעלה מהתחלקות ושי־נויים⁸), כמשנ״ת לעיל⁹ בארוכה,\nאיז דא נאך אן ענין אין דעם שם „יעקב”, אז ער איז פארבונדן מיטן תואר „עבד”¹⁰. און ווי מען זאגט אויף יעדער מוצאי שבת קודש [אנהויבנדיק פון מוצש״ק פ׳ בראשית, דער ערשטער מוצש״ק שלאחרי שמח״ת¹¹] „אל¹² תירא עבדי יעקב”¹³, אז יעקב איז פארבונדן מיט „עבדי”.\nאון וויבאלד אז די עבודה פון אן „עבד” איז בכל הענינים בשוה, כדלקמן (סעיף ה׳) — דעריבער איז דער „ויעקב הלך לדרכו” (דער הילוך פון „עבדי יעקב”) אין אזא אופן, אז דער הילוך איז אין אלע ענינים פון „דרכו”, ביז אז בכל הענינים איז דאס בשוה.\nה. דער אויפטו פון עבודה דבחי׳ עבד אויף קיום המצות בכלל (שלא בדרגא זו) — אע״פ אז אויך דער קיום המצות בכלל, טוט זיי א איד בשליחותו של הקב״ה [נוסף צו דעם וואס די מצוות",[["8","8","וגם מצד זה, ההליכה „לדרכו” היא בכל הענינים בשוה."],["9","9","לעיל ע׳ 269-70."],["10","10","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380600\" data-slug=\"likkutei-torah\" data-id=\"4001380600\">לקו״ת בלק ע, רע״ג</a>. המשך תרס״ו ע׳ רכה, שה. ובכ״מ."],["11","11","ראה ד״ה בראשית ברא סעיף ה׳ (לעיל ע׳ 264-5)."],["12","12","לשון הכתוב — ישעי׳ מד, ב. ירמי׳ ל, יו״ד. ועוד."],["13","13","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו״ת שם עב, ב</a> — הובא (גם) בד״ה הנ״ל שם."]]],[1300201316,"זיינען שלוחים של הקב״ה¹⁴], וואס „שלוחו של אדם (העליון¹⁵) כמותו”.\nאין דעם ענין השליחות זיינען דא דריי (אופנים) מדריגות¹⁶:\nא) אויך בשעת עשיית השליחות איז דער שליח א מציאות בפני עצמו, און די מעשה השליחות איז זיך מתייחס צו אים (צום שליח). און דער ענין פון „שלוחו של אדם כמותו” איז נאר אז זיין עשי׳ איז כאילו ווי דער משלח וואלט דאס געטאן.\nב) א העכערע מדריגה: אז די מעשה גופא איז זיך מתייחס צום משלח. דאס הייסט, אז (ניט דער שליח טוט עס, נאר) דער משלח טוט עס דורך אים.\nג) נאך א העכערע מדריגה: אז (ניט נאר די עשיית השליח און זיין כח המעשה, נאר אויך) דער שליח גופא איז דער משלח.\nאון דאס איז דער אויפטו פון אן „עבד” אויף א „שליח”:\nאין שליחות קען דאך זיין כמה מדריגות. און וויבאלד אז אלע דריי מדריגות הנ״ל זיינען אופנים אין זעלבן ענין (ענין השליחות) — איז דערפון פארשטאנדיק, אז אפילו אין דער העכסטער מדריגה (וואס דער שליח גופא איז דער משלח) איז שייך צו אפ־טיילן דעם שליח פון משלח¹⁷:\nמשא״כ אן עבד איז ניט קיין מציאות בפני עצמו כלל, און כל מציאותו [ובמילא, הכחות שלו — פון זיין כח המעשה ביז זיין כח התענוג] איז די מציאות פון דעם אדון¹⁸.\nוואס דערפאר איז „מה שקנה עבד קנה רבו”¹⁹ [אז אלץ נאר וואס דער עבד האט („מה שקנה”, וואס עס זאל נאר ניט זיין) איז „קנה רבו”], ביז אז דאס ווערט (לדיעה אחת) נקנה מלכתחילה צו רבו²⁰.\nאון וויבאלד אז כל מציאותו פון דעם עבד איז די מציאות האדון — איז במילא ניט שייך אז בא אים זאל זיין א חילוק (מצדו) פון זיין עבודה ביז די צווייטע²¹ (וויבאלד אז ער איז ניט קיין מציאות לעצמו כלל).\nו. דערפון איז אויך פארשטאנדיק בנוגע צו „ויעקב הלך לדרכו”, אז דער הילוך פון „ויעקב הלך לדרכו” — וויבאלד אז ענינו פון „יעקב” איז „עבדי יעקב” (כנ״ל ס״ד) — איז בכל עניניו, און בכל עניניו, בשוה:\nדער ענין ההליכה קען זיין בנוגע צו בלויז אין כח [בנוגע צו כח המעשה (כח הכי תחתון) וכו׳ — ביז בנוגע צו כח",[["14","14","תנחומא ויגש ו."],["15","15","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו״ת ויקרא א, ג</a> (בנוגע לנש״י). ובתנחומא שם (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380133\" data-slug=\"likkutei-torah\" data-id=\"4001380133\">לקו״ת שם ב, א</a>) — בנוגע למצוות."],["16","16","בהבא לקמן — ראה בארוכה לקח טוב (למהרי״ ענגיל) כלל א. ובהמצויין שם (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181376\" data-slug=\"likkutei-sichot\" data-id=\"1300181376\">לקו״ש חי״ח ע׳ 367</a> הע׳ 24, שמשו״ע אדה״ז סרס״ג סכ״ה בקו״א משמע באופן הג׳). ענינים של ג׳ מדריגות אלו בעבודת האדם — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191336\" data-slug=\"likkutei-sichot\" data-id=\"1300191336\">לקו״ש חי״ט ע׳ 323</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121148\" data-slug=\"likkutei-sichot\" data-id=\"1300121148\">חי״ב ע׳ 148</a>."],["17","17","כדמוכח גם מזה שיחס השליח להמשלח (גם לפי אופן הג׳ שהשליח עצמו הוא המשלח) — הוא רק בנוגע לענין השליחות, ולא בנוגע לשאר עניניו*. ודלא כעבד, שכל „מה שקנה עבד קנה רבו”, כדלקמן בפנים."],["18","18","ראה בארוכה המשך תרס״ו ע׳ שכו-שכז."],["19","19","פסחים פח, ב. קידושין כג, ב."],["20","20","ראה רשב״א לקידושין שם."],["21","21","המשך הנ״ל ע׳ שכא-שכב. *) ולהעיר דגם לדעת ר׳ שילא ד„אין שליח נעשה עד (לפי ד)הוה לי׳ כגופי׳” (קידושין מג, א), לפי דס״ל (כאופן הג׳) „דהשליח נחשב כגוף המשלח וא״כ הוא עצמו הבעלים ואין יכול להעשות עד־” (לקח טוב שם ס״א) יכול הוא להעיד להמשלח בענינים שאינם שייכים לשליחותו."]]],[1300201317,"התענוג (כח הכי נעלה)], אז זיין עבודה איצטער אין דעם כח — איז שלא בערך צו זיין עבודתו אין דעם כח ווי ס׳איז געווען פריער (וואס דאס איז אמיתית ענין ההליכה, אז ער גייט אוועק לגמרי פון זיין פריערדיקן מעמד ומצב)⁵,\nאיז אע״פ אז אויך ווען דער „הילוך” (עבודה שלמעלה ממדידה והגבלה) איז בלויז אין איין כח (מעשה, דיבור, מחשבה, מדות, שכל, רצון אדער תענוג), איז עס אן ענין נעלה ביותר, ווארום בא אים איז שוין פאראן (בנוגע לכח אחד עכ״פ) די עבודה פון „בכל מאדך” — קומט עס אבער ניט (און — שלא בערך) צו די מדריגה ווען דער „הילוך” איז בכל עניניו:\nבשעת אז דער „בכל מאדך” איז בא אים נאר אין איין כח, אדער אפילו אין רובם (אבער ניט אין אלע), איז [נוסף אויף דעם וואס ס׳איז נאך פארבליבן בא אים אן ענין וואס (זיין עבודה) איז במדידה והגבלה] וויבאלד אז זיין עצם מציאות האט ער נאך ניט איבער־געשטעלט (וואס דערפאר איז בא אים פארבליבן אין כח (עכ״פ) במדידה והגבלה), איז עס נאך ניט דער אמיתית הענין פון „בכל מאדך”.\nאון אין דעם באשטייט דער עילוי אין דער הליכה פון „לך לך” אויף די הליכה פון „ויעקב (ניט זאגנדיק דערביי — עבדי) הלך לדרכו” וואס פאר פרשת לך לך — ווארום אין די הוראה „לך לך” איז מודגש בגילוי²² אז דער ענין ההליכה דארף זיין בכל הענינים, כדלקמן.\nז. אויף אברהם אבינו [וואס צו אים איז געזאגט געווארן דער ציווי „לך לך” (און אויך דער סיפור פון כל קורות ועניני אברהם אבינו הויבט זיך אן בעיקר אין פרשת לך לך)] שטייט²³, אז ער איז געווען „נדיב בממונו בגופו ובנפשו”,\nדאס הייסט, אז זיין עבודה — וואס זיין עבודה (עיקרית) איז געווען בקו החסד²⁴ (נדיבות) — האט אים דורכ־גענומען בכל מציאותו ובכל עניניו, וואס כל זה באשטייט און טיילט זיך אין די דריי חלוקות ממון, גוף און נפש.\n[און די נדיבות און חסד פון אברהם איז געווען בלי גבול²⁵, העכער פון מדידה והגבלה²⁶\n[וכמרז״ל²⁷ אז מען לערנט אפ פון אברהם׳ן — אז הכנסת אורחים איז „גדולה מהקבלת פני שכינה” (וואס „הקבלת פני שכינה” מיינט, אז עס ווערט נתקבל (בפנימיות) „פני שכינה”, בחי׳ פנימיות דשכינה) — ווייל שכינה (כולל אויך „פני שכינה”) איז „על שם ששוכנת ומתלבשת תוך כל עלמין”²⁸, און זיין חסד איז העכער פון הגבלה²⁹],",[["22","22","משא״כ ב„ויעקב הלך לדרכו” — רק משמע כן (שההליכה צריכה להיות בכל עניניו) מענין „ויעקב הלך לדרכו” (כנ״ל ס״ד), אבל אין זה מודגש בגילוי."],["23","23","אורחות צדיקים שער יז."],["24","24","ורק מצד זה ש„כל המדות כלולות זו מזו”, הי׳ בו גם מדת הגבורה (אגה״ק סי״ג. ובכ״מ)."],["25","25","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו״א יב, א</a> [ובהגהות הצ״צ לשם — <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490047\" data-slug=\"or-hatorah-hb\" data-id=\"8316490047\">אוה״ת לך לך (כ״ד) תרצג, א</a>]. אוה״ת וירא צ, ב. צג, ב."],["26","26","באוה״ת לך לך שם ובאוה״ת וירא צג, ב, שהבל״ג דחסדו של אברהם היא למעלה גם מהמדידה והגבלה דחסד דאצילות."],["27","27","שבת קכז, א. רמב״ם הל׳ אבל פי״ד ה״ב."],["28","28","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ״א (נז, ב</a>)."],["29","29","והכנסת אורחים דכל אחד גדולה מהקבלת פני שכינה (אף שהחסד הוא מוגבל) — לפי „שלמדין” זה מאברהם אבינו (כבפנים), שממנו נמשך הכח בכל אחד מישראל, שבעשיית החסד שלו"]]],[1300201318,"איז די נדיבות פון אברהם אבינו אין יעדער ענין פון די דריי הנ״ל — סיי „בממונו”, סיי „בגופו”, סיי „בנפשו” — איז געווען (ניט נדיבות סתם, נאר) באופן פון זיין נדיבות (נדיבות דאברהם אבינו), למעלה ממדידה והגבלה³⁰].\nוואס פון דעם איז מובן, אז דער ציווי „לך לך” וואס איז געזאגט געווארן צו אברהם אבינו איז — אז די הליכה זאל זיין אין אלע זיינע כחות.\nאון וויבאלד אז דער ציווי „לך לך” וואס איז געזאגט געווארן צו אברהם אבינו איז אויך א הוראה צו יעדער אידן (כדלקמן סעיף יב), אז אויך בא אים זאל זיין „לך לך” בדוגמא ווי ס׳איז געווען בא אברהם אבינו — איז דעריבער פארשטאנדיק, אז אויך די הוראה „לך לך” צו יעדער אידן איז, אז די הליכה זאל זיין אין אלע זיינע ענינים.\nח. ענין הנ״ל — אז דער ציווי „לך לך” (ניט נאר צו אברהם אבינו, נאר אויך צו יעדער אידן) איז בנוגע צו אלע זיינע כחות — קומט ארויס נאך מער בהדגשה אין די ווערטער שלאחרי זה „מארצך וממולדתך ומבית אביך”, וואס טייטשן אפ דעם „לך לך”: אז דער הילוך („לך לך”) דארף זיין סיי בנוגע צו „ארצך” (רצון³¹), סיי בנוגע צו „מולדתך” (מדות³¹), סיי בנוגע צו „בית אביך” (מוחין³¹).\nאז די אלע דריי ענינים הנ״ל [וואס זיי זיינען כללות כל הכחות] זאלן זיין ניט ווי זיי זיינען מצד הטבע (כאטש אז דאס רעדט זיך וועגן טבע דאברהם אבינו³¹), נאר זיי זאלן זיין אין א אופן פון „לך”, בבחינת הליכה שלמעלה ממדידה והגבלה (העכער אפילו פון מדידה והגבלה דאברהם אבינו),\nביז אז די עלי׳ (והילוך) אין אלע זיינע כחות איז אין אן אופן אז זיי זיינען שלא בערך⁵ לגבי ווי זיי זיינען געווען פריער,\nוואס דעריפאר זאגט ער „לך לך גו׳ מארצך וממולדתך ומבית אביך”, אז ער זאל אוועקגיין פון „ארצך” „מולדתך” און „בית אביך” — ווארום די כחות הנ״ל ווי זיי זיינען מצד הטבע (דאברהם אבינו) [„ארצך” „מולדתך” „בית אביך”] זיינען ניט בערך⁵ לגבי ווי זיי זיינען נאך דער עבודה פון „לך”.\nט. דער „הילוך” (שלא בערך) וואס עס דארף זיין אין אלע כחות און עניני הנפש — „ארצך”, „מולדתך” און „בית אביך” — איז דער פסוק מבאר דורך זיין צוגעבן דעם ווארט „לך”, אז דער „לך” דארף זיין „לך”. והביאור בזה:\nאין „לך” זיינען פאראן כמה פירושים. ומהם: (א) „לך — להנאתך”³²: (ב) „לך — לעצמך, לשרשך ומקורך”³³. וואס לויט ביידע פירושים, איז מודגש אין דעם ווארט „לך”, אז די הליכה וואס דארף זיין (אין אלע כחות ועניני הנפש) איז א שינוי שלא בערך לגבי ווי זיי זיינען געווען פריער:",[["","","יהי׳ מעין הענינים (והמעלות) שבעשיית החסד דאברהם. ועפ״ז יומתק: (א) מ״ש הרמב״ם שם „שנאמר וירא והנה שלשה אנשים” (אף שבכלל אין דרכו להביא המקורות של ההלכות). (ב) מה שמקדים „והוא החק שחקקו אברהם אבינו כו׳”. (וראה לקו״ש ח״ג ע׳ 765 ואילך הביאור בדברי הרמב״ם שם באופן אחר)."],["30","30","ראה ד״ה אשר ברא תרפ״ט ס״ד וה׳: ד״ה כל הנהנה תרפ״ט ס״י. וראה אוה״ת וירא (צ, ב), שמקשר הנדיבות דאברהם אבינו בממונו בגופו ובנפשו, עם זה שהחסד דאברהם הי׳ בלי גבול."],["31","31","ראה סד״ה לך לך תש״ה."],["32","32","פרש״י ריש פרשתנו."],["33","33","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490022\" data-slug=\"or-hatorah-hb\" data-id=\"8316490022\">אוה״ת לך לך</a> (כ״ד) תרפ, סע״ב. המשך תרס״ו ע׳ סז, שצז. ד״ה לך לך תש״ב. תש״ה. ובכ״מ."]]],[1300201319,"„לך — להנאתך” מיינט, אז טראץ דעם וואס מאנט זיך פון אים אז ער זאל אוועקגיין פון זיין פריערדיקן מעמד ומצב (ארויסגיין פון זיך) — פונדעסט־וועגן, וויבאלד אז דאס איז דעם אויבערשטנס רצון, ווערט דאס זיין הנאה און תענוג.\nוואס דאס איז דער ענין פון אן עבד, אז זיין תענוג איז דער תענוג האדון³⁴.\nוואס דערפון איז מובן דער גודל העילוי (והשינוי) וואס ווערט דורך די הליכה פון „לך לך” — ווארום דער אויפטו פון אן עבד (אויף קיום התומ״צ סתם) איז שלא בערך (כנ״ל סעיף ה׳):\nאון עד״ז (און נאך מער) איז לויטן צווייטן פירוש אין „לך” — „לעצמך, לשרשך ומקורך”. ווארום ענין ההליכה לשרשו ומקורו איז דער ענין פון תשובה בבחינת „והרוח תשוב אל האלקים אשר נתנה”³⁵, און דער אויפטו וואס אין עבודת התשובה (ובפרט אין תשובה דבחינת „והרוח תשוב אל האלקים אשר נתנה”) אויף עבודת הצדיקים, איז שלא בערך³⁶.\nיו״ד. נאך אן ענין אין דער הוראה הנ״ל (סוף סעיף ו׳ ואילך) [וואס קומט צו אין פרשת לך לך אין דעם ענין פון „ויעקב הלך לדרכו” (לגבי ווי ער איז געווען פריער, אנהויבנדיק פון מוצאי יוהכ״פ)] אז די הליכה דארף זיין אין אלע כחות וענינים:\nאפילו אויב דאס וואס במשך כל הזמן (פון מוצאי יוהכ״פ און) האט ער געפועל׳ט בא זיך דעם ענין ההליכה נאר אין איין ענין אדער אין כמה ענינים\n(אבער ניט בכולם), איז עס געווען מצד דערויף וואס אלע זיינע אנדערע ענינים זיינען בתכלית השלימות (מצד מעמדו ומצבו, ווי ער שטייט אין זיין מציאות), און דעריבער האט זיך בא אים ניט געפאדערט (בנוגע צו די ענינים) דער ענין ההליכה (צו ארויסגיין פון זיך),\nפונדעסטוועגן, וויבאלד אז די הוראה „לך לך” (אז דער ענין ההליכה זאל זיין אין אלע ענינים, און ווי דער פסוק טייטשט אויס: „מארצך וממולדתך ומבית אביך”) איז צו יעדער אידן [אויך צו אזא וואס איז בדרגא נעלית ביותר, ביז אז די הוראה בפשטות איז געווען צו אברהם אבינו] — איז מובן, אז בשעת עס קומט פרשת לך לך, פאדערט זיך פון יעדער אידן דער ענין ההליכה אויך אין די ענינים וואס מצד מציאותו זיינען זיי בתכלית השלימות.\nוכמבואר בתו״א³⁷ בנוגע צו דעם וואס ר׳ חנינא בן תרדיון האט געפרעגט „מה אני לחיי העוה״ב”, און מען האט אים געענטפערט „כלום מעשה בא לידך”³⁸ — אז ער האט זיך געפירט ווי בנימין הצדיק³⁹ — אע״פ אז רחב״ת האט זיך מוסר נפש געווען אויף עסק התורה³⁸ — בכדי צו מאכן זיכער, אז זיין מס״נ אויף עסק התורה איז ניט מצד טבע, אפילו ניט מצד טבע נפשו האלקית\n(וואס דאס איז דער פירוש הפנימי בתו״א).\nוואס דאס איז אויך דער אויפטו פון „עובד אלקים” אויף „אשר לא עבדו”⁴⁰ — הגם אז אויך „אשר לא עבדו” איז",[["34","34","המשך תרס״ו ס״ע שכה ואילך."],["35","35","קהלת יב, ז. לקו״ת ר״פ האזינו."],["36","36","ראה בארוכה ד״ה מים רבים ס״ד (לעיל ע׳ 278-9)."],["37","37","יט, סע״ב ואילך. דרך חיים פא, סע״א ואילך."],["38","38","ע״ז יח, א."],["39","39","ולא כגבאי צדקה סתם (ראה ב״ב י, ע״ב ושם יא, א)."],["40","40","לשון הכתוב — מלאכי ג, יח."]]],[1300201320,"„לא עבר מימיו שום עבירה קלה וגם קיים כל המצוות כו׳”⁴¹ — אז אן „עובד אלקים” הארעוועט [ביז צו א יגיעה גדולה ביותר, כמובן אויך פון דעם וואס עבודה איז פון לשון עיבוד עורות⁴², וואס עיבוד עורות איז א גרויסע הארעוואניע] אויף משנה זיין טבע מדותיו⁴³.\nוואס דער פנימיות הפירוש בזה איז, אז ער הארעוועט צו משנה זיין אויך טבע מדותיו דנפשו האלקית [וכידוע בענין „לשנות טבע מדותיו”⁴⁴] — וואס דעריבער איז זיין הארעוואניע ביגיעה גדולה ביותר (כנ״ל), ווארום משנה זיין די טבע המדות דנפש האלקית איז א סאך שווערער ווי צו משנה זיין די טבע המדות דנפש הבהמית.\nיא. און אויך די הוראה אויף דעם ענין — האט מען פון אברהם אבינו:\nדאס וואס אברהם אבינו איז געווען בטבעו אן איש החסד — איז עס מצד דערויף וואס ער איז געווען א מרכבה צו מדת החסד דאצילות [וכדאיתא בספר הבהיר⁴⁵, אז מדת החסד דאצילות האט געזאגט „אברהם עומד ומשמש במקומי”],\nאון פונדעסטוועגן זאגט מען, אז דאס וואס אברהם אבינו האט געטאן טוב\nוחסד, איז עס געווען ניט „מצד טבעו הטוב”, נאר „בשביל שהוא רצון ה׳”⁴⁶.\nאון דאס איז ארויסגעקומען נאך מער בהדגשה נאך דעם ווי ער האט געהאט דעם ציווי „לך לך מארצך וממולדתך ומבית אביך”, צו „אוועקגיין” לשרשו — העכער פון זיין שכל ומדות (דקדושה³¹, שמצד נפשו האלקית).\nיב. וויבאלד אז בא יעדער אידן איז דא בירושה דער ענין פון יעדער איינעם פון די אבות (וואס דערפאר איז „אין⁴⁷ קורין אבות אלא לשלשה”⁴⁸), ביז יעדער איד קען זאגן „מתי יגיעו מעשיי למעשה אבותי אברהם יצחק ויעקב”⁴⁹,\nועאכו״כ אז בא יעדער אידן איז דא בירושה דער ענין פון אברהם אבינו — וואס אויף אים שטייט „אחד הי׳ אברהם”⁵⁰, „האדם הגדול בענקים”⁵¹\n[וכידוע אז די אהבה מסותרת וואס איז דא בא יעדער אידן בירושה מאבותינו⁵² (פון אלע אבות), קומט זי בעיקר פון אברהם אבינו⁵³ „שהוא השרש הראשון לנש״י והוא הרועה הראשון”⁵⁴],\nאיז דעריבער פארשטאנדיק, אז דער ציווי „לך לך” [צו פועל׳ן דעם ענין ההליכה בכל הכחות] וואס איז געזאגט געווארן צו אברהם אבינו, איז אויך א",[["41","41","<a class=\"ft-cite\" href=\"#/read/tanya/3401310020\" data-slug=\"tanya\" data-id=\"3401310020\">תניא פט״ו</a>. — ע״פ המבואר בכ״מ (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370402\" data-slug=\"torah-or\" data-id=\"3901370402\">תו״א פט, ג</a>. קיד, ד. ועוד) דיש מעלה באתכפיא לגבי אתהפכא — ה״ז גם מעלת עובד אלקים לגבי „עבד ה׳”, צדיק."],["42","42","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו״א עו, א</a>."],["43","43","ראה תניא שם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370512\" data-slug=\"torah-or\" data-id=\"3901370512\">תו״א שם. קיד, ד</a>."],["44","44","ראה „התמימים” ח״ג ע׳ סו."],["45","45","נדפס בהשמטות לזח״א רסד, רע״ב. וראה ד״ה בחודש השלישי תש״ב ס״ב (ובכ״מ). ושם (ס״ב ואילך), ע״י (בכמה ענינים) „גדלה מדת החסד דאברהם על מדת החסד דאצילות”. וראה לעיל הערה 26."],["46","46","[?] ...עת תר״ץ (סה״מ קונטרסים פד, א). וראה עד״ז קונטרס ומעין מ״א פ״ב."],["47","47","ברכות טז, ב."],["48","48","תו״א ר״פ וארא."],["49","49","תדבא״ר פכ״ה."],["50","50","יחזקאל לג, כד."],["51","51","יהושע יד, טו. ובב״ר פי״ד, ו (ובפרש״י עה״כ מ„מדרש אגדה”): זה אברהם."],["52","52","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי״ח</a>."],["53","53","להעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו״ת סוכות עח, ד</a>. שמע״צ פט, ב."],["54","54","תו״ח שמות תקלז, סע״ב."]]],[1300201321,"ציווי און נתינת כח (ווארום ציווי הקב״ה איז אויך א נתינת כח⁵⁵) צו יעדער אידן,\nאז ער זאל דורכפירן דעם „ויעקב הלך לדרכו” אין אלע זיינע כחות,\nאנהויבנדיק פון כח המעשה [כולל אויך כח הדיבור און כח המחשבה, וואס אויך ענינם איז לבוש ועשי׳], וואס המעשה הוא העיקר⁵⁶,\nאון דערנאך — אויך אין אלע עשר כחות פנימיים (שכל ומדות), און אויך אין די כחות מקיפים (רצון ותענוג).\nאון דורך דעם וואס זיין עבודה בכל הכחות והענינים שלו איז אין אן אופן פון הליכה, וואס דאן איז זיין עבודה (בכל הכחות והענינים שלו) בשלימות — בריינגט דאס אויך די המשכה מלמעלה (אז כאטש דער „לדרכו” איז אין עובדין דחול) מען זאל אים געבן שלימות בכל עניניו, און ווי עס שטייט בא יעקב׳ן\n[וואס נוסף צו דעם וואס מעשה אבות (בכלל) זיינען „סימן לבנים”⁵⁷, איז ער דאך דער „בחיר שבאבות”⁵⁸ ומטתו שלימה⁵⁹, איז די ענינים וואס ווערן דערציילט אין תורה בנוגע צו יעקב אבינו זיינען ביותר שאת „סימן לבנים”⁶⁰,\nובפרט אז ענין הנ״ל איז פארבונדן מיט „ויעקב הלך לדרכו”]\nאז אע״פ אז ער איז געווען אין חרן בא לבן׳נען, און געהאט אויך צו טאן מיט עשו׳ן, פונדעסטוועגן „ויבא\nיעקב שלם”⁶¹ — „שלום בגופו”, „שלם בממונו” און „שלם בתורתו”⁶².\nיג. מאמר ד״ה ויאמר גו׳ לך לך.\nיד. אין היינטיקער סדרה ווערט דערציילט אז (פריער) האט דער אויבערשטער געזאגט צו אברהם אבינו „לזרעך אתן את הארץ הזאת”⁶³, „אתן” לשון עתיד: אבער דערנאך — נאך דעם ווי אברהם אבינו איז געגאנגען בארץ לארכה ולרחבה⁶⁴ — האט אים דער אויבערשטער געזאגט „לזרעך נתתי את הארץ הזאת”⁶⁵, „נתתי” לשון עבר, „כבר נתתי”⁶⁶.\nאון פון דעמולט אן האבן אידן באקומען הארץ הזאת בפועל [דער אויבערשטער האט צוגעזאגט באופן כך אז דאס האט זיך שוין אפגעטאן בפועל, ווי רש״י איז מפרש בפירושו על התורה.\nאון וויבאלד אז פירוש רש״י איז פשוטו של מקרא — איז פארשטאנדיק אז ענין הנ״ל (אז פון דעמולט אן האבן אידן באקומען ארץ ישראל בפועל) איז מובן גאר בפשטות, ביז צו א פינף יאריקן קינד],\nוואס דערפאר איז בעת כיבוש יהושע האבן די בכורים גענומען פי שנים — אע״פ אז „אין הבכור נוטל פי שנים בראוי כבמוחזק”⁶⁷ — ווייל „ארץ ישראל מוחזקת היא”⁶⁸.",[["55","55","ראה במדב״ר פי״ב, ג (ובתנחומא נשא יא): איני מבקש לפי כחי אלא לפי כחן."],["56","56","אבות פ״א מי״ז."],["57","57","תנחומא לך לך ט. ב״ר פ״מ, ו."],["58","58","ב״ר פע״ו, א. שער הפסוקים להאריז״ל תולדות כז, כה. ועוד."],["59","59","ויק״ר פל״ו, ה."],["60","60","ראה בארוכה לקו״ש ח״ג ע׳ 788. חי״ד ע׳ 1051 (בהע׳ 18)."],["61","61","וישלח לג, יח."],["62","62","פרש״י שם."],["63","63","יב, ז."],["64","64","יג, יז. וראה ב״ב ק, א."],["65","65","טו, יח."],["66","66","ירושלמי חלה פ״ב ה״א. ובב״ר (והובא ברש״י) עה״פ: מאמרו של הקב״ה מעשה."],["67","67","ב״ב קיט, א. וש״נ."],["68","68","ב״ב שם."]]],[1300201322,"טו. נאך אן ענין אין דעם:\nוויבאלד אז דער „לזרעך נתתי את הארץ הזאת” איז געווען אין אן אופן פון כריתת ברית⁶⁵ — וואס אין א כריתת ברית איז ניט שייך קיין שינויים — איז פארשטאנדיק, אז אויך נאך דעם וואס „מפני חטאינו גלינו מארצנו” איז פאר־בליבן (בכל השלימות והתוקף) דער „לזרעך נתתי את הארץ הזאת”,\nוכמובן (אויך) פון דעם לשון „גלינו מארצנו ונתרחקנו מעל אדמתנו” (גופא), אז אויך לאחרי ווי „גלינו” און „נת־רחקנו” איז עס „ארצנו” און „אדמתנו” (אונזער לאנד און אונזער ערד), ביז אז דער דין איז (לכמה דעות⁶⁹), אז יעדער איד (אויך שבחוץ לארץ) האט א חלק (ד׳ אמות⁶⁹*) אין ארץ ישראל (אויך\nבשעת הגלות, ווארום „קרקע⁷⁰ אינה נגזלת”⁷¹).\nעס איז נאר אז בכדי צו ארויס־בריינגען דאס בגילוי בעיני בשר, פאדערט זיך דער „קום התהלך בארץ לארכה ולרחבה” (כדלקמן סעיף כ׳).\nטז. שוין גערעדט כמה פעמים, אז דער ענין פון כיבוש ארץ ישראל איז דא (כפשוטו און אויך) ברוחניות: נוסף צו דעם וואס יעדער איד דארף „כובש” זיין די עשר אומות שבנפשו — די ז׳ אומות וואס דאס זיינען די ז׳ מדות, און „את הקני ואת הקניזי ואת הקדמוני” וואס דאס זיינען די ג׳ מוחין⁷² — דארף ער אויך „כובש” זיין חלקו בעולם, און מאכן דערפון „ארץ ישראל” און „ארץ הקודש” — א דירה לו ית׳.\nואע״פ אז פון דעם וואס מען רופט עס אן מיטן נאמען „ארץ ישראל” ווייזט עס אז דאס רעדט זיך וועגן ענינים ארציים [ביז אז דאס איז (איידער א איד מאכט דערפון א דירה לו ית׳) „נחלת גוים”⁷²*] — איז וויבאלד אבער אז אידן זיינען „ארץ חפץ”⁷³, אז זיי זיינען כולל די צווי קצוות פון „ארץ” און „חפץ”",[["69","69","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380899\" data-slug=\"likkutei-torah\" data-id=\"4001380899\">שו״ת מהר״ם ב</a>״ר ברוך סי׳ תקלו. ס׳ השטרות לר״י ברצלוני ע׳ 43. אוצר הגאונים קידושין סי׳ קמו-קנא. ואף שהתוספות (ב״ב מד, ב ד״ה דלא) רא״ש (ב״מ פ״ד ס״ג — הובא בב״י וד״מ חו״מ סו״ס קיג) ורמב״ם (הל׳ שלוחין פ״ג ה״ז) חולקים על זה, ועד שבשו״ע — בהדינים דפרוזבול (חו״מ סי׳ סז. שו״ע אדה״ז הל׳ הלואה סל״ה. וראה דרישה שם סקכ״ד), קנין אגב קרקע (שם סו״ס קיג. וראה ב״י שם) והרשאה (שם ריש סקכ״ג) לא נזכרה דיעה זו — הרי נוסף על זה ש(כמדובר כמ״פ) המדובר בשיחות אליבא דדיעה אחת — אע״פ שאין הפס״ד כן (ע״ד הביאור בלקו״ת (נצבים מה, סע״א) בענין שופר יעל פשוט. ועוד) — הרי בנדו״ד עוד ענין ועיקר: בנוגע לפרוזבול והרשאה — כיון „שלא הוברר חלקו אא״פ לגבות מהקרקע”. משא״כ בתוכן המדובר בפנים (חוו״ד דכאו״א בנוגע לא״י) — נוגע רק שיש לו בעלות בה. 69*) כ״ה ברוב המקומות שבהערה הקודמת. ובדרישה שם: אמה. ולהעיר מהמבואר בספר פענח רזא (חיי שרה כג, טז), דת׳ שקל דאברהם — ה״ז ס׳ רבוא אמה (ע״פ החשבון דשדה חומר שעורים)."],["70","70","סוכה ל, ב. וש״נ."],["71","71","תוספות ב״ב שם. שו״ת מהר״ם שם. אוצר הגאונים שם. ואף ש„מלך אפילו נכרי שכבש איזו מדינה במלחמה קונה אותה” (הל׳ הפקר לאדה״ז ס״ג. וש״נ), הרי בעלות דנ״נ — שבאה במקום דצדקי׳ — היא כללית דכל המדינה. אבל שניהם אינם שוללים בעלות היחיד על הקרקע שלו (משא״כ „נהרות ויערים” שבהל׳ הפקר שם)."],["72","72","ראה בארוכה ד״ה אל תצר את מואב (לאדהאמ״צ) ע׳ 11 ואילך (מאמרי אדהאמ״צ דברים ח״א בתחלתו). ובכ״מ. 72*) תהלים קיא, ו. רש״י ר״פ בראשית."],["73","73","מלאכי ג, יב. *) ואולי נכלל זה ב„אינו ברשותו” שברמב״ם שם. ודוחק. — אבל להעיר מחדושי חת״ס (ירושלים תשי״ט) לב״ק ע, א (בשוה״ג). וראה כלי חמדה (להר״ד פלאצקי) פ׳ תבוא (ער, סע״ב ואילך)."]]],[1300201323,"וואס „ארץ” איז קצה הכי תחתון [ווי עס שטייט דער לשון בנוגע צו ארץ „שהכל דשים עלי׳”⁷³*, אז יעדער ענין („הכל”) שטייט העכער פון ארץ, ביז אין אן אופן „דשים עלי׳”], און „חפץ” איז קצה הכי עליון [ווארום „חפץ” איז פארבונדן מיט תענוג⁷⁴, וואס איז העכער (אפילו) פון רצון],\nאיז מצד דערויף וואס אידן (גופא) זיינען כלול פון די צוויי קצוות „ארץ” און „חפץ” (חפץ ה׳), [דאע״פ אז מצד הגוף וואס ער איז „מן התחתונים”⁷⁵ זיינען זיי „ארץ”, איז אבער מצד הנפש וואס ער איז „מן העליונים”⁷⁵ זיינען זיי „חפץ ה׳”] — האבן זיי בכח צו מאכן פון די ענינים ארציים (ביז צו „נחלת גוים”) א דירה לו ית׳⁷⁶.\nיז. נאך אן ענין אין דעם:\nס׳איז ידוע⁷⁷ פירוש הבעש״ט אויפן פסוק „כי תהיו אתם ארץ חפץ”⁷³: „אזוי ווי די גרעסטע חכמים וועלן אייביג ניט דערגיין די גרויסע טבעיות׳דיקע אוצרות, וועלכע השי״ת האט טובע געווען בארץ, אז הכל הי׳ מן העפר⁷⁸,\nאט אזוי קען קיינער ניט דערגיין די גרויסע אוצרות וואס ליגן אין אידן, וואס זיי זיינען דעם אויבערשטנס ב״ה ארץ חפץ”.\nדערפון איז פארשטאנדיק בנוגע צו די צוויי קצוות „ארץ” און „חפץ”, אז ניט נאר וואס „ארץ” וואס אין אידן איז ניט סותר צום „חפץ ה׳” וואס אין זיי, נאר אדרבה:\nכשם ווי אין ארץ כפשוטה, איז די גרעסטע טבעיות׳דיקע אוצרות האט דער אויבערשטער מטביע געווען דוקא אין ארץ (ד„הכל הי׳ מן העפר”) — אזוי אויך בנוגע צו אידן, אז דוקא מצד דעם „ארץ” (גוף) שבהם בריינגט זיך ארויס (מער) דער חפץ ה׳ וואס אין זיי. וכמבואר בכ״מ, אז דוקא דורך דעם וואס די נשמה איז יורד למטה, ווערט נמשך⁷⁹ איר שרש האמיתי ווי זי איז מושרש אין עצמות⁸⁰. ביז אז (אויך) אין דעם גוף הגשמי (ארץ) גופא, אין אים דוקא איז די בחירת העצמות⁸¹.\nאון כשם ווי דאס איז בנוגע דעם „ארץ חפץ” פון אידן גופא — עד״ז איז עס אויך בנוגע צום „ארץ חפץ” וואס אידן דארפן ממשיך זיין אלקות (חפץ ה׳) אין חלקם בעולם (ארץ) און מאכן עס א דירה לו ית׳: מצד די „גשמיות” וואס אין חלקם בעולם, געפינט זיך דערויף דער כח העצמות⁸². און די עבודה פון",[["","","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370198\" data-slug=\"torah-or\" data-id=\"3901370198\">73*) ראה ב</a>״ר פמ״א, ט: ומה עפר עשוי׳ דיי״ש. ובמ״כ שם: הכל דשים עלי׳. ובתו״א מג, סע״ד: שהיא (הארץ) מדרס תחת כפות רגלי הכל."],["74","74","לקו״ת שה״ש ד״ה לבבתני ספ״א (וש״נ). שו״ת הצ״צ אהע״ז ח״ב סי׳ רסג. ועוד. ולהעיר מאגה״ק סכ״ט (קמט, ב), שרצון זה הוא חיצוניות דתענוג."],["75","75","ב״ר פ״ח, יא. פי״ב, ח. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">תו״א ג, ד</a> ואילך. קונטרס ומעין מט״ו. המשך תרס״ו ע׳ תצה. ובכ״מ."],["76","76","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו״א שם (ד, א</a>) ובהמשך הנ״ל שם, שע״י שהנשמה נתלבשה בגוף שמבחי׳ דומם היותר תחתון מכולם, ביכלתה להעלות את כללות העולם."],["77","77","היום יום ע׳ נד. ובכ״מ (הובא בהוספות לכתר ש״ט (הוצאת קה״ת) סי׳ מד)."],["78","78","קהלת ג, כ."],["79","79","להעיר גם מהמבואר בד״ה זה היום תש״י פ״ב, שהטעם שנקרא אדם על שם האדמה — הגם שלכאורה הי׳ ראוי לקרותו ע״ש הצורה שהוא מדבר ולא ע״ש החומר שהוא אדמה — כי אדרבה, ענין זה שנפשו ירדה ונתלבשה בגוף גשמי (אדמה) מבטא מעלת נשמתו, דכל הגבוה ביותר יורד למטה ביותר. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370015\" data-slug=\"torah-or\" data-id=\"3901370015\">תו״א ד, ב</a>."],["80","80","המשך תרס״ו ע׳ תצב ואילך. ובכ״מ."],["81","81","תורת שלום ע׳ 120."],["82","82","ראה אגה״ק ס״כ (קל, ב. ושם קלב, רע״א ואילך, שזהו המעלה שביסוד העפר הגשמי)."]]],[1300201324,"אידן איז צו מגלה זיין דעם כח העצמות וואס געפינט זיך אין דעם ארץ הגשמי.\nחי. לאחרי כל זה קען מען דאך טענה׳ן: כל הנ״ל איז בהעלם, אבער דאס וואס ער זעט בגילוי, איז — א וועלט וואס הקליפות גוברים בו⁸³. דאס הייסט, אז ניט בלויז וואס ער זעט ניט ווי דורך זיין עבודה איז ער מזכך די וועלט און מאכט פון איר „ארץ ישראל”, נאר אדרבה, ער זעט גאר דעם היפך, אז דער חושך שטארקט זיך מיום ליום⁸⁴ [בדוגמת „והכנעני אז בארץ” וואס „הי׳ הולך וכובש את א״י מזרעו של שם”⁸⁵]. טא ווי קען עס זיין אז ער וועט כובש זיין די וועלט און מאכן פון איר ארץ ישראל?\nאויף דעם איז די הוראה: אז בשעת א איד ווערט ניט נתפעל פון „והכנעני אז בארץ”, און גייט ארויס אין וועלט על מנת לכובשה,\nאון טוט עס (ניט ח״ו מיטן הרגש פון „כוחי ועוצם ידי גו׳”⁸⁶, נאר) אלס שלוחו של הקב״ה, און נאכמער אלס עבדו⁸⁷, וואס דער אויבערשטער האט אים אנגעזאגט „קום התהלך בארץ לארכה ולרחבה”, צוזאמען מיט דער הבטחה „כי לך אתננה”\nאיז בשעת ער הויבט אן מקיים זיין דעם ציווי — ווערט עס און ער דערזעט עס אז ס׳איז „לזרעך נתתי — כבר נתתי”,\nעס ווערן בטל די העלמות והסתרים, און נאך מער — זיי ווערן און זיינען\nמסייע. ווי גערעדט⁸⁸ בפירוש גם אויביו ישלים אתו⁸⁹ („ישלים” אויך מלשון שלימות), ניט נאר וואס זיי שטערן ניט, נאר זיי גיבן נאך צו שלימות.\nיט. ס׳איז דאך אין ענין יוצא מידי פשוטו — איז כל הנ״ל אויך בנוגע צו ארץ ישראל כפשוטה: טראץ דעם וואס עס דוכט זיך אויס אז ס׳זיינען דא אזוינע פון אומות העולם וואס זיינען מערער אויף געווייסע חלקים פון ארץ ישראל, ביז אז זיי טענה׳ן „לסטים אתם”⁹⁰ — דארף מען ניט רעכענען זיך דערמיט,\nווארום וויבאלד אז דער אויבערשטער אליין זאגט „לזרעך נתתי את הארץ הזאת”, איז „כהמס דונג מפני אש גו׳ מפני אלקים”⁹¹.\nאון נאך מער: דאס וואס עס זיינען דא אזעלכע וואס זיינען מערער כו׳ — איז עס נאר זמנית און למראית עין, אבער בפנימיות ובאמיתית ווייסן אויך זיי⁹¹* [און ווי רש״י האט שוין מודיע געווען אז אידן „אומרים להם” (צו אלע או״ה), אז דאס וואס „ברצונו נתנה להם” (לפי שעה) איז בכדי אז דערנאך זאל זיין „ברצונו נטלה מהם ונתנה לנו”⁹⁰] אז גאנץ ארץ ישראל לגבולותי׳ געהערט צו אידן.\nכ. ובכדי ארויסבריינגען דאס בגילוי, פאדערט זיך דער „קום התהלך בארץ לארכה ולרחבה” — באזעצן אלע שטחים פון ארץ ישראל ובפרט — אין",[["83","83","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ״ו (יו״ד, סע״ב</a>)."],["84","84","ראה סוטה מט, א."],["85","85","פרשתנו יב, ו. פרש״י שם."],["86","86","עקב ח, יז."],["87","87","ראה לעיל סעיף ה׳ המעלה דעבד על שליח."],["88","88","לעיל ע׳ 291-2."],["89","89","משלי טז, ז."],["90","90","פרש״י ר״פ בראשית."],["91","91","תהלים סח, ג. 91*) להעיר ממרדכי (מגילה ג, א. וש״נ) דאע״ג דאינהו לא חזו כיון דמזלייהו חזו — נופלת עליהם חרדה גדולה כו׳."]]],[1300201325,"די שטחים וועלכע עס זיינען דא מערערים אויף זיי,\nאון אז די התיישבות זאל זיין אין אן אופן אזוי ווי ס׳איז געווען בא אברהם אבינו (וואס מעשה אבות סימן לבנים⁵⁷), אז קומענדיק און גייענדיק (התהלך) אין ארץ ישראל איז „ויבן שם מזבח לה׳ גו׳”⁹²: אין די אלע ערטער זאל מען בויען א מקום תורה און א מקום תפלה⁹³, און אויך א מקוה טהרה.\nאון דורך דעם וועט זיין דער „התהלך בארץ לארכה ולרחבה” — וועט מען זעהן בגילוי בעיני בשר, אז „לזרעך נתתי את הארץ הזאת”, און אז אויך די אומות העולם אנערקענען דאס,\nאון אפילו אויב לשעה קלה וועט זיין דער „רגשו גוים ולאומים יהגו”⁹⁴ — איז דער אמת איז אז זיי אליין ווייסן אז דאס איז (כסיום הכתוב) „ריק”⁹⁴, און דאס וואס „רגשו” און „יהגו” איז עס בלויז מצד דעם וואס זיי ווילן יוצא זיין פאר אימעצען.\nנאר בכדי מען זאל זעהן בגילוי אז אויך די אומות העולם ווייסן אז (דער „רגשו” און „יהגו”) איז „ריק” — דארפן אידן ווייזן⁹⁴* אז דאס וואס זיי זאגן אז\nגאנץ ארץ ישראל געהערט צו זיי, מיינען זיי דאס מיט אן אמת\nאון פשיטא ניט איינלאדן, ח״ו, א לחץ פון די אומות, דורך דער הנהגה מוזרה צו באזעצן זיך נאר אין געציילטע עטלעכע נקודות,\nוואס דורך דער הנהגה ווייזט מען אז מען רעכנט זיך מיט דער הנהגה פון די מערערים\nאון ס׳איז ניטא קיין סברא בשכל ובמציאות צו מחלק זיין די עטלעכע נקודות פון אלע איבעריקע — ווארום דער „רגשו” און „יהגו” איז פונקט דער זעלבער באם באזעצן עטלעכע נקודות און באם באזעצן כל אורך הגבול וכל השטחים.\nבשעת מען וועט גיין מיטן אמת — וועט מען ניט האבן אין דעם קיין שוועריקייטן, וויבאלד אז „לזרעך נתתי את הארץ הזאת”, „כבר נתתי”.\nכא. מען זאל נאר ניט מכריז זיין כ״ז בקול רם, די התיישבות אין די שטחים זאל זיין אן רעש והמולה, עס איז נוגע די מעשה ההתיישבות בפועל. בנוגע צו למעלה אז אידן האבן מחליט געווען ווי עס דארף זיין — איז דאך כלפי שמיא גליא, און בנוגע צו למטה — איז המעשה הוא העיקר.\nאון דעריבער דארף ניט זיין דער רעש שבזה, ועאכו״כ ניט די התפארות אז „כוחי ועוצם ידי עשה לי את החיל הזה”⁸⁶, ואדרבה: די התפארות אז „כוחי ועוצם ידי גו׳” קען ח״ו קאליע מאכן. נוסף וואס דאס איז ניט אמת.\nמען דארף וויסן אז מען טוט עס בשליחותו ובכחו של הקב״ה, וואס דורך",[["","","(מנחות מג, ב) — אלא שבירושלמי שם הוא שב״נ יזהרו מהמצות (תפילין וציצית) שקיבלו עליהם."],["92","92","יב, ז-ח."],["93","93","ראה מגילה כז, א."],["94","94","תהלים ב, א. 94*) ובפרט, שהקס״ד שלהם בזה [ד„רגשו” ו„יהגו”] הוא (כהמשך הכתובים בתהלים שם) „יתייצבו גו׳ על ה׳ ועל משיחו” (לנתק את בנ״י מה׳ —) „ננתקה את מוסרותימו — אלו תפילין של יד ונשליכה ממנו עבותימו — אלו תפילין של ראש”*, שמצות תפילין היא מצוה כללית (קדושין לה, א) — הרי בודאי שצריך להיות בתוקף, שלא להתפעל מזה. *) מדרש תהלים עה״פ (ב, ג). בירושלמי ע״ז פ״ב ה״א: „זו מצות תפילין זו מצות ציצית” — וגם מצות ציצית היא מצוה כללית"]]],[1300201326,"דעם קומט צו תוקף יותר אין דער מעשה ההתיישבות. ולגבי כחו של הקב״ה איז ניט שייך קיין מניעות ח״ו.\nכב. בשעת מען וועט גיין מיט דעם וועג, איז ניט נאר אז זיי וועלן סוף סוף ניט מערער זיין [ועאכו״כ אז עס וועט ניט קאסטן ח״ו קיינע קרבנות, אפילו ניט א נפש אחת מישראל (וואס א נפש אחת איז א עולם מלא⁹⁵), און אפילו ניט פארוואונדעט ווערן ח״ו, אין אופן פון „קטלא פלגא”⁹⁶],\nנאר אדרבה: דאס וועט בריינגען דעם „הללו את ה׳ כל גוים שבחוהו כל האומים, כי גבר עלינו חסדו גו׳”⁹⁷\n[ובפרט אז מען קומט איצט פון חג הסוכות⁹⁸, וואס זיבען טעג נאכאנאנד (שבעת ימי ההיקף, וואס זיינען כולל כל משך הזמן⁹⁹), און אויך גלייך דערנאך בהמשך — בשמיני (שומר ההיקף) עצרת ושמח״ת, האט מען געזאגט הלל גמור],\nאז אויך די „גוים” און „אומים” וועלן זאגן און לויבן בגילוי לעין כל, אז „גבר עלינו חסדו”, אז דער חסד ה׳ האט זיך געשטארקט „עלינו” — אויף אלע אידן שבכל מרחבי תבל, ובפרט אויף די אידן וואס געפינען זיך אין ארץ אשר גו׳ עיני ה״א בה מרשית השנה ועד אחרית שנה¹⁰⁰,\nזיי וועלן מסייע זיין אידן (ניט נאר דאס וואס זיי האבן שוין מבטיח געווען, נאר) כל הסיוע (בממון וכיו״ב) וואס\nאידן דארפן דערווייל אנקומען צו זיי, מצד דערויף וואס מען געפינט זיך אין גלות.\nכג. ווארום, כמדובר כמ״פ¹⁰¹, מען געפינט זיך נאך אין גלות, ס׳איז נאך פאר דער אתחלתא דגאולה.\nוכדמוכח פון דעם גופא וואס (למרבה הפלא ותמי׳ גדולה ביותר, מהולה בצער גדול) אז ביז איצטער האט מען זיך ניט באזעצט אין אלע שטחים פון ארץ ישראל — אע״פ אז אזא הנהגה איז היפך השכל הישר, ווארום (כנ״ל סעיף כ׳) דערמיט איז מען נאר מזמין א לחץ תמידי.\nמען שרעקט זיך פאר א קול עלה נדף. דער קול עלה נדף קומט דאך פון אן אינו יהודי, איז מצד דעם חושך כפול ומכופל פון גלות איז דא אזוינע וואס פאלן בא זיך אראפ פאר דעם אינו יהודי (כאטש אז בשכל הבריא, ווייס מען אז ס׳איז בלויז א קול עלה נדף).\nדאס איז א חושך כפול ומכופל אין דעם חושך הגלות גופא. דער גלות מצד עצמו איז — כידוע¹⁰² — נאר „די גופים זיינען געגאנגען אין גלות”, ניט די נשמות. און עס קומען א מתי מספר פון אידן, און שלעפן אריין אויך די נשמה און גלות, אז אויך זי (די נשמה) זאל זיין נכנע פאר א אינו יהודי.\nדאס וואס איז געווען ביז איצטער — איז אין צועקין על העבר. אבער מכאן ולהבא איז יהי רצון אז יערה עליהם רוח ממרום, אויך אויף די מתי מספר הנ״ל, אז זיי זאלן (ניט נאר מבלבל זיין, נאר זיי זאלן) מסייע זיין אז אידן זאלן זיך באזעצן אין אלע שטחים פון ארץ",[["95","95","סנהדרין לז, א במשנה."],["96","96","לשון הגמרא ב״ק סה, א."],["97","97","תהלים קיז."],["98","98","וראה ד״ה בסוכות תשבו תשל״ו (סה״מ — מלוקט ח״א ע׳ קעה) סוס״ח (ובהנסמן שם), השייכות ד„הללו את ה׳ כל גוים” לחגה״ס."],["99","99","ראה לעיל ע׳ 281-2 ובהנסמן שם."],["100","100","עקב יא, יב."],["101","101","וראה גם לעיל ע׳ 272-3."],["102","102","לקו״ד ח״ד תרצב, א."]]],[1300201327,"ישראל, און אז מען זאל דאס ניט אפלייגן נאר טאן דאס תיכף ומיד, בשעתא חדא וביומא חדא ממש (שזה דוקא יגדיל ההצלחה).\nאון דוקא דאס איז די וועג צו „ונתתי שלום בארץ ושכבתם ואין מחריד גו׳”¹⁰³ און כל הברכות המנויות בפרשת בחוקותי, ביז צו „ואולך אתכם קומ־מיות”¹⁰⁴,\nאז נאך זייענדיק אין די לעצטע טעג פון גלות, וועט דער אויבערשטער פירן און מאכן גיין יעדער אידן [סיי די אידן שבחו״ל, סיי די אידן שבאה״ק ת״ו] „קוממיות” — „בקומה זקופה”¹⁰⁵,\nאון דאס וועט זיין א הכנה צום „קץ שם לחושך”¹⁰⁶, אז דער אויבערשטער וועט מאכן א סוף צום חושך הגלות\n[דורך דעם וואס אידן וועלן (מאכן ליכטיג דורך) בויען בכל השטחים א מקום תורה און מקום תפלה, וואס ווערן אנגערופן „בית גדול”⁹³ וועלכער קומט בהמשך צו „בית המלך”¹⁰⁷, דוד מלכא משיחא\nאון דורך דעם וואס מען וועט בויען בכל השטחים א מקוה טהרה, וואס דאס איז א הכנה צו („מקוה ישראל ה׳”¹⁰⁸ און) „וזרקתי עליכם מים טהורים גו׳”¹⁰⁹],\nביז אז דער חושך גופא וועט נהפך ווערן לאור, ולילה כיום יאיר¹¹⁰,\nאז בקרוב ממש וועט קומען משיח צדקנו און יבנה מקדש במקומו און (דערנאך) יקבץ נדחי ישראל¹¹¹, ביז אז „יתקן את העולם כולו לעבוד את ה׳ ביחד שנאמר¹¹² כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה׳ ולעבדו¹¹³ שכם אחד”¹¹¹,\nעס וועט זיין „והיו מלכים אומניך ושרותיהם מניקותיך”¹¹⁴, און „והיתה לה׳ המלוכה”¹¹⁵.\nכד. וואס דאס האט אויך א קשר מיוחד מיט מוצאי שבת קודש, ווארום במוצש״ק פראווענט מען דאך סעודת מלוה מלכא, וואס זי ווערט אויך אנגערופן (און איז) „סעודתא דדוד מלכא משיחא”¹¹⁶\nאון מען זאגט דעמולט (אדער מען רעדט אין דעם ענין) „אל¹² תירא עבדי יעקב”¹¹⁷ — אז ס׳איז ניטא וואס צו מורא האבן, ווארום דער אויבערשטער גייט מיט יעדער אידן, זיי גייען צוזאמען, נאך זיינדיק אין די לעצטע טעג פון גלות\nאון דערנאך נעמט דער אויבערשטער יעדער אידן (ניט קוקנדיק אויף זיין מעמד ומצב) און פירט אים ארויס פון גלות (ווי רש״י איז עס מבאר¹¹⁸ בפשטות, אויך פאר א קליין קינד),\nבקרוב ממש און בעגלא דידן.",[["103","103","בחוקותי כו, ו."],["104","104","שם, יג."],["105","105","פרש״י בחוקותי שם (מתו״כ)."],["106","106","איוב כח, ג."],["107","107","מ״ב כה, ט."],["108","108","ירמי׳ יז, יג. משנה סוף יומא."],["109","109","יחזקאל לו, כה. יומא שם. וראה ד״ה ארע״ק אשריכם (אוה״ת יוהכ״פ ע׳ א׳תקעו ואילך). סיום דמס׳ יומא (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171176\" data-slug=\"likkutei-sichot\" data-id=\"1300171176\">לקו״ש חי״ז ע׳ 176</a> ואילך)."],["110","110","תהלים קלט, יב."],["111","111","רמב״ם הל׳ מלכים ספי״א."],["112","112","צפני׳ ג, ט."],["113","113","לעיל ע׳ 259 הערה 36."],["114","114","ישעי׳ מט, כג."],["115","115","עובדי׳ א, כא."],["116","116","סידור האריז״ל (להר״ש מרשקוב). פע״ח סוף שער השבת."],["117","117","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו״ת בלק עב, ב</a>. וראה לעיל ע׳ 264 הערה 24, שבחב״ד אין נוהגים לומר „אל תירא גו׳”."],["118","118","נצבים ל, ג."]]],[1300201328,"בס״ד. מוצאי ש״פ חיי שרה, מבה״ח כסלו - בחדרו - ה׳תשל״ח\nואברהם זקן בא בימים גר׳<sup data-n=\"1\">1</sup>, ומביא רבינו הזקן בתו״א בפרשתנו ד״ה<sup data-n=\"2\">2</sup> להבין ענין\nמשארז״ל<sup data-n=\"3\">3</sup> יפה שעה אחת בתשובה ומע״ט בעוה״ז מכל חיי עוה״ב (ולפני הדרוש - שהוא „שייך לפסוק ואברהם זקן בא בימים\") אמר הזהר<sup data-n=\"4\">4</sup> עה״פ באינון יומין עילאין כו׳, שהם הלבושים דתומ״צ<sup data-n=\"5\">5</sup>.(תשובה ומעשים טובים) שעל ידם תוכל הנשמה ליהנות מזיו השכינה בעוה״ב. וענין זה שייך גם לימים כפשוטם<sup data-n=\"6\">6</sup>, שצריכים להיות כל הימים שלמים, היינו שכל יום יהי׳ מלא בעשיית מצוה (יומין עילאין). וידוע מאמר הבעש״ט<sup data-n=\"7\">7</sup> „לא יניח שום יום מעשיית מצוה כו׳\". וזהו בא בימים, שאברהם אבינו עבד את עבודתו בכל יום ויום<sup data-n=\"8\">8</sup>, שכל ימיו היו יומין שלימין (ולא חסרין ח״ו), ועי״ז „בא בימים — באינון יומין עילאין\"<sup data-n=\"9\">9</sup>. וידוע הדיוק בזה<sup data-n=\"10\">10</sup>, הרי העיקר הוא לבושי המצוות (יומין עילאין), ומה נוגע בזה ענין הימים (כפשוטם) שלא יניח שום יום מעשיית מצוה כו׳, הלא יוכל לעשות למחר שתי מצוות. דלכאורה גם כשעושה כמה מצוות במשך יום אחד יש לו אותו מספר המצוות כמו כשהי׳ מקיימם במשך כמה ימים<sup data-n=\"11\">11</sup>, וא״כ, מה נוגע שיקיים מצוה בכל יום דוקא, ועד שכאשר חסר לו יום אחד חסר לו לבוש<sup data-n=\"12\">12</sup>.",[["1","1","פרשתנו כד, א."],["2","2","טז, א. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">תו״א משפטים עו, ג</a>. עס, ב."],["3","3","אבות פ״ד מי״ז."],["4","4","ראה זח״א רכד, א. וראה שם קכט, א הלשון „יומין עילאין\"."],["5","5","באגה״ק ובתו״א מקץ שבהערה 17 [וכן בתו״א ח״ש שם (בתחילת הענין)] שהמצוות הם לבושים. אבל בתו״א משפטים עס, ב (וראה גם תו״א ח״ש שם בהמשך הענין — נעתק לקמן ס״ג): לבושי התורה והמצוות — בפרטיות יותר. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא ספ״ה</a>. אוה״ת משפטים ע׳ א׳רסו."],["6","6","כ״ה בתו״א משפטים שם."],["7","7","צוואת הריב״ש בתחלתה."],["8","8","ראה זח״א קכט, א: ולא אתקריב אברהם ביומא חדא או בזמנא חדא אלא עובדוי קריבו לי׳ בכל יומוי כו׳."],["9","9","לשון הזהר שם."],["10","10","אוה״ת שבועות ע׳ צא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830262\" data-slug=\"or-hatorah-hb\" data-id=\"8158830262\">בלק ע׳ תתקמח</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010084\" data-slug=\"or-hatorah-hb\" data-id=\"8159010084\">פינחס ע׳ א׳קצט</a>. וראה גם אוה״ת לתהלים ע׳ תקכז."],["11","11","באוה״ת וארא ע׳ קכ: „וצריך לסגל תורה ומצוות ואפילו מצוה אחת כמה פעמים במספר הימים אשר נתנו לו מן השמים כפי שיעור הלבושים הצריכים לפי שרש נשמתו .. כי מאחר שיש לו פנאי כו׳\". והשאלה שבפנים (ממקומות שבהערה הקודמת) „הלא יוכל לעשות למחר שתי מצוות\" — כי מהלשון „יומין שלימין\" מוכח דמה שצריך לעשות מצוה בכל יום (כתורת הבעש״ט המובאה בפנים) הוא גם כשאין לו פנאי לעשות יותר מב׳ מצוות, שאין נפק״מ במספר המצוות."],["12","12","„ודוחק לומר דמיירי בביטול מ״ע התלויות בו ביום כמו ק״ש כו׳, (ועוד?) דא״כ מלבד מה שחסר הלבוש הרי פגם ג״כ בביטול המצוה וצריך תשובה\" (אוה״ת בלק שם)."]]],[1300201329,"ב) והנה מזה שמעלה זו דאברהם (בא בימים) בא בקרא לאחרי כו״כ מעלות שלו שבפסוקים שלפנ״ז, ועד שבכתוב זה גופא בתחילה הוא אומר ואברהם זקן ואח״כ מוסיף בא בימים, מובן שענין בא בימים הוא מעלה גדולה יותר גם מהמעלה דזקן. דהגם שואברהם זקן פי׳ שהי׳ בעילוי נפלא ביותר, וכמרז״ל<sup data-n=\"13\">13</sup> שאמר לו הקב״ה לאברהם בא לבוש לבושי (דהקב״ה שנקרא<sup data-n=\"14\">14</sup> עתיק יומין<sup data-n=\"15\">15</sup> שנאמר ואברהם זקן, היינו שואברהם זקן היא מעלת אברהם מה שלובש לבוש הקב״ה כמו שהקב״ה הוא בבחי׳ עתיק יומין, הנה בא בימים נעלה עוד יותר. וצריך להבין מהו גודל העילוי דבא בימים, לבושי המצוות [ובפרט בהענין דעשיית מצוה בכל יום דוקא, הגם שאינו מתוסף עי״ז במספר המצוות], ועד שזה נעלה יותר מענין (ואברהם) זקן שהוא בחי׳ (הלבוש ד)עתיק יומין<sup data-n=\"16\">16</sup>.\nג) ויובן זה בהקדים ביאור הידוע<sup data-n=\"17\">17</sup> בזה שהנשמה צריכה להלבושים דתורה ומצוות בכדי שתוכל ליהנות מזיו השכינה, כי להיות שהנשמה היא נברא [וכמבואר בכ״מ שהנשמה היא כמו שאלקות נעשה בבחי׳ נברא<sup data-n=\"18\">18</sup>, ועד שהדביקות שלה באלקות היא דביקות בלתי ניכרת<sup data-n=\"19\">19</sup>] ואי״א לנברא להשיג שום השגה באוא״ס ב״ה, לכן בכדי שתוכל הנשמה ליהנות מזיו השכינה שהוא הארה מאוא״ס ב״ה [ובפרט לחזות בנועם הוי׳<sup data-n=\"20\">20</sup>], צריכה היא ללבושים. וכמשל אור גדול [ביותר, וכמו אור השמש, בחי׳ שמש הוי׳] שאין יכולים להביט בו, ועי״ז המסך (שהוא כמו לבוש) יכולים לקבל [ולקלוט] את האור.\nוהנה ידוע<sup data-n=\"21\">21</sup> שכל ממוצע המחבר ב׳ דברים, צ״ל כלול משניהם. ומזה מובן גם בענין הלבושים דתומ״צ [שהם כמו ממוצע המחבר בחי׳ זיו",[["13","13","ב״ר ספנ״ח."],["14","14","דניאל ז, ט."],["15","15","מ״כ לב״ר שם (הובא באוה״ת פרשתנו תשעט, א). וראה גם פרש״י לב״ר שם. ובהגהות הרד״ל שם מביא מילקוט „דכתיב עתיק יומין יתיב\"."],["16","16","ובפרט לפי מ״ש ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו״א לג, ב</a>, שעתיק יומין הוא „נעתק ונבדל מבחי׳ היומין שהם הלבושים הנעשים מהמצוות\"."],["17","17","ראה בכ״ז אגה״ק סכ״ט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו״א מקץ לב, ד</a> ואילך. וראה גם תו״א פרשתנו שבהערה 2."],["18","18","ראה ביאוה״ז לאדהאמ״צ (קטו, ב) ולהצ״צ (ע׳ תקמח). המשך תרס״ו ע׳ תנט. ס״ע תע."],["19","19","דנוסף לזה שהכלים דאצילות (שרש הנשמות) הם בדביקות בלתי ניכרת, הנה גם הדביקות דנשמות בהכלים היא בלתי ניכרת (ראה המשך תער״ב ח״א ריש ע׳ קע)."],["20","20","אגה״ק שם."],["21","21","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו״ת שה״ש ח, א</a>. המשך תער״ב ח״א ע׳ שצו. סה״מ ה׳ש״ת ד״ה עוטה אור כשלמה. ובכ״מ."]]],[1300201330,"השכינה (שהוא הארה מאוא״ס הבל״ג) עם הנשמה (שהיא נברא ובע״ג)], שיש בהם מב׳ הענינים. דשרשם (של התומ״צ) הוא מרצה״ע וחכמתו ית׳ שהם מיוחדים בו ית׳ (שהוא<sup data-n=\"22\">22</sup> וחכמתו ורצונו אחד) — ענין הבל״ג [ועד שרצה״ע וחכמתו ית׳ (שרש התומ״צ) הם למעלה גם מבחי׳ זיו השכינה<sup data-n=\"23\">23</sup>], ועי״ד שירדו למטה בעוה״ז הגשמי ציצית בצמר גשמי ותפילין בקלף גשמי וכן בכל המצוות [ועד״ז הוא גם בתורה שנתלבשה בשכל אנושי, ועד בטענות של שקר, ונתלבשה בדיו על הספר<sup data-n=\"24\">24</sup> הם בבחי׳ מדידה והגבלה ועד להמדידה והגבלה דעוה״ז הגשמי שאין תחתון למטה ממנו<sup data-n=\"25\">25</sup>, הנה ע״י ב׳ ענינים אלו שבתומ״צ [ענין הבל״ג שבהם מצד שרשם, וענין הגבול שבהם מצד ירידתן למטה] הם נעשים לבוש וממוצע המחבר את הנשמה שהיא נברא ובע״ג (וכמו שהיא מלובשת בגוף גשמי) עם בחי׳ זיו השכינה ועד עם בחי׳ נועם הוי׳ שלמעלה מכל מדידה והגבלה<sup data-n=\"26\">26</sup>.\nד) והנה מצד ההתלבשות דתומ״צ בעניני עוה״ז הגשמי שהוא רובו ככולו רע<sup data-n=\"27\">27</sup>, צריך לנקותן מכל פסולת הנופל בהן<sup data-n=\"28\">28</sup>, וכמו בלימוד התורה, שמצד זה שהתורה נתלבשה בשכל אנושי ובענינים גשמיים הרי אפשר<sup data-n=\"29\">29</sup> שהלימוד שלו יהי׳ שלא לשמה ועד לדרגא הכי תחתונה בשלא לשמה, ועד״ז במצוות<sup data-n=\"30\">30</sup>. וזהו מה שהלבושים דתומ״צ צריכים לרחיצה וכיבוס, שיהי׳ לבושים נקיים וכו׳ (ואפילו לא יהיו באופן דמלבושי אגאלתי<sup data-n=\"31\">31</sup>, בדוגמת לבוש הגשמי שבכדי שיהי׳ זך ונקי צריך לרחוץ ולכבס אותו<sup data-n=\"28\">28</sup>. [וגם לאחרי שהאדם מכבס את הלבושים דתומ״צ שיהיו נקיים מכל פסולת כו׳, בכדי",[["22","22","שעהיוה״א פ״ח."],["23","23","תו״א טז, ס״א. וראה הגהות הצ״צ לשם (אוה״ת פרשתנו תשפו, סע״ב)."],["24","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ״ד</a>. וזהו „התלבשות\" יותר מזה שמתלבשת בטענות של שקר, כי ההתלבשות דתורה בטענות של שקר היא רק מה שהתורה דנה בזה, ולשון התלבשות הוא רק המושאל בלבד\" (ד״ה ויאמר משה תש״ד ס״ב); משא״כ בהתלבשותה „בדיו על הספר עשרים וארבעה ספרים שבתורה נביאים וכתובים\", הרי בחושב״כ נוגע דיני הדיו והקלף."],["25","25","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>."],["26","26","בכל הבא לעיל — ראה תו״א (פרשתנו וס׳ מקץ) שבהערה 17."],["27","27","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ״ז (יא, ב</a>)."],["28","28","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו״א עו, א</a>."],["29","29","ראה קונטרס עה״ח פי״א."],["30","30","ראה אוה״ת לתהלים שם, שענין כיבוס הלבושים הוא „דאל״כ י״ל הם מטונפים שיש מצוה שלא לשמה\"."],["31","31","ישעי׳ סג, ג. אוה״ת לתהלים שם."]]],[1300201331,"שיעלו למעלה, צריכים הם להזדכך ע״י המלאכים, דגפיף להון ונשיק להון<sup data-n=\"32\">32</sup>. והענין הוא דהנה כתיב<sup data-n=\"33\">33</sup> אין צדיק בארץ אשר יעשה טוב ולא יחטא, שמפני שהאדם נמצא בארץ בעוה״ז הגשמי לכן יש בו חטא, חטא מל׳ חסרון<sup data-n=\"34\">34</sup> (עכ״פ). והגם שהחטא (החסרון) הוא לא באשמתו ח״ו, שהרי ועמך כולם צדיקים<sup data-n=\"35\">35</sup>, כי אם כמ״ש<sup data-n=\"36\">36</sup> נורא עלילה על בני אדם שרצון הקב״ה הוא שבנ״א נמצא בעולם כזה [ובדוגמת<sup data-n=\"37\">37</sup> מלך ששלח את בנו למדינה רחוקה בכדי להראות את חכמת בנו שגם במדינה הרחוקה יכיר את האמת, בחי׳ ואמת הוי׳ לעולם<sup data-n=\"38\">38</sup>], אעפ״כ, מכיון שבפועל יש בו (חטא מל׳) חסרון, וגם התומ״צ שלו אינם בשלימות, וכמ״ש אין צדיק בארץ אשר יעשה טוב ולא יחטא, שהחסרון (יחטא) הוא גם בהתומ״צ (ביעשה טוב) שלו, לכן בכדי שהתומ״צ שלו יעלו למעלה, צריך הוא לסיוע המלאכים].\nה) והנה זה מה שהתומ״צ שבעוה״ז הגשמי צריכים וזקוקים לסיוע המלאכים הוא לא רק מפני שעוה״ז הגשמי הוא רובו ככולו רע, אלא (גם<sup data-n=\"39\">39</sup> מצד הגשמיות דעוה״ז<sup data-n=\"40\">40</sup>. שלהיותו גשמי הוא באין ערוך לעולמות העליונים (הרוחניים). ועד״ד הידוע בנוגע לנשמת האדם, שאפילו צדיק גמור כשעולה לג״ע צריך טבילה בנהר דינור בכדי לשכוח על חיזו דהאי עלמא, כי מצד האי״ע דעוה״ז הגשמי לג״ע הרי אפילו מקצת מעניני עוה״ז מונע מלעלות לג״ע<sup data-n=\"41\">41</sup> [ובדוגמת העליות שבדרגות דג״ע שמגעה״ת לג״עה״ע וכו׳, שמכיון שהעליות הם באין ערוך, צריך להיות תחילה ביטול ההשגה דגעה״ת<sup data-n=\"41\">41</sup>]. וכידוע המשל מענין השגת השכל, שבכדי לבוא להשגה עליונה שבאין ערוך להשגה הקודמת (אע״פ שגם השגה העליונה היא בעוה״ז הגשמי) צריך",[["32","32","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">ראה זח״א כג, ב</a>. ח״ב רא, ב. תו״א מג, סע״א ואילך. סידור רעג, ב."],["33","33","קהלת ז, כ."],["34","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו״ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>. ד״ה על כן יאמרו המושלים תרצ״א בתחלתו. ובכ״מ."],["35","35","ישעי׳ ס, כא."],["36","36","תהלים סו, ה. תנחומא וישב ד. וראה תו״ח תולדות יג, א ואילך."],["37","37","ראה המשך תרס״ו ס״ע שפ ואילך."],["38","38","תהלים קיז, ב."],["39","39","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">תניא פ״מ (נד, ב</a>), שעוה״ז הוא עולם השפל בב׳ בחינות: (א) ש„ההארה שבו מצומצמת מאד עד קצה האחרון ולכן הוא חומרי וגשמי\". (ב) שהארה זו גופא „בלבושים ומסכים רבים כו׳\"."],["40","40","ועד״ד המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא שם</a> בנוגע ל„אותיות הקדושות של דברי תורה ותפלה\", ש„מאחר שהקול והדיבור הוא גשמי\" — העלאתן למעלה היא דוקא ע״י הכוונה המתלבשת בהם — אף ששתיהן (האותיות והכוונה) שוות בזה שאינן בבחי׳ הסתר."],["41","41","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370145\" data-slug=\"torah-or\" data-id=\"3901370145\">תו״א לא, סע״א</a>. המשך תרס״ו ע׳ טו. ובכ״מ."]]],[1300201332,"להיות תחילה ביטול השגה הקודמת. וכמו ר״ז כי סליק לארעא דישראל יתיב<sup data-n=\"42\">42</sup> מאה תעניתא (או מ׳ תעניות<sup data-n=\"43\">43</sup> לשכוח תלמוד בבלי בכדי שיוכל ללמוד תלמוד ירושלמי<sup data-n=\"44\">44</sup>], עד״ז הוא גם בנוגע להתומ״צ של האדם, שמצד היותן מלובשות בענינים גשמיים, צ״ל תחלה שיזדככו ויתפשטו מגשמיותן ע״י המלאכים.\nו) וי״ל בדרך אפשר דהגם שהזדככות התומ״צ והעלאתן למעלה נעשה ע״י המלאכים, מ״מ, מכיון שתכלית השלימות דכל ענין הוא כאשר הוא נעשה ע״י עבודת האדם (ולכן אדם רוצה בקב שלו דוקא<sup data-n=\"45\">45</sup>, לכן גם ענין הזדככות התומ״צ, ההתחלה בזה הוא ע״י עבודת האדם. וזהו מה שאיתא בתו״א 46 שכיבוס וזיכוך התומ״צ הוא ע״י עבודת התפלה, שהכוונה בזה היא (לא רק שע״י התפלה הוא מנקה את התומ״צ מכל פסולת, שלא יהיו באופן דשלא לשמה וכיו״ב, כי אם), שע״י התפלה נעשה גם (התחלת<sup data-n=\"47\">47</sup> ה)זיכוך שלהם, מה שמזדככות מגשמיותן ועולות למעלה. דהנה תפלה היא סולם מוצב ארצה וראשו מגיע השמימה<sup data-n=\"48\">48</sup>, היינו שהתפלה היא מקשרת את ב׳ הקצוות דארץ ושמים (מטה ומעלה<sup data-n=\"49\">49</sup>, ובפרט ע״פ הידוע<sup data-n=\"50\">50</sup> שארצה (בתוס׳ ה׳) הוא מדריגה היותר תחתונה שבארץ הלזו הגשמית גופא, ושמימה (בתוס׳ ה׳) הוא מדריגה היותר נעלית שבשמים (שמי השמים), והשמימה (בתוס׳ ה׳ גם בתחילה) הוא למעלה גם משמימה. וזהו סולם מוצב ארצה וראשו מגיע השמימה, שע״י התפלה „יכול להיות עליית גם (האדם) הנמצא ארצה במדריגות היותר תחתונות שבארץ הלזו הגשמית להשמימה להמדריגות היותר נעלות ונפלאות\"<sup data-n=\"51\">51</sup>. הנה כמו שהתפלה פועלת בהאדם, שגם כשהוא נמצא ארצה יכול הוא להתעלות להשמימה (אלא שצ״ל גם סיוע המלאכים",[["42","42","ב״מ פה, א."],["43","43","גירסת הרש״ל שם, ועוד — ראה דק״ס שם."],["44","44","המשך תרס״ו שם. המשך תער״ב ח״ב ע׳ א׳נ ואילך."],["45","45","ב״מ לח, א."],["46","46","עו, א. שם, ג. דרמ״צ פג, א."],["47","47","שלכן, גם העלאת התפלה היא ע״י המלאכים (מקומות שבהערה 32)."],["48","48","ויצא כח, יב. זח״א רסו, ב. זח״ג שו, ב. תקו״ז תי׳ מה."],["49","49","שהם לא רק רחוקים זמ״ז אלא גם הפכים (ד״ה זה היום תרצ״ד ספ״א)."],["50","50","ד״ה זה היום שם."],["51","51","לשון כ״ק מו״ח אדמו״ר בד״ה זה היום הנ״ל רפ״ב."]]],[1300201333,"דחביק לה כו׳), עד״ז פועלת היא גם בכל עניני האדם<sup data-n=\"52\">52</sup> ובפרט בהתומ״צ<sup data-n=\"53\">53</sup> שלו, שע״י ד׳ השליבות דתפלה (שהם כנגד ד׳ עולמות) עולות הן מעולם לעולם, ועד שהן עולות בבחי׳ השמימה שלמעלה מהעולמות, ועד שהן עולות למהותו ועצמותו ית׳ ממש.\nז) וזהו אחד הביאורים בהשייכות דלבושי המצוות לענין הימים (כפשוטם), כי עליית המצוות הוא ע״י התפלה, והתפלה הרי היא „ענין עבודת היום\" [וכמובן גם ממרז״ל 54 תפלות כנגד תמידין תקנום, עולת תמיד העשוי׳ בכל יום, שנים ליום 55], שהתפלה בכל יום מבררת ומעלה את הניצוצות שנתחדשו ביום זה 56, לכן המצוות [שעלייתן הוא ע״י התפלה] זקוקים ל„עבודת היום\" 57.\nאמנם ביאור זה מבאר רק השייכות דמצוות לימים. אבל עדיין אינו מובן ההכרח לעשיית המצוות בכל יום דוקא, דלכאורה, גם כשיחסיר יום אחד ולמחר יעשה שתי מצוות, יזדככו המצוות ע״י התפלה דיום המחרת. ואין לומר שהתפלה יכולה לזכך ולהעלות רק המצוות השייכות ליום זה, דאין כל טעם לחילוק זה. ועוד דמכיון דיש ענין התשלומין (ביום שלאח״ז, בתפלה הסמוכה לה) 58 „ואין אומרים כיון שעבר יומו בטל קרבנו\" 59, ועד ש(בנוגע לכוונת התפלה) תפלה אחת מלוקטת מתפלות כל השנה מעלית את תפלות דכל השנה 60, משמע מזה גם בנוגע לעליית המצוות שע״י התפלה, התפלה מעלית גם המצוות דיום הסמוך וכו׳. וסמוכין לדבר וכו׳ — התפלות שבת שהם מעלים התפלות של כל ימי החול עם כל התורה ומע״ט שנכללו בהן 61.",[["52","52","ראה ד״ה זה היום שם ספ״ב: דע״י אותיות התפלה הוא ההעלאה של כל העניינים דארצה שהם עפ״י התורה."],["53","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו״ת יו״כ סח, ב</a> (הובא באוה״ת לתהלים שם) ש„מלאכי אלקים\" (שעולים בהסולם דתפלה) הם המצוות."],["54","54","ברכות כו, ב."],["55","55","פינחס כח, ג."],["56","56","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו״א לח, ג</a>."],["57","57","אוה״ת לתהלים שם."],["58","58","או״ח סי׳ קח."],["59","59","שו״ע אדה״ז שם ס״ב."],["60","60","תניא בקו״א ד״ה להבין מ״ש בשער היחודים (קנד, ב)."],["61","61","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו״ת בהר מא, א</a>."]]],[1300201334,"ח) אך הענין הוא, דהנה ידוע שהתכלית דתומ״צ הוא לפעול בירור וזיכוך בעוה״ז הגשמי. דזהו מה שתורה לא בשמים היא 62, וכל התורה ניתנה לעשות שלום בעולם 63, ועאכו״כ מצוות שלא ניתנו אלא לצרף בהן את הבריות 64. ועד שמצות צדקה היא שקולה כנגד כל המצוות (ונקראת בשם מצוה סתם), כי התכלית דמצוות [וכן התכלית דירידת הנשמה למטה] שהוא [לא בשביל הנשמה כ״א] בכדי לתקן את הגוף ונפה״ב וחלקו בעולם, נשלם ע״י מצות הצדקה (יותר מאשר ע״י שאר כל המצוות), כמבואר בתניא 65. וזהו 66 שצריך להיות יומין שלימין דוקא, שבכל יום ויום צריך להיות קיום מצוה, כי מכיון שגדר העולם הוא מקום וזמן 67, הרי מובן שהתומ״צ (שתכליתם הוא לתקן את העולם) צריכים לתקן גם את הזמן. ולכן מוכרח שבכל יום תהי׳ עשיית מצוה (הגם שגם כשחסר לו יומא חדא יכול הוא לעשות את הלבוש ע״י שיקיים מחר לו ב׳ מצוות), כי בכדי לתקן את הימים 68 (הזמן) גופא צריך להיות כל 69 יומא ויומא עביד עבידתי׳.\nט) וזהו ואברהם זקן בא בימים, שלאחרי שואברהם זקן הוא גם בא בימים שהוא מעלה גדולה יותר גם מהמעלה דזקן. דהנה הכוונה האמיתית בהתהוות העולמות (בבחי׳ עצמות א״ס) היא מה שנתאוה הקב״ה להיות לו ית׳ דירה בתחתונים דוקא 70. וכוונה זו נשלמת ע״י עבודת האדם, אתם קרויין אדם 71, שהאדם דוקא יכול להשלים כוונה זו. וזהו שנקרא בשם אדם, ע״ש ב׳ הקצוות שהוא אדמה לעליון 72 ושהוא נוצר מן האדמה 73, שגופו נעשה",[["62","62","ב״מ נט, ב."],["63","63","רמב״ם סוף הל׳ חנוכה."],["64","64","ב״ר פמ״ד, א."],["65","65","פל״ז (מח, ב)."],["66","66","אוה״ת משפטים ע׳ א׳קכב. שבועות ע׳ צא. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830262\" data-slug=\"or-hatorah-hb\" data-id=\"8158830262\">בלק ס״ע תתקמח</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010084\" data-slug=\"or-hatorah-hb\" data-id=\"8159010084\">פינחס ע׳ א׳קצט</a>. וראה בארוכה לקו״ש כרך ד׳ ע׳ 1194."],["67","67","שעהיוה״א פ״ז (פב, רע״א). ועפ״מ בתולוי״צ למסכת מדות (ריש ע׳ רעג), שמקום הוא בז״א וזמן הוא במלכות — עיקר הענין דדירה בתחתונים שאין תחתון למטה ממנו הוא בבירור ותיקון הזמן."],["68","68","ומה שעיקר ההדגשה הוא על הימים (וראה תורת הבעש״ט שבתחילת המאמר) — הוא (כמבואר בלקו״ש שם) לפי שבהם הוא עיקר ההתחלקות דזמן, כמרז״ל (נזיר ז, א) „יומי מפסקי מהדדי\". ולהעיר מאוה״ת בלק שם ואילך."],["69","69","עפ״פ לשון הזהר — ח״ג צד, ב."],["70","70","המשך תרס״ו ע׳ תמו."],["71","71","יבמות סא, א."],["72","72","שלי״ה כ, ב. שא, ב. ובכ״מ."],["73","73","ב״ר פי״ז, ד."]]],[1300201335,"מהאדמה עצמה 74 ובאופן שהי׳ תחילה דומם בפ״ע (בלי שום נפש חיונית בתוכו) וכמ״ש 75 גלמי ראו עיניך (ולא כגוף הצומח והחי) 76, כי גם ענין זה שבתואר אדם (על שם האדמה) מורה על מעלתו 77, שהוא מברר מתקן ומעלה גם את הדומם שהוא תחתון ביותר שאין תחתון למטה ממנו. ומעלה זו שבו באה בפועל ע״י העבודה דבא בימים דוקא. שע״י העבודה דזקן (עצמה), אף שגם ע״י בירר ותיקן את חלקו בעולם (מקום), מ״מ, מכיון שלא תיקן עדיין את הזמן, הרי לא השלים עדיין הכוונה דדירה בתחתונים. ולכן הגם שעבודה זו מגעת בבחינת עתיק יומין, שהיא בהעתקה (והבדלה) מבחי׳ יומין, אין זה תכלית השלימות. משא״כ ע״י העבודה דבא בימים 78, כשעובד לתקן את הימים, ועד דאת מספר ימיך אמלא 79 מספר מלשון אבן ספיר (וכמ״ש בתו״א 80 שמספר ימיך הוא כמו השמים מספרים 81 שפירש בזהר 82 מנהרין ומנצצין וספירין), היינו שהאדם מאיר את הימים (הזמן) באור התורה והמצוות, עי״ז הוא משלים הכוונה דדירה בתחתונים (בהתחתון שבעוה״ז גופא<sup data-n=\"83\">83</sup>, שזה (השלמת כוונה זו) הוא תכלית שלימות מעלת האדם, כנ״ל.",[["74","74","והיינו, שהצומח והחי נבראו ממאמר אלקי (תדשא הארץ, תוצא הארץ), משא״כ „גופו של אדה״ר לא נברא ע״י מאמר אלקי .. כשאר כל הברואים .. אלא רק צבר עפרו .. ועשה בו צורה גשמית שלא ע״י מאמר כלל וכלל\". ומ״ש נעשה אדם — „פשטו מורה שלא ע״י מאמר זה נעשה אלא כמ״ש צבר עפרו ועשאו גולם תחילה בלי מאמר כלל\" (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670057\" data-slug=\"torat-chaim\" data-id=\"2300670057\">תו״ח בראשית יט, ב</a>)."],["75","75","תהלים קלט, טז. וראה סנהדרין לח, סע״א ואילך."],["76","76","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">תו״א ג, ד</a> ואילך. תו״ח שם יח, ד ואילך. ובכ״מ."],["77","77","ד״ה זה היום השי״ת פ״ב."],["78","78","והא שמבואר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו״א לג, ב</a> (נעתק לעיל הערה 16) שעתיק יומין הוא נבדל מבחי׳ היומין שהם הלבושים הנעשים מהמצוות — יש לומר, שהכוונה שם היא לענין המצות (מצד עצמם), אבל לא לענין בירור הזמן שנעשה ע״י״ז. ולהעיר מזה שמסיים בתו״א שם: אך ע״י בירור נה״ב כו׳. ועצ״ע."],["79","79","משפטים כג, כו."],["80","80","עס, ריש ע״ג."],["81","81","תהלים יט, ב."],["82","82","ח״ב קלו, ב. ונתבאר בארוכה בסידור קעה, סע״א ואילך. פיהמ״ל לאדהאמ״צ פ״ט ואילך."],["83","83","ראה לעיל הערה 67."]]],[1300201336,"שיחת מוצאי ש״פ חיי שרה, מבה״ח כסלו - בחדרו - ה׳תשל״ח.\nא. ס׳איז מוצאי שבת קודש, און אין דערויף קומט צו נאך דער פרט — אז ס׳איז דער מוצאי שבת קודש פון ש״פ חיי שרה, און אויך א דריטער ענין — דער מוצאי שבת קודש פון שבת מברכים חודש כסלו.\nוע״פ תורת הבעש״ט<sup data-n=\"1\">1</sup> אז יעדער ענין איז א הוראה אין עבודת ה׳ — איז פארשטאנדיק, אז אין יעדער ענין פון די דריי ענינים הנ״ל, איז דא א הוראה פאר אלע אידן און פאר יעדער אידן אין עבודת ה׳ [וואס דאס איז תכלית בריאתו, כמרז״ל<sup data-n=\"2\">2</sup> אני נבראתי לשמש את קוני].\nאון ויבאלד אז די אלע דריי הוראות האבן זיך צוזאמען געטראפן בבת אחת — איז מובן<sup data-n=\"3\">3</sup>, אז אין די אלע דריי הוראות איז דא א צד השוה וואס איז זיי מאחד,\nאון אז דער צד השוה האט אין זיך א חשיבות מיוחדת, וואס איז העכער<sup data-n=\"4\">4</sup> (ביז צו העכער באין ערוך<sup data-n=\"5\">5</sup> אפילו פון די חשיבות וואס אין יעדער הוראה בפני עצמה.\nב. דער סדר פון די דריי ענינים הנ״ל —\nאע״פ אז לכאורה קומט צום אלעם ערשטן דער „בשותף״דיגער\" ענין פון די אלע דריי, דער ענין פון מוצאי שבת קודש, און דערנאך ווערט אין דעם ניתוסף אז דאס איז א מוצאי ש״ק פון שבת פרשת חיי שרה און פון שבת מברכים (כסלו),\nאיז אבער ע״פ הידוע בגודל מעלת התורה [אפילו אויף מעלת המצוות<sup data-n=\"6\">6</sup>], איז פארשטאנדיק, אז דער ענין הכי חשוב אין (יעדער) מוצאי ש״ק איז די פרשה בתורה וואס מען לייענט בשבת [וואס אויך מוצאי שבת איז שייך צו דער פרשה<sup data-n=\"7\">7</sup>],\nוואס פון דעם איז פארשטאנדיק בנוגע צום סדר (החשיבות) פון די דריי ענינים הנ״ל וואס אין היינטיקן מוצאי ש״ק, אז דער ערשטער ענין אין אים — וואס ער איז שייך צו (א פרשה ב)תורה, ובפרטיות, [וואס דאס איז נוגע במיוחד צו היינטיקן מוצאי שבת, ובפרט ע״פ תורת כ״ק אדה״ז<sup data-n=\"8\">8</sup> אז מען דארף לעבן מיט דער פרשת השבוע] — צו פרשת חיי שרה:\nואע״פ אז בכל מוצאי ש״ק זיינען דא כמה דינים און מנהגי ישראל (וואס אויך מנהג ישראל תורה היא<sup data-n=\"9\">9</sup>, זיינען די דינים און מנהגים (בלויז) מצות, וואס קומען ניט צו די מעלה פון תורה<sup data-n=\"6\">6</sup>",[["1","1","היום יום ע׳ נב."],["2","2","קידושין בסופה."],["3","3","שהרי כל הענינים (ומכ״ש עניני תומ״צ) אינם באקראי ח״ו, כ״א בהשגחה פרטית."],["4","4","ע״ד המבואר בשעהיוה״א פ״ב בענין אור העולה על כולנה."],["5","5","להעיר מהמשך תער״ב פכ״ז-כ״ח שנוסף על האור הכללי המתלבש בהפרטים בבחי׳ אור פנימי — יש גם אור כללי „שהוא בבחי׳ בל״ג ממש\", ועד שהצמצום באור זה (בפירוד הפרטים) הוא (לא בבחי׳ מיעוט, כ״א) בבחי׳ סילוק."],["6","6","מו״ק ט, רע״ב."],["7","7","ראה לעיל ע׳ 301 הערה 4."],["8","8","סה״ש תשי״ב ע׳ 29 ואילך."],["9","9","ראה תוד״ה נפסל — מנחות כ, ב. ירושלמי פסחים פ״ד ה״א."]]],[1300201337,"[בפרט צו תורה ווי זי ווערט געלייענט בציבור, און מיט א ברכה לפני׳ ולאחרי׳,\nוואס נוסף צום גודל העילוי פון ברכות בכלל (כמבואר בתו״א<sup data-n=\"10\">10</sup> ובדרושי רבותינו נשיאינו<sup data-n=\"11\">11</sup>), איז דא א מעלה מיוחדת אין ברכת התורה („ברכו בתורה תחלה\"<sup data-n=\"12\">12</sup>), ביז אז אין דעם איז תלוי קיום הארץ<sup data-n=\"13\">13</sup>];\nדערנאך קומט דער ענין פון מוצאי שבת קודש — וואס דער נאמען — שמו אשר יקראו לו בלה״ק „מוצאי שבת קודש\" איז מדגיש (נאר) דעם זמן פון מוצש״ק (און ניט די דינים ומנהגים שבו<sup data-n=\"14\">14</sup>),\nאון דערנאך קומט דער ענין פון מוצאי שבת מברכים חודש כסלו, וואס אויך אין דעם זיינען דא צוויי ענינים [ועד״ז אויך צוויי ענינים אין קריאת התורה]: דער ענין פון ברכת החודש (בכלל), וואס ברכת החודש האט א שייכות (ובדוגמת) צו קידוש החודש<sup data-n=\"15\">15</sup>; און דער ענין הפרטי (וואס איז נוגע במיוחד היינט) — וואס מען בענטשט חודש כסלו.\nג. אין פרשת חיי שרה גופא — זיינען פאראן דריי ענינים כלליים:\nצום אלעם ערשטן — דער ענין פון חיי שרה [וואס נוסף צו דעם וואס ער\nאיז דער ערשטער ענין פון דער סדרה, איז (ווי גערעדט כמה פעמים<sup data-n=\"16\">16</sup> בנוגע צו שמות הסדרות, איז) ער אויך דער נאמען וואס גיט ארויס די נקודה התיכונית פון אלע ענינים פון דער סדרה];\nדערנאך — דער ענין פון „ואברהם זקן גו׳\"<sup data-n=\"17\">17</sup> (וואס קומט בתור הקדמה<sup data-n=\"18\">18</sup> צו) „ויאמר אברהם אל עבדו וגו׳\"<sup data-n=\"19\">19</sup> (וואס אברהם האט געזאגט אליעזר׳ן צו בריינגען רבקה׳ן);\nאון דערנאך — די „פרשה של שיחת אליעזר\" וואס איז א פרשה ארוכה און א פרשה חשובה, ווי רש״י<sup data-n=\"20\">20</sup> זאגט אז דער טעם פון דעם וואס די פרשה איז „כפולה בתורה\" איז ווייל „יפה שיחתן של עבדי אבות כו׳ מתורתן של בנים\", אז ניט נאר וואס זי איז יפה בכלל, נאר אז איר יופי איז גרעסער אפילו פון דעם יופי פון „תורתן של בנים\".\nד. וויבאלד אז אלע דריי ענינים הנ״ל זיינען פאראייניקט אין דער זעלבער סדרה — איז פארשטאנדיק (ע״ד הנ״ל ס״א), אז אין די אלע דריי ענינים איז דא א צד השוה.\nאון וויבאלד אז די אנדערע צוויי ענינים „ואברהם זקן\" און „פרשה של שיחת אליעזר\" זיינען חלקים (פרטים) פון (פרשת) חיי שרה [וכנ״ל (סעיף ג׳) אז דער נאמען „חיי שרה\" גיט ארויס דעם תוכן פון אלע ענינים פון דער סדרה] — איז פארשטאנדיק, אז די",[["10","10","ד״ה להבין ענין הברכות (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו״א ו, א</a> ואילך)."],["11","11","ד״ה הנ״ל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560169\" data-slug=\"or-hatorah-hb\" data-id=\"8316560169\">אוה״ת בראשית (כ״ג תקנא, א</a> ואילך). המשך חייב אדם לברך תרל״ח. ובכ״מ."],["12","12","שהו״ע נעלה ביותר — ראה ב״ח או״ח סמ״ז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380691\" data-slug=\"likkutei-torah\" data-id=\"4001380691\">לקו״ת מסעי צא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">ראה כט, א</a>. ובכ״מ."],["13","13","ב״מ פה, סע״א ואילך. נדרים פא, א."],["14","14","משא״כ הפרשה — שהרי כל מוצש״ק נקרא „מוצאי שבת פרשת ..\"."],["15","15","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091187\" data-slug=\"likkutei-sichot\" data-id=\"1300091187\">לקו״ש ח״ט ע׳ 187</a> ואילך ובהנסמן שם."],["16","16","וראה גם לעיל ע׳ 285 ובהנסמן שם בהערה 36."],["17","17","פרשתנו כד, א."],["18","18","פרש״י שם."],["19","19","פרשתנו כד, ב ואילך."],["20","20","שם, מב."]]],[1300201338,"הוראה פון „חיי שרה\" איז א הוראה כללית; און די הוראה פון „ואברהם זקן\" און פון „פרשה של שיחת אליעזר\" זיינען פרטים וואס קומען צו אין דער הוראה (כללית) פון „חיי שרה\".\nה. מאמר ד״ה ואברהם זקן בא בימים.\nו. די הוראה פון „ואברהם זקן בא בימים\" [וואס האט זיך גערעדט אין מאמר, מיוסד אויף מאמרי רבותינו נשיאינו]\n— אז די מעלה פון דער עבודה פון „בא בימים\" [אויפטאן אין די „ימים\", זמן] איז גרעסער אפילו פון דער מעלה פון דער עבודה וואס אין „זקן\" [אע״פ אז דער ענין פון „זקן\" איז בדוגמת בחי׳ „עתיק יומין\"<sup data-n=\"21\">21</sup>] —\nאיז (כנ״ל סעיף ד׳) א פרט וואס קומט צו אין דער הוראה (כללית) פון „חיי שרה\" (כדלקמן סעיף יד).\nז. וועט מען עס פארשטיין בהקדים וואס רש״י<sup data-n=\"22\">22</sup> זאגט אויף „שני חיי שרה\" „כולן שוין לטובה\" — אז ניט נאר וואס אלע אירע יארן זיינען געווען גוטע יארן, נאר אויך אז „כולן שוין לטובה\" (אז אין אלע אירע יארן איז געווען א גלייכקייט אין דעם טוב).\nוואס פון דעם לשון „כולן שוין לטובה\" איז פארשטאנדיק, אז ניט נאר וואס דער (זעלבער) טוב וואס אין אירע פריערדיקע יארן איז געווען אויך אין אירע שפעטערדיקע יארן (ווי רש״י זאגט פריער<sup data-n=\"23\">23</sup> „בת ק׳ כבת כ׳ לחטא כו׳ ובת כ׳ כבת ז׳ ליופי\"), נאר אויך לאידך גיסא: אז אויך אירע פריערדיקע יארן\nזיינען געווען „שוין לטובה\" צו אירע שפעטערדיקע יארן<sup data-n=\"24\">24</sup>.\nולכאורה איז ניט מובן: ס׳איז דאך א דבר פשוט אז שרה האט געהאלטן אין עולה זיין מדרגא לדרגא [אזוי ווי אלע צדיקים<sup data-n=\"25\">25</sup>, וואס „ילכו מחיל אל חיל\"<sup data-n=\"26\">26</sup>] — טא ווי קען מען זאגן<sup data-n=\"27\">27</sup>, אז דער טוב פון אירע פריערדיקע יארן איז בשוה צו דעם טוב פון אירע שפעטערדיקע יארן ?\nח. נוסף צו דעם וואס בא שרה׳ן (ווי ביי אלע צדיקים) איז געווען די הליכה מחיל אל חיל — זיינען געווען ביי איר אויך כמה שינויים כלליים, דורך וועלכע זי איז נתעלה געווארן (ביז — שלא בערך) לגבי ווי זי איז געווען פריער:\nבשעת ס׳איז געווען דער „וילך אברם כאשר דבר אליו ה׳ גו׳\"<sup data-n=\"28\">28</sup> (און ער האט מקיים געווען דעם ציווי „לך לך מארצך וממולדתך ומבית אביך גו׳\"<sup data-n=\"29\">29</sup> און דערביי איז „ויקח אברם את שרי אשתו גו׳\"<sup data-n=\"30\">30</sup> — איז זי נתעלה געווארן שלא בערך. ווארום ס׳איז דאך מובן, אז די עילויים פון „לך לך\"<sup data-n=\"31\">31</sup> [און אויך דער",[["21","21","ראה ב״ר ספנ״ח. רש״י ומ״כ שם."],["22","22","פרשתנו כג, א."],["23","23","בד״ה ויהיו חיי שרה גו׳."],["24","24","ועפ״ז מובן בפשטות ההוספה ד„כולן שוין לטובה\" על „בת ק׳ כבת כ׳ כו׳\" — נוסף על מה שיש לומר, שההוספה היא ש„כולן שוין כו׳\" ולא רק „כבת כ׳ ו„כבת ז׳\" (בכ״ף הדמיון). וראה לקו״ש ח״ה פרשת חיי שרה ובהוספות שם."],["25","25","בגמרא שבהערה הבאה: תלמידי חכמים. אבל בת״י לתהלים פד, ח (שמשם למדים בגמרא שם ש„אין להם מנוחה כו׳\"): „אזלין צדיקיא\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151137\" data-slug=\"likkutei-sichot\" data-id=\"1300151137\">לקו״ש חט״ו ע׳ 137</a> ואילך."],["26","26","תהלים שם. סוף מס׳ ברכות. סוף מס׳ מו״ק."],["27","27","ובפרט שהלשון „ילכו גו׳\" מורה על עלי׳ שבאין ערוך (ד״ה צדר תרס״ב. וראה גם תו״א ס״פ וישב. ובכ״מ)."],["28","28","לך לך יב, ד."],["29","29","שם, א."],["30","30","שם, ה."],["31","31","ראה בארוכה לעיל בד״ה לך לך ובשיחת מוצאי ש״פ לך לך ובהנסמן שם."]]],[1300201339,"שכר „ואעשך לגוי גדול וגו׳ (ביז) והי׳ ברכה\"<sup data-n=\"32\">32</sup>] האבן זיך אויפגעטאן אויך בא שרה׳ן:\nדערנאך, בשעת ס׳איז נשתנה געווארן איר נאמען פון „שרי\" צו „שרה\"<sup data-n=\"33\">33</sup> — איז זי ווידער נתעלה געווארן שלא בערך. וכמובן אויך אין פשטות הכתובים דער גודל העילוי פון „שרה\", וואס מיינט „שרה על כל\"<sup data-n=\"34\">34</sup> (אויף אלע ענינים), אויף „שרי\", וואס מיינט „שרי לי׳\"<sup data-n=\"34\">34</sup> (בלויז צו אברהם׳ן).\nוואס עפ״ז איז נאכמער ניט פארשטאנדיק וואס רש״י זאגט „כולן שוין לטובה\": ווי קען מען פארגלייכן די יארן ווען זי האט געהייסן „שרי\", און עאכו״כ די יארן איידער ס׳איז געווען דער „לך לך\", צו די שפעטערדיקע יארן (ווען ס׳איז שוין געווען בא איר די עילויים וואס האבן זיך אויפגעטאן דורך „לך לך\", און ווען זי האט שוין געהייסן „שרה\") און זאגן אז זיי זיינען „כולן שוין\" ?\nט. די שאלה איז נאך גרעסער: פון דעם אליין וואס רש״י זאגט „בת ק׳ כבת כ׳ לחטא כו׳ ובת כ׳ כבת ז׳ ליופי\", איז פארשטאנדיק דער עילוי וואס איז געווען אין איר ווען זי איז געווען בת כ׳ לגבי ווי זי איז געווען בת ז׳, און דער עילוי ווען זי איז געווען בת ק׳ לגבי ווי זי איז געווען בת כ׳:\nוויבאלד אז אין די יארן ווען זי איז געווען עלטער פון בת ז׳ איז איר יופי געווען באופן של חידוש (ווארום מצד טבע הגוף רופט ארויס דער עלטער ווערן מיעוט היופי) — איז פאר־שטאנדיק, אז דאן איז ביי איר געווען אזא עבודה נעלית וואס האט גע׳פועל׳ט א שינוי בטבע הגוף<sup data-n=\"35\">35</sup>.\nועד״ז איז אויך בנוגע צו די שפעטערדיקע יארן ווען זי איז געווען עלטער פון בת כ׳, אז וויבאלד אז דאס וואס אויך דאן איז זי געווען „בלא חטא\" איז עס געווען מצד איר עבודה — האט דאך געדארפט צוקומען אט די עבודה — א הוספה און א העכערע מדריגה ווי זי איז געווען ביז בת כ׳.\n[ויש לומר, אז דער חילוק פון די דריי דרגות הנ״ל איז מרומז אויך אין דעם וואס דער פסוק טיילט אויס די יארן פון שרה׳ן אין דריי סוגים — „מאה שנה\", „עשרים שנה\" און „שבע שנים\" — וואס „כל אחד נדרש לעצמו\"<sup data-n=\"36\">36</sup>].\nועד״ז איז אויך בנוגע צו אירע לעצטע זיבן און צוואנציק יאר — נאכדעם וואס זי האט שוין דערגרייכט צו די דרגא פון „מאה שנה\", וואס מאה איז שלימות המספר<sup data-n=\"37\">37</sup> (והעבודה) — אז איר עבודה דאן איז געווען בדרגת השלימות (העכער פון הגבלות פון „עולם\"<sup data-n=\"38\">38</sup>).",[["32","32","לך לך שם, ב."],["33","33","שם יז, טו."],["34","34","פרש״י שם."],["35","35","ראה גר״א ריש פרשתנו ד״ה בת עשרים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051109\" data-slug=\"likkutei-sichot\" data-id=\"1300051109\">לקו״ש ח״ה ע׳ 97</a> ואילך ובהע׳ 22, שהעדר השינוי בנוגע ליופי דשרה (שפעלה ע״י עבודתה) הי׳ (לא רק מצד אור הנשמה, כ״א גם) מצד הגוף עצמו."],["36","36","פרש״י ריש פרשתנו. ובראב״ם שם: „פירוש כל כלל מתפרש לעצמו ואינו מתחבר עם הכללים האחרים .. משום דשנה שנה לחלק משמע\"."],["37","37","ואף שיש אלף ורבבה — הרי מספרים אלו הם בחי׳ (מקיפים), אבל בנר״ן (פנימיים) — מאה הוא שלימות המספר (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381101\" data-slug=\"likkutei-torah\" data-id=\"4001381101\">לקו״ת ברכה צג, רע״ג</a>). וראה זהר רפ״ח (קכג, א): מאה שנה כללא דכולא. לקו״ת צו יוד, א. ביאוה״ז (לאדהאמ״צ ולהצ״צ) לזהר שם."],["38","38","וכמדובר כמ״פ (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011026\" data-slug=\"likkutei-sichot\" data-id=\"1300011026\">לקו״ש ח״א ע׳ 26</a>. ח״ה ע׳ 307. ועוד) בפירוש מרדו״ל (אבות ספ״ה) „בן מאה שנה כאילו מת ועבר ובטל מן העולם\"."]]],[1300201340,"ועאכו״כ בעת הסתלקותה — וואס דאן איז זי געשטאנען אין נאך א העכערן עילוי, ווארום [נוסף צו דעם וואס בעת ההסתלקות קלייבן זיך צוזאמען „כל מעשיו כו׳ אשר עבד כל ימי חייו\"<sup data-n=\"39\">39</sup>] דאן איז ביי איר צוגעקומען אויך דער ענין העילוי דורך „בשורת העקידה\"<sup data-n=\"40\">40</sup>.\nוואס ע״פ כהנ״ל איז ניט פארשטאנדיק וואס רש״י זאגט „כולן שוין לטובה\": ווי קען מען זאגן אז די ערשטע „שבע שנים\" (כולל אויך דעם ערשטן יאר) זיינען בשוה צו די לעצטע יארן (כולל אויך וואס נאך „מאה שנה\"), ביז צום זמן הסתלקותה ?\nיוד. איז די נקודת הביאור אין דעם:\nיעדע זאך וואס שרה האט געטאן איז איר עבודה געווען בתכלית השלימות לויט אירע כחות און מעגלעכקייטן וואס זי האט געהאט דעמולט — דעריבער זיינען זיי אלע „שוין לטובה\", מצד דערויף וואס אין אלע אירע מעשים האט זי ממלא געווען בשלימות בקשת הקב״ה וואס „איני מבקש כו׳ אלא לפי כחן\"<sup data-n=\"41\">41</sup>.\nאבער דער תירוץ איז ניט מספיק. ווייל לפי זה קומט אויס, אז שוין זיינען אלע אירע מעשים — פון דעם אבער וואס מען זאגט א מעלה אויף שרה׳ן — דורך איבערחזר׳ן — שני ח״ש אז „כולן — די שני — שוין לטובה\" — איז פארשטאנדיק, אז דאס איז א מעלה מיוחדת וואס שרה האט אויפגעטאן דורך איר עבודה אין „שני ח״ש\" — אין אירע יארן.\nיא. והענין: נוסף צו דעם וואס די עבודה פון שרה׳ן איז אלעמאל געווען בתכלית השלימות (לויט אירע כחות דאן), איז די עבודה געווען אין אירע יארן, און די עבודה פון די פריערדיקע יארן איז געווען (ביי איר) אויך א הקדמה און א הכנה צו דער העכערער עבודה פון די שפעטערדיקע יארן.\nאון אזוי אויך לאידך גיסא: איר עבודה אין דעם שפעטערדיקן זמן איז געווען (ניט נאר אין א העכערן אופן, לויט אירע כחות וואס זי האט געהאט דעמולט, נאר אויך) אין אזא אופן אז זי האט מעלה געווען אירע פריערדיקע עבודות און יארן, אז אויך זיי זיינען נתעלה געווארן אין דער העכערער מדריגה (פון איר שפעטערדיקער דרגא)<sup data-n=\"42\">42</sup>.\nאון וויבאלד אז אויך אירע ערשטע יארן זיינען ס״ס נתעלה געווארן אין דער מדריגה נעלית אין וועלכער זי איז געווען בהסתלקותה — דעריבער, איז (לאחרי ווי זיי זיינען נתעלה געווארן) „כולן שוין לטובה\"<sup data-n=\"43\">43</sup>.",[["39","39","אגה״ק סי׳ ז״ך (קמו, סע״א). וראה גם סידור שער הל״ג בעומר (דש, סע״ב ואילך)."],["40","40","פרש״י פרשתנו כג, ב. וראה לקמן סעיף טו."],["41","41","במדב״ר פי״ב, ג."],["42","42","להעיר מהמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061247\" data-slug=\"likkutei-sichot\" data-id=\"1300061247\">לקו״ש ח״ו ע׳ 236</a> ואילך, שמכיון שבנ״י אינם „אמצעי\" לאיזה ענין אחר כ״א התכלית הוא בהם עצמם ובכל הענינים שבהם, לכן: לאחרי שאיזה ענין שבהם מביא למדריגה נעלית יותר — הרי הענין הקודם הוא לא רק „אמצעי\" למדריגה הנעלית, כי אם, שהוא עצמו מתעלה במדריגה זו, מכיון שזה (מדריגה הנעלית) הוא התכלית ואמיתית מציאותו של הענין הקודם עצמו."],["43","43","ועפ״ז אולי י״ל מה שבהענין ד„כולן שוין לטובה\" נאמר רק שכל שנותי׳ של שרה הי׳ „שוין לטובה\" — ולא ששרה היתה שוה במשך כל שנותי׳ (כמו בענין „בת ק׳ כבת כ׳ כו׳ ובת כ׳ כבת ז׳\") — כי מכיון שהי׳ בה כו״כ (שינויים ו)עליות, יתכן לומר רק שהשנים (לאחרי שנתעלו) הם „כולן שוין לטובה\" — ועצ״ע נקודת החילוק בין הזמן והאדם, באם ישנו."]]],[1300201341,"יב. אע״פ אז דער ענין פון „כולן שוין לטובה\" איז א מעלה וואס מען זאגט אויף שרה׳ן [וואס זי האט אויפגעטאן ע״י עבודתה צו מעלה זיין אירע פריערדיקע שנים ועבודות אין דער העכערער מדריגה, כנ״ל],\nוויבאלד אבער אז דאס שטייט אין תורה (לשון הוראה<sup data-n=\"44\">44</sup> ווערט עס א לימוד (און א נתינת כח<sup data-n=\"45\">45</sup> צו יעדער אידן [ובפרט צו נשי ובנות ישראל, וואס יעדערע פון זיי ווערט אנגערופן בת שרה וכו׳],\nאז בשעת מען ווערט עלטער און עס קומט צו א גרעסערע ידיעה און גרעסערע כחות אין עבודת ה׳ — זאל מען אויפטאן אין עלי׳ אויך אין די שנים והתומ״צ וואס מען האט געטאן פריער (איידער מען האט געהאט די גרעסערע ידיעה און כחות).\nיג. קען מען דאך מיינען: וויבאלד אז אפילו ווען מען הארעוועט בכל יום ויום אז די עבודה זאל זיין בשלימות (לויט די כחות שביום זה), דארף מען איר (והזמן) מעלה זיין אין די העכערע מדריגה צו וועלכע מען וועט צוקומען שפעטער — איז במילא ניט נוגע (אויף אזוי פיל) צו הארעווען בכל יום מיט אלע כחות אז די עבודה זאל זיין בשלימות, ווארום אפילו ווען עס וועט „פעלן\" אין דער עבודה, האט מען בכח צו משלים זיין דאס שפעטער —\nאויף דעם קומט די הוראה פון סדר הענינים אין פסוק: פריער שטייט „מאה שנה ועשרים שנה ושבע שנים\", וואס „לכן נכתב שנה בכל כלל וכלל לומר לך שכל אחד נדרש לעצמו\"<sup data-n=\"46\">46</sup> — אז יעדער\nזמן באזונדער דארף און מוז זיין בשלימות (לויט די דרגא פון די כחות וואס מ׳גיט אין דעם זמן):\nאון ערשט לאחרי זה „שני חיי שרה — כולן שוין לטובה\" — אז דוקא לאחרי זה און דורך דעם וואס יעדער זמן באזונדער איז בשלימות, קען מען נתעלה ווערן אין דער העכערער מדריגה פון דעם שפעטערדיקן זמן.\nיד. און דאס איז אויך דער צד השוה פון דער הוראה פון „(ואברהם זקן) בא בימים\" מיט דער הוראה פון „חיי שרה\" — ווארום אויך די הוראה פון „בא בימים\" איז (ווי גערעדט אין מאמר) אז עס דארף זיין „כל הימים שלמים\"<sup data-n=\"47\">47</sup>,\nאון [ניט נאר וואס אין יעדער טאג דארף זיין עבודה („כל יומא ויומא עביד עבידתי׳\"<sup data-n=\"48\">48</sup>, נאר אויך אז] יעדער טאג דארף זיין א שלם — פולער און פולקאמענער<sup data-n=\"49\">49</sup>, אז אלע רגעים פון טאג (און אויך אלע כחות וואס זיינען דא ביום זה) זאלן זיין אנגעפילט מיט עבודת ה׳ בשלימות.\nאון אין דער הוראה פון „(ואברהם זקן) בא בימים\" קומט צו נאך א פרט [ווי גערעדט פריער (סעיף ד׳) אז די הוראות פון די ענינים פרטים שבפרשתנו זיינען פרטים וואס קומען צו אין דער הוראה (כללית) פון „חיי שרה\"]:\nדאס וואס יעדער זמן דארף זיין אנגעפילט מיט עבודת ה׳ איז עס (ניט נאר צוליב דעם ענין העבודה, נאר אויך, און בעיקר) צוליב דעם זמן גופא (ווי גערעדט בארוכה אין מאמר).",[["44","44","ראה זח״ג נג, ב."],["45","45","כמובן ממרז״ל שבהערה 41."],["46","46","פרש״י ריש פרשתנו."],["47","47","תו״א עס, ב — ע״פ זח״א רכד, א."],["48","48","זח״ג צד, ב."],["49","49","ראה המכתב כללי דח״י אלול ה׳תשל״ז (נדפס בלקו״ש חי״ד ע׳ 473)."]]],[1300201342,"וואס דאס איז אויך דער דיוק הלשון „יומין שלימין\" — און מען דארף אויפטאן אז די טעג זאלן זיין בשלימות.\nטו. נאך א צד השוה אין די הוראות פון צוויי ענינים הנ״ל [„חיי שרה\" און „ואברהם זקן בא בימים\"], וואס אויך אין דעם ענין קומט צו א פרט נוסף אין דער הוראה פון „ואברהם זקן בא בימים\" אויף דער הוראה פון „חיי שרה\":\nאין דער פרשה „ויהיו חיי שרה\" (די פרשה ראשונה פון דער סדרה) ווערט דערציילט אז ווען שרה האט געהערט „בשורת העקידה\" איז „פרחה נשמתה\"<sup data-n=\"50\">50</sup>. וואס דער פשט אין דעם איז\n[ניט אז בשורת העקידה האט גע׳פועל׳ט אין איר אן ענין בלתי רצוי, ח״ו — וויבאלד אז דער ענין העקידה איז אן ענין נעלה ביותר, און ער האט אויפגעטאן אן עילוי נפלא בא יצחק׳ן און אויך ביי אברהם׳ן (כמבואר בכמה דרושים) — קען מען דאך ניט זאגן, אז בנוגע צו שרה׳ן האט ער גע׳פועל׳ט היפך העילוי, ח״ו. נאר דער פשט אין דעם איז],\nאז דער ענין (פון בשורת) העקידה האט אין איר אויפגעטאן אן עילוי גדול ביותר, וואס איז העכער פון דרגת הנשמה ווי זי איז מלובש בגוף — „פרחה נשמתה\" 50*).\nאון אע״פ אז ענין העקידה (וואס האט געבראכט דעם עילוי פון „פרחה נשמתה\") ווערט דערציילט אין פרשת וירא — איז אבער דער עילוי פון „פרחה נשמתה\" שטייט ערשט אין פרשת חיי שרה:\nאז דוקא דורך דעם וואס אלע אירע יארן זיינען געווען בתכלית השלימות ביז אז אויך די פריערדיקע יארן זיינען נתעלה געווארן אין דער שלימות ווי זי איז געווען בגמר עבודתה (כנ״ל סעיף יא) — האט זי געקענט צוקומען צום עילוי פון „פרחה נשמתה\".\nלאחרי זה (וויבאלד אז „פרחה נשמתה\" איז א רגע (טייל) פון שני חיי שרה — וואס „כולן שוין לטובה\") — איז דאן געווארן כולן שוין אין דעם עילוי פון „פרחה נשמתה\"\nוואס איז טאקע דער טעם פון דעם — איז דאס ווערט פארשטאנדיק פון ענין „ואברהם זקן בא בימים\", כדלקמן.\nטז. כאמור לעיל<sup data-n=\"51\">51</sup> — פון דעם וואס פריער זאגט דער פסוק „ואברהם זקן\" און דערנאך איז ער מוסיף „בא בימים\", איז מוכח אז אע״פ אז דער ענין פון „זקן\" איז א מדריגה נעלית, ביז אז מען פארבינדט עס מיט בחינת „עתיק יומין\" — פונדעסטוועגן, איז דורך דער עבודה פון „בא בימים\", וואס אברהם האט גע׳פועל׳ט אין די „ימים\" אז זיי זאלן זיין בשלימות, איז ער נתעלה געווארן נאך העכער.\nאון דאס איז אויך דער ביאור אין דעם וואס דער עילוי פון „פרחה נשמתה\" איז געקומען דוקא (כנ״ל סט״ו) דורך דעם וואס אלע אירע פריערדיקע יארן זיינען געווען בשלימות, „כולן שוין לטובה\":\nדער עילוי פון „פרחה נשמתה\" — העכער (און מובדל) פון דרגת הנשמה המלובשת בגוף — איז בדוגמת בחינת „עתיק יומין\" וואס ער איז נעתק ונבדל פון „יומין\"<sup data-n=\"52\">52</sup>. און היות אז דער ענין פון",[["50","50","פרש״י פרשתנו כג, ב. 50*) ע״ד מרז״ל (שבת פח, ב) דעל כל דבור פרחה נשמתן."],["51","51","בהמאמר — נעתק לעיל סעיף ו׳."],["52","52","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380965\" data-slug=\"likkutei-torah\" data-id=\"4001380965\">לקו״ת ר״ה סא, ג</a>. דרמ״צ לט, רע״א. ועוד."]]],[1300201343,"„בא בימים\" איז העכער פון דעם ענין פון „זקן\" וואס איז בדוגמת בחינת „עתיק יומין\"<sup data-n=\"21\">21</sup> — דעריבער קומט נאך דעם עילוי פון „פרחה נשמתה\" (בדוגמת ענין „זקן\") — דער עילוי פון „כולן שוין לטובה\" (בדוגמת „בא בימים\") — נוסף אויף אייגענער שלימות ביז דער שלימות פון „פרחה נשמתה\" אויך די שלימות אין דער זעלבער טוב אין די שנים<sup data-n=\"53\">53</sup>, ווארום דער ענין פון כל השנים „שוין לטובה\" און „בא בימים\" איז העכער פון דעם ענין פון „זקן\" ופרחה נשמתה.\n* * *\nיז. עד״ז איז אויך בנוגע צום דריטן כללות׳דיקן ענין פון היינטיקער סדרה — „פרשה של שיחת אליעזר\", וואס פון איר לערנט מען אפ<sup data-n=\"20\">20</sup> אז „יפה שיחתן של עבדי אבות כו׳ מתורתן של בנים\", אז די הוראה פון „יפה שיחתן כו׳\" איז פארבונדן (אין איר איז דא א „צד השוה\") מיט די הוראות פון די פריערדיקע צוויי כלליים ענינים — „חיי שרה\" און „ואברהם זקן בא בימים\" (כדלקמן סעיף כב), און אז אין דער הוראה פון „יפה שיחתן כו׳\" קומט צו א הוספה אויף די פריערדיקע צוויי הוראות (כדלקמן סעיף כה ואילך).\nיח. וועט מען פארשטיין בהקדים דעם פירוש אין מרז״ל הנ״ל „יפה שיחתן של עבדי אבות כו׳ מתורתן של בנים\" — ווי איז שייך צו זאגן אז אין „שיחה\" זאל זיין א יתרון לגבי תורה ?\nדי קשיא איז נאך גרעסער: „תורתן של בנים\" מיינט דאך תורה ווי זי איז לאחרי מ״ת [וכדמוכח פון דעם וואס „יפה שיחתן כו׳ מתורתן של בנים\" קומט\nבתור ביאור אויף דעם וואס „הרבה גופי תורה לא ניתנו אלא ברמיזה\"<sup data-n=\"20\">20</sup>, וואס דאס רעדט זיך דאך וועגן „גופי תורה\" שלאחרי מ״ת]. איז תמוה: אפילו תורה ווי זי איז געווען פאר מ״ת איז ניט בערך צו תורה ווי זי איז לאחרי מ״ת<sup data-n=\"54\">54</sup> — איז ווי קען מען זאגן אז די „שיחה\" פון יענעם זמן (שלפני מ״ת) איז „יפה\" פון דער תורה שלאחרי מ״ת ?\nנאך מער: לאחרי מ״ת — זיינען דא צוויי כללות׳דיקע מדריגות אין לימוד התורה: ווי זי איז „תורת ה׳\", און ווי זי ווערט „תורתו\"<sup data-n=\"55\">55</sup> (פון דעם אדם הלומד, ביז אז ער ווערט בעה״ב אויף איר), וואס דאס איז דער תכלית העילוי אין לימוד התורה. און אעפ״כ זאגט מען, אז „שיחתן של עבדי אבות\" איז יפה ניט נאר פון תורה (ווי זי איז לאחרי מ״ת) סתם, נאר אפילו פון תורה ע״י הלימוד באופן אז די תורה ווערט „תורתן\" (זייער תורה) ?\nיט. וועט מען פארשטיין ע״פ המבואר אין חסידות<sup data-n=\"56\">56</sup>, אז דער ענין פון „שיחתן של עבדי אבות\" איז פארבונדן מיט דעם ענין פון די עשרה מאמרות שבהם נברא העולם, וואס לגבי דעם אויבערשטן זיינען זיי „מילין דהדיוטא\"<sup data-n=\"57\">57</sup> און דערפאר ווערן זיי אנגערופן „שיחה\" (ווי עס שטייט<sup data-n=\"58\">58</sup> „הוא שח ויהי\").",[["53","53","וי״ל דבאברהם נזכר יום ובשרה — שנה, דיום הוא בז״א (ול׳ זכר) ושנה במל׳ (ול׳ נקבה)."],["54","54","ראה שהש״ר פ״א, ג: כל השירות שאמרו לפניך האבות ריחות היו כו׳. ובד״ה לריח שמניך תשי״ז בתחלתו: שירים קאי על התורה .. שכל ענין לימוד התורה שלהם הוא רק ריחות לבד."],["55","55","קידושין לב, רע״ב. ע״ז יט, א."],["56","56","ראה בארוכה אוה״ת פרשתנו קכט, סע״א ואילך."],["57","57","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380187\" data-slug=\"likkutei-torah\" data-id=\"4001380187\">זח״ג קמט, ב</a>. וראה בארוכה לקו״ת אחרי כה, ד."],["58","58","פיוט ד״ה ויהיוהכ״פ — הובא באוה״ת שם (קכט, ב)."]]],[1300201344,"און וויבאלד אז אלע ענינים שלמעלה ווערן נמשך דורך די ענינים אין עבודת האדם וואס זיינען בדוגמתם (וכפי׳ הה״מ<sup data-n=\"59\">59</sup> ואדה״ז<sup data-n=\"60\">60</sup> בהמשנה<sup data-n=\"61\">61</sup> „דע מה למעלה (הוא) ממך\") — דעריבער, איז בכדי צו „אויפטאן\", כביכול, די „שיחה\" למעלה, די עשרה מאמרות — איז ניט מספיק דער ענין פון לימוד התורה, נאר עס דארף זיין די עבודה פון „שיחתן\", אז אידן זאלן זיך פארנעמען מיט עניני העולם („מילין דהדיוטא\"<sup data-n=\"62\">62</sup>) אין אן אופן פון „וכל מעשיך יהיו לשם שמים\"<sup data-n=\"63\">63</sup> און „בכל דרכיך דעהו\"<sup data-n=\"64\">64</sup>\n[בדוגמת די שיחה פון אליעזר עבד אברהם, וואס אע״פ אז ער האט גערעדט ענינים פשוטים (בחיצוניות<sup data-n=\"65\">65</sup>) און צו אנשים פשוטים (לבן און בתואל), איז אבער געווען ניכר בגילוי אז ער רעדט עס מצד דעם וואס ער איז פון „עבדי אבות\", עבדו של אברהם, און ווי ער האט געזאגט גלייך בתחילת וראשית דיבורו „עבד אברהם אנכי\"<sup data-n=\"66\">66</sup>]\nוואס דורך דעם טוט מען אויף אויך למעלה די „שיחה\" אין „ענינים פשוטים\" („מילין דהדיוטא\"), אז דער אויבערשטער זאל „זאגן\" די עשרה מאמרות — עס זאל זיין דער „המחדש<sup data-n=\"67\">67</sup> בטובו בכל יום תמיד מעשה בראשית\".\nכ. דאס איז אויך איינער פון די ביאורים אין דעם וואס „שיחתן (של עבדי אבות)\" איז געשריבן אין תורה באריכות, „שנים וג׳ דפים\"<sup data-n=\"68\">68</sup> — ניט ווי „תורתן (של בנים)\", וואס „הרבה גופי תורה<sup data-n=\"20\">20</sup> לא ניתנו אלא ברמיזה\":\nוויבאלד אז די וועלט, עלמא דאתגליא, מוז אנקומען בכל יום פון אלע ימי ההיקף און בכל מקום פון די מעשה בראשית צו די עשרה מאמרות<sup data-n=\"69\">69</sup>, צו די „שיחה\" שלמעלה — דארף דעריבער זיין אויך די עבודה פון „שיחתן\" [דער „מעשיך\" און „דרכיך\", אין אן אופן פון „לשם שמים\" און „דעהו\"] אין אן אופן פון „אריכות\"<sup data-n=\"70\">70</sup>.\nמשא״כ די עבודה פון „תורתן\", לימוד התורה (און קיום מצוותי׳) — וויבאלד אז תורה איז חכמתו ורצונו של הקב״ה וואס איז העכער פון עולם און ניט אין דער מדידה פון עולם (און דער לימוד התורה (וקיום המצוות) איז בכדי צו",[["59","59","אור״ת קיב, ב."],["60","60","סה״ש תש״ד ע׳ 23. היום יום ע׳ נג."],["61","61","אבות פ״ב מ״א."],["62","62","באוה״ת שם, ש„שיחה\" הו״ע התפלה. אבל יש לומר, שבכללות — גם העסק בענינים גשמיים („לשם שמים\") נכלל ב„שיחה\". וכ״מ מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650188\" data-slug=\"or-hatorah-hb\" data-id=\"8316650188\">אוה״ת נ״ך (כ״ב) ע׳ תתקיז</a>, שמקשר ענין „כל העוסק בתורה נכסיו מצליחין לו\" עם ענין „שיחת חולין של ת״ח\" [ובפרט לפי המובא לקמן הערה 86 ש„שיחת חולין של ת״ח\" שייך לענין „יפה שיחתן כו׳\"]. ועפ״ז יש לתווך בפשטות הביאור באוה״ת שם עם מש״כ במעלת ופעולת עמל מלאכה (ששת ימים תעשה מלאכה) — בד״ה אר״א כל אדם לעמל נברא תרפ״ט. ולהעיר גם מזה ש„שיחתן של עבדי אבות\" (בפשטות) אינה ענין תפלה (שהרי תפלת אליעזר „הקרה נא גו׳\" היא רק כמה פסוקים)."],["63","63","אבות פ״ב מי״ב."],["64","64","משלי ג, ו."],["65","65","משא״כ בפנימיות — שהרי דברי אליעזר הם פרשה בתורה. וראה זח״ג קנב, א."],["66","66","פרשתנו כד, לד."],["67","67","נוסח התפלה — סוף ברכת יוצר."],["68","68","ב״ר פ״ס, ח."],["69","69","ראה בארוכה שעהיוה״א בתחלתו. ובכ״מ."],["70","70","ראה רמב״ם הל׳ דעות ספ״ג: המהלך בדרך זו כל ימיו עובד את ה׳ תמיד. *) משא״כ בפרטיות, שאז מחלקים בין „(עמל) מלאכה, שיחה, תורה\" — ראה ד״ה אר״א כו׳ שבפנים ההערה. ובכ״מ. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161093\" data-slug=\"likkutei-sichot\" data-id=\"1300161093\">לקו״ש חט״ז ס״ע 93</a> ואילך."]]],[1300201345,"ממשיך זיין אין וועלט אן „אור חדש\" וואס איז העכער פון עולם<sup data-n=\"71\">71</sup> — איז דעריבער גענוג א רמיזא, די לחכימא (ועניניו) ברמיזא<sup data-n=\"72\">72</sup>.\nכא. עפ״ז וועט מען אויך פארשטיין וואס עס שטייט „יפה שיחתן כו׳ מתורתן כו׳\", און ווי דאס איז ניט בסתירה צו דעם וואס שטייט אז „(עמל) תורה איז העכער פון „(עמל) שיחה\"<sup data-n=\"73\">73</sup> — ווייל ס׳איז דא א מעלה אין תורה אויף שיחה, און א מעלה אין שיחה אויף תורה:\nדי מעלה אין עמל תורה אויף עמל שיחה איז — וואס דורך עמל שיחה איז מען ממשיך (כנ״ל סעיף כ) (בלויז) די שיחה שלמעלה, די עשרה מאמרות וואס זיינען „מילין דהדיוטא\". משא״כ דורך עמל תורה איז מען ממשיך (כנ״ל שם) אן „אור חדש\" וואס איז העכער פון עולם:\nעס איז דא אבער אויך א יתרון אין „שיחתן\" אויף „תורתן\"<sup data-n=\"74\">74</sup>, ווייל וויבאלד אז דורך דעם טוט מען אויף דעם „המחדש כו׳ תמיד מעשה בראשית\" (וואס אין דעם איז ניטא קיין שינוי) — דריקט זיך דורך דעם אויס דער ענין פון „לא<sup data-n=\"75\">75</sup> שניתי\".\nכב. דאס איז אויך דער קשר און „צד השוה\" פון „פרשה של שיחת אליעזר\" מיטן ענין „ואברהם זקן בא בימים\" [וואס קומט בתור הקדמה צו דער פרשה<sup data-n=\"18\">18</sup>], און אויך מיט „חיי שרה\" [וואס די פרשה של שיחת אליעזר איז א טייל פון דער סדרה „חיי שרה\"]:\nדי מעלה פון „שני חיי שרה\" אויף דעם ענין פון „פרחה נשמתה\", און אזוי אויך די מעלה פון „בא בימים\" אויף „זקן\", איז (כנ״ל<sup data-n=\"76\">76</sup> בארוכה) מצד דערויף וואס דורך דער עבודה פון „שני חיי שרה\" און די עבודה פון „בא בימים\" — צו אויפטאן אין דעם זמן אז ער זאל זיין בשלימות [אז די „שני חיי שרה\" זאלן זיין „כולן שוין לטובה\" און אז די „ימים\" זאלן זיין „יומין שלימין\"] טוט מען אויף דעם בירור ותיקון העולם, וואס דער גדר פון עולם איז (מקום און) זמן<sup data-n=\"77\">77</sup> — ניט ווי דער ענין פון „פרחה נשמתה\" און „עתיק יומין\" („זקן\") וואס ער איז נעתק ונבדל פון יומין<sup data-n=\"52\">52</sup>;\nאון אויך די מעלה פון „שיחתן\" אויף „תורתן\" איז (כנ״ל סכ״א) מצד דערויף וואס (דוקא) די עבודה פון „שיחתן\" איז פארבונדן און טוט אויף אין עולם.\nכג. דער טעם פון דעם וואס מען פארבינדט דעם ענין פון „שיחתן\" וואס טוט אויף די („שיחה\" שלמעלה —) עשרה מאמרות שבהם נברא העולם מיט זמן דוקא [„שני חיי שרה\" און „בא",[["71","71","אוה״ת פרשתנו שם. ובכ״מ."],["72","72","וכיון שדי ברמיזא — הרי הוספה ע״ז, כל יתר — כנטול דמי."],["73","73","סנהדרין צט, ב."],["74","74","להעיר גם מאוה״ת שם (סע״ב ואילך) שמקשר „ענין חסידים הראשונים שהיו שוהין בתפלתן תשעה שעות ביום ובטלו עסק התורה זמן רב בכל יום [היינו, דתפלה (=שיחה — ראה לעיל הערה 62) הי׳ אצלם זמן ארוך יותר מתורה] עם ענין יפה שיחתן כו׳ מתורתן כו׳\"."],["75","75","מלאכי ג, ו. ולהעיר מהמדובר כמ״פ (וראה גם ד״ה החדש תרס״ו) בענין המעלה שבהנהגה טבעית על הנהגה ניסית, שמכיון שהנהגת הטבע היא באופן ד„לא ישבותו\" נגלה בה ענין „לא שניתי\" — והרי מהענינים שבאים ע״י התורה הו״ע הנהגה ניסית (ראה אוה״ת שם (קכט, ב): „עמל תורה כו׳ שאף התנאים ואמוראים היו עושים ניסים מופלאים\")."],["76","76","בהמאמר סעיף ח׳ וט׳. לעיל (בהשיחה) סעיף יד וטז."],["77","77","שעהיוה״א פ״ז (פב, א). וראה לקמן סוף סעיף כג. *) <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171153\" data-slug=\"likkutei-sichot\" data-id=\"1300171153\">לקו״ש חי״ז ע׳ 153</a>. לעיל ע׳ 34־5."]]],[1300201346,"בימים\"] — אע״פ אז דער גדר פון עולם איז ניט נאר זמן נאר אויך מקום<sup data-n=\"78\">78</sup>:\nיעדע „התהוות\" [כולל אויך התהוות פון מקום] איז א „שינוי\" לגבי קודם<sup data-n=\"79\">79</sup> ההתהוות<sup data-n=\"80\">80</sup>. ובמילא קומט אויס, אז פאר יעדער התהוות (אויך די התהוות פון מקום), איז שוין געווען די מציאות פון א ענין וואס איז דערנאך נשתנה געווארן — וואס דאס איז (תוכן ענין ה)זמן.\n[ואע״פ אז זמן איז פארבונדן מיט מקום<sup data-n=\"81\">81</sup> [כמובן אויך פון דעם וואס שטייט אין תניא<sup data-n=\"82\">82</sup> אז ביידע (זמן און מקום) נעמען זיך פון זעלבן שרש, ספירת המלכות] — אעפ״כ איז מובן (כנ״ל) אז אין דעם גופא קומט זמן פאר מקום].\nועפ״ז איז פארשטאנדיק וואס מען איז מדגיש בעיקר די עבודה פון אויפטאן אין זמן — „יומין שלימין\" — ווייל די ערשטע מציאות פון עולם [וואס פון איר פאנגען זיך אן אלע נמצאים] איז זמן.\nכד. נאך אן ענין אין דער שייכות פון „יפה שיחתן כו׳\" מיטן ענין פון זמן [„שני חיי שרה\" און „בא בימים\"]:\nדי עשרה מאמרות — די „שיחה\" שלמעלה, מיט דער שלימות שבזה<sup data-n=\"83\">83</sup> וואס איז געקומען דורך (דער מנוחה פון) שבת, וואס טוט זיך אויף כביכול דורך דער עבודה פון „שיחתן\" — איז געווען במשך פון זיבן טעג — שבעת ימי ההיקף וואס זיינען כולל דעם גאנצן מציאות פון זמן<sup data-n=\"84\">84</sup>.\nאון נאך מער: יעדער אמירה פון די עשרה מאמרות איז געווען פארבונדן מיט א זמן (יום) מיוחד, ווי עס שטייט אין זהר<sup data-n=\"85\">85</sup>: „כל יומא ויומא עביד עבידתי׳\", און זייער שלימות — מיט יום השבת.\nועפ״ז קומט אויס, אז די שייכות פון דער „שיחה\" שלמעלה (וואס קומט דורך דער עבודה פון „שיחתן\") צום ענין הזמן איז [ניט נאר מצד דערויף ווייל דער עולם וואס ווערט נתהווה פון די עשרה מאמרות („שיחה\") איז און הויבט זיך אן מיטן מציאות פון זמן (כנ״ל סכ״ג), נאר אויך] מצד דערויף וואס די עשרה מאמרות גופא זיינען פארבונדן מיט זמן.\nכה. פון די הוראות וואס קומען צו אין „פרשה של שיחת אליעזר\" אויף „שני חיי שרה\" און „ואברהם זקן בא בימים\" — איז דער דיוק פון „יפה שיחתן של עבדי אבות כו׳\":\nדער לשון „עבדי אבות\" איז א טעם אויף דעם „יפה\" — אז דאס וואס „יפה שיחתן של עבדי אבות כו׳ מתורתן של בנים\" איז עס ניט נאר מצד דער מעלה וואס איז דא אין שיחה לגבי תורה נאר אויך מצד דעם יתרון וואס איז דא אין „עבדים\" אויף „בנים\".\nדאס הייסט, אז אע״פ אז די מעלה וואס איז דא אין שיחה לגבי תורה, איז",[["78","78","עוד טעם על זה — ראה בהמאמר סעיף ח ובהערה 67."],["79","79","שזה שייך לומר אפילו בהתהוות דרגע הראשון דהזמן, אף שאין שייך להיות עבר ממש — כיון שזהו מגדרי הזמן. אבל יש בזה קדימה ואיחור — ע״ד סיבה ומסובב בשכל. ועוד."],["80","80","ראה גם המשך תער״ב ח״א ע׳ שלט: דכל מה שנתהווה ה״ז בבחי׳ זמן .. שנתהווה מן ההעדר .. להיות הי׳ זמן שלא הי׳ ונתהווה ונתחדש."],["81","81","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו״ת ברכה צח, א</a>."],["82","82","שעהיוה״א שם."],["83","83","וכמרז״ל הובא בפרש״י עה״ת (בראשית ב, ב): מה הי׳ העולם חסר מנוחה כו׳. ובב״ר (פ״י, ט) ששבת הוא כמו החותם בטבעת — והרי החותם משנה כל הטבעת."],["84","84","ראה לעיל ע׳ 281־2 ובהנסמן שם בהערה 18."],["85","85","ח״ג צד, ב."]]],[1300201347,"אויך דא בשיחתן של בנים לגבי תורתן<sup data-n=\"86\">86</sup> — פונדעסטוועגן, איז דער אמתית היופי אין דער שיחה פון עבדים.\nכו. דער ביאור אין דעם:\nדי עבודה פון אן עבד (ע״ד הרגיל<sup data-n=\"87\">87</sup> איז — אן „עבודה גרועה\" (אזוי ווי חטיבת עצים וכה״ג), וואס איז ניט „מכבוד האדון לעשות בעצמו\". וואס אין עבודת ה׳ איז דאס דער ענין פון עבודת הבירורים, וואס אידן פארנעמען זיך מיט עניני העולם ובפרט אין „מעשיך\" און „דרכיך\", וואס איז בא עם אין אן אופן פון „לשם שמים\" און „דעהו\". וואס דורך דעם טוען זיי אויף (כנ״ל סעיף יט) למעלה דעם ענין פון עשרה מאמרות — וואס דאס איז א ירידה והשפלה (בדוגמת „עבודה גרועה\") כביכול לגבי דעם אויבערשטן, ווארום „לאו<sup data-n=\"57\">57</sup> אורחא דמלכא לאשתעי במילי דהדיוטא\"<sup data-n=\"88\">88</sup>.\nאון דאס איז דער יתרון אין „שיחתן של עבדים\" אויף „שיחתן של בנים\":\nדאס וואס אידן ווערן אנגערופן מיטן נאמען „בנים\" — איז עס פארבונדן מיטן ענין פון תורה<sup data-n=\"89\">89</sup> [כמובן אויך פון דעם וואס שטייט אין תניא<sup data-n=\"90\">90</sup>, אז דאס וואס נשמות ישראל זיינען „בנים\", איז עס מצד דערויף וואס זיי ווערן נמשך פון „מחשבתו וחכמתו ית׳\", בדוגמא ווי א בן וואס ווערט נמשך פון „מוח האב\"].\nאון דעריבער איז אויך „שיחתן של בנים\" פארבונדן מיט תורה\n[בדוגמת „שיחת חולין<sup data-n=\"91\">91</sup> של תלמידי חכמים\"<sup data-n=\"92\">92</sup>, וואס וויבאלד אז דאס איז א שיחת חולין פון תלמידי חכמים — איז „צריכין לימוד\"<sup data-n=\"93\">93</sup> מצד דערויף וואס זי איז די „נובלות\" פון זייער חכמה („מותרי מוחין\")<sup data-n=\"94\">94</sup>],\nדאס הייסט, אז ווען תלמידי חכמים („בנים\") טוען אין עניני העולם [וואס דאס איז דער ענין פון זייער „שיחתן\" (כנ״ל שם)] — איז עס ניט דער תחתון שאין תחתון למטה ממנו, (ניט אמיתית הענין) פון „מעשיך\" און „דרכיך\" [ובמילא ניט דער אמיתית הענין פון „עולם\" מלשון העלם<sup data-n=\"95\">95</sup>], וויבאלד אז זייער עסק בעניני העולם (מלכתחילה) איז נאר צוליב תורה<sup data-n=\"96\">96</sup>, אדער בל׳",[["86","86","שלכן, הענין ד„יפה שיחתן\" מובא גם לענין „שיחת חולין של ת״ח\" ולענין „האגדות שבגמרא\" (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600482\" data-slug=\"or-hatorah-hb\" data-id=\"8316600482\">אוה״ת נ״ך ע׳ תפב</a>). ולהעיר, שכ״ה גם בפשוטו של מקרא — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161475\" data-slug=\"likkutei-sichot\" data-id=\"1300161475\">לקו״ש חט״ז ע׳ 462</a>, דזה מה שלא הוזקק רש״י לפרש הטעם מה שמעשה המשכן נכפל כמה פעמים הוא לפי שסיפור מעשה המשכן הר״ע של „שיחה\", ולכן מבין זה ה„בן חמש (למקרא)\" ממה שכבר פירש רש״י בפ׳ ח״ש."],["87","87","בהמשך תרס״ו שבהערה הבאה, שיש גם עבד „שעובד במלאכות דקים ושכליים שהאדון בעצמו הי׳ עושה\". אבל מובן שעבד זה אינו ע״ד הרגיל [ובפרט לפי המבואר שם ע׳ שלב, שהרע״ע „עבד נאמן\"]."],["88","88","ראה בכ״ז המשך תרס״ו ע׳ ל־לב."],["89","89","ראה המשך הנ״ל ע׳ שסד. ובכ״מ."],["90","90","רפ״ב."],["91","91","כ״ה הלשון בע״ז יט, ב. וכ״ה גם לפי גירסא אחת בסוכה כא, ב. וכן מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650188\" data-slug=\"or-hatorah-hb\" data-id=\"8316650188\">אוה״ת נ״ך (כ״ב) ע׳ תתקיז</a> מסוכה שם *."],["92","92","וראה לעיל הערה 86, שזה שייך לענין „יפה שיחתן כו׳\"."],["93","93","סוכה שם. ובע״ז שם: צריכה תלמוד. וכ״ה לפי כמה גירסאות גם בסוכה שם (ראה דק״ס שם). ושם, שמחמת הצענזאר שינו מ„תלמוד\" ל„לימוד\" — ראה דק״ס מאמר על הדפסת התלמוד דפוס בסיליאה הערה צג (7))."],["94","94","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380928\" data-slug=\"likkutei-torah\" data-id=\"4001380928\">לקו״ת נצבים נב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380865\" data-slug=\"likkutei-torah\" data-id=\"4001380865\">תצא לז, א</a>."],["95","95","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380459\" data-slug=\"likkutei-torah\" data-id=\"4001380459\">לקו״ת שלח לו, ד</a>. ובכ״מ."],["96","96","ראה אוה״ת נ״ך שם שהטעם מה ש„כל העוסק בתורה נכסיו מצליחין לו\" (ע״ז שם), הוא „כי נמשך לו רק בשביל עסק התורה\". ושם לפנ״ז: „גם *) להעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380928\" data-slug=\"likkutei-torah\" data-id=\"4001380928\">לקו״ת נצבים נב, ב</a>: ארז״ל שיחת חולין של ת״ח צריכין לימוד, שכוונתו לכאורה היא למרז״ל בסוכה שם (מכיון שהלשון בע״ז הוא „תלמוד\" ולא „לימוד\")."]]],[1300201348,"הרמב״ם<sup data-n=\"97\">97</sup> אין אן אופן אז „במאכלו וכו׳\" איז החכם ניכר (וואס דאס איז היפך העולם).\nאון וויבאלד אז די כוונה פון „דירה בתחתונים\" איז אז אויך די עניני העולם („עולם\" מלשון העלם) וועלכע הערן זיך אן פאר א מציאות לעצמם זאלן ווערן א דירה לו ית׳ — דעריבער איז דא א יתרון<sup data-n=\"98\">98</sup> אין דער עבודה פון „שיחתן של עבדים\", וואס זייערע עניני הרשות זיינען „מעשיך\" און „דרכיך\" ממש [וויבאלד אז זיי טוען עס מצד זייער טבע, וואס א מענטש איז מתאוה בטבעו<sup data-n=\"99\">99</sup> צו ענינים גשמיים].\nדורך דעם וואס א איד פועל׳ט אז זיין אכילה ושתי׳ וכיו״ב, אויך ווען ער איז אויסן די „גשמיות\" דערפון, זאלן זיין „לשם שמים\" ביז אין אן אופן פון „דעהו\" — פועל׳ט ער אויך אין די („תחתונים\", „שאין תחתון למטה מהם\") — די עניני העולם וואס הערן זיך אן פאר א מציאות לעצמם, אז זיי זאלן ווערן א דירה לו ית׳.\nכז. ענין הנ״ל אין „שיחתן של עבדים\" איז פארבונדן אויך דערמיט וואס די עבודה פון אן עבד איז בדרך קבלת עול<sup data-n=\"100\">100</sup>.\nווארום ווי איז עס טאקע מעגליך, אז אויך אכו״ש וכיו״ב וואס ער טוט מצד דערויף וואס בטבעו איז ער מתאוה צו זיי, זאלן זיין „לשם שמים\" —\nאיז עס (בלויז) מצד דערויף וואס אן עבד פאלגט אויס דעם ציווי האדון בדרך קבלת עול, און דעריבער — איז ער מקיים דעם ציווי „וכל מעשיך יהיו לשם שמים\" מצד קבלת עול מלכות שמים<sup data-n=\"101\">101</sup>.\nכח. וויבאלד אז בא יעדער אידן דארפן זיין אלע סארטן עבודות, דעריבער, איז אויך בא בעלי עסקים [וואס זיינען בדוגמת „עבדים\", וואס פארנעמען זיך מיט „עבודה גרועה\" — ובפרט בערך התורה] דארף זיין דער ענין פון עסק התורה\n[בדוגמת ווי אליעזר וואס אע״פ אז ער איז געווען „עבד אברהם\", איז ער געווען „דולה ומשקה מתורת רבו\"<sup data-n=\"102\">102</sup>]\nאון אז דער עסק התורה זאל זיין ניט נאר בדרך קבלת עול (מצד דעם חיוב",[["","","החולין שלו נק׳ חולין שנעשו על טהרת הקודש .. אינו חול ממש אלא כמו חול המועד\"."],["97","97","הל׳ דעות רפ״ה."],["98","98","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051087\" data-slug=\"likkutei-sichot\" data-id=\"1300051087\">לקו״ש ח״ה ע׳ 75</a> ואילך בענין המעלה של הפרשת מעשר של אברהם על הפרשת מעשר דיצחק — כי זריעת הדגן דיצחק הי׳ מלכתחילה בשביל הפרשת מעשר."],["99","99","שלפעמים תאוה זו (משא״כ תאוה חומרית) צ״ל בשביל קיום העולם (ראה יומא סט, ב: נקטלי׳ (ליצרא דעבירה) כליא עלמא)."],["100","100","ראה לעיל סעיף כו, שענין „שיחתן של עבדים\" הוא דוגמת מה שהעבד עובד „עבודה גרועה\" (כמו חטיבת עצים) שאינה „מכבוד האדון לעשות בעצמו\". וראה המשך הנ״ל ע׳ שלב, שעבודה זו שייכת לעבד פשוט (משא״כ העבודה דנקיבת מרגליות וכיו״ב שייכת לעבד נאמן). ועפ״ז מודגשת יותר השייכות ד„שיחתן של עבדים\" לענין הקב״ע — כי ענין הקב״ע הוא (בעיקר) בעבד פשוט, כמבואר בהמשך הנ״ל ע׳ שי ואילך."],["101","101","והגם שזה גופא מה שעסקו בעניני רשות הוא מצד זה שבטבעו הוא מתאוה לזה, מורה לכאורה שכוונתו בזה היא לתועלת עצמו (ולא לשם שמים), מ״מ מצד הקבלת עול שלו יכול לפעול בעצמו שכוונתו „לשם שמים\" תהי׳ באמת — כי מכיון שעבד הפשוט הוא בטל „בכל עצם מהותו כאילו .. אינו נברא בעולם רק למלאכה ושירות לאדונו וה״ה נחשב כרכושו וקנין כספו ממש\" (המשך הנ״ל שם), לכן שייך, שכוונתו „לשם שמים\" תהי׳ באמת גם בענינים אלו שעשייתם (לכתחילה) היא לתועלת עצמו — מכיון שגם מהות עצמו שלו הוא „רק למלאכה ושירות לאדונו\". ועצ״ע."],["102","102","פרש״י לך לך טו, ב."]]],[1300201349,"פון מצות תלמוד תורה), נאר אז ער זאל האבן א געשמאק אין דעם — אזוי ווי א „בן\" וואס זיין ענין איז תורה;\nאון אזוי אויך לאידך גיסא: אויך בא די וואס זיינען בבחינת „בנים\", דארף זיין זייער עבודה (ניט מצד זייער געשמאק, נאר) מצד קבלת עול מלכות שמים — כשם ווי מען וואלט מקיים געווען דעם ציווי פון אויבערשטן „אילו נצטווינו לחטוב עצים\", מצד קבלת עול<sup data-n=\"103\">103</sup>.\nאעפ״כ איז דא א חילוק וואס איז דער עיקר: בא בנים איז דער עיקר חכמתו ית׳ (קיום באהבה<sup data-n=\"104\">104</sup> תורה, בא עבדים — קבלת עול (עבודה ביראה), לחטוב עצים, שיחה,\nאון „כל אדם צ״ל בשתי בחי׳ ומדריגות\"<sup data-n=\"104\">104</sup> הנ״ל.\n* * *\nכט. די הוראה עיקרית בנוגע לפועל פון כל האמור לעיל אין פשוט׳ע אותיות, און בנוגע צו „ויעקב הלך לדרכו\" — איז אין צוויי ענינים:\nא) די הדגשה אין „לדרכו\" — אז ס׳איז ניט מספיק דער „ויעקב הלך לדרכו\" לויטן פירוש<sup data-n=\"105\">105</sup> פון „לדרכו\" — „בחי׳ תורה ומצות, דתורה אקרי<sup data-n=\"106\">106</sup> דרך\", נאר עס דארף זיין אויך די הליכה „לדרכו\" בפשטות — אין די עניני העולם ועובדין דחול, צו מאכן (אויך) פון זיי א דירה לו ית׳.\nווי גערעדט פריער בארוכה, אז דער צד השוה פון אלע דריי ענינים כלליים פון היינטיקער סדרה [„שני חיי שרה\", „בא בימים\" און „יפה שיחתן\"] איז — די הדגשה אז מען דארף אויפטאן אין די עניני העולם.\nב) די הדגשה אין „הלך\" — אז מען דארף גיין בזריזות, און האלטן אין גיין און ניט אפשטעלן זיך אויף קיין איין רגע. ווארום וויבאלד אז אלע דריי ענינים הנ״ל [כולל אויך דעם ענין פון „יפה שיחתן\"<sup data-n=\"107\">107</sup>] זיינען מדגיש דעם גודל החשיבות פון זמן — איז דאך פארשטאנדיק אז מען דארף מייקר זיין כל רגע.\nאון וויבאלד אז ביידע הוראות זיינען מודגש אין דער סדרה (וואס מען האט היינט געלייענט) דריי מאל, וואס „בתלתא זימני הוי חזקה\"<sup data-n=\"108\">108</sup> — איז דאך פארשטאנדיק דער חיזוק וגודל הנתינת כח וואס די סדרה גיט צו יעדער אידן אויף דורכפירן בפועל כל הוראות הנ״ל.\nל. אזוי ווי המעשה הוא העיקר — איז דער סיכום פון די הוראות הנ״ל בנוגע למעשה בפועל:\nא איד זאל זיך ניט מסתפק זיין מיט דעם וואס ער אליין פירט זיך כדבעי, און אפילו ניט מיט דעם וואס ער פארנעמט זיך מיט אזוינע אידן וואס זיינען בערכו, נאר בכל מקום ומקום, ביז אין דעם מקום הכי תחתון (ברוחניות), דארף ער מפיץ זיין תורה ויהדות, אנהויבענדיק פון די ענינים כלליים,\nוואס הויבן זיך אן מיט „מבצע אהבת ישראל\", און דערנאך קומט דאס אראפ אין „מבצע חינוך\", „מבצע תורה\", „מבצע תפילין\", „מבצע מזוזה\", „מבצע צדקה\", און „בית מלא ספרים — יבנה וחכמי׳\",",[["103","103","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380472\" data-slug=\"likkutei-torah\" data-id=\"4001380472\">לקו״ת שלח מ, א</a>. המשך תרס״ו ע׳ נד."],["104","104","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ״א</a>."],["105","105","תו״א ס״פ ויצא."],["106","106","קידושין ב, ב."],["107","107","ראה לעיל סעיף כד."],["108","108","ב״מ קו, ב."]]]]});
